package com.osrsflipper.sync;

import com.google.gson.Gson;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.channels.OverlappingFileLockException;
import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import java.util.PriorityQueue;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Local, ordered storage for immutable GE events. An event is published only
 * after its temporary file has been forced to disk and atomically renamed.
 * Unacknowledged files survive restart; a crash before acknowledgement can
 * replay the same event ID, which the Worker must handle idempotently.
 *
 * The caller supplies the complete owner/endpoint/device/RuneScape context.
 * Only its hash is used in paths. Retry counters belong to the caller and must
 * not be included in the immutable event JSON.
 */
final class EventJournal
{
    static final int MAX_HEAD_ENTRIES = 500;
    private static final int FORMAT_VERSION = 1;
    private static final Pattern EVENT_FILE =
        Pattern.compile("([0-9]{20})_([0-9a-f]{64})\\.json");

    private final Gson gson;
    private final Path directory;

    EventJournal(Path root, String contextKey, Gson gson) throws IOException
    {
        if (root == null || contextKey == null || contextKey.trim().isEmpty())
        {
            throw new IllegalArgumentException(
                "A journal root and complete context are required");
        }

        this.gson = Objects.requireNonNull(gson, "gson");
        directory = root.toAbsolutePath().normalize().resolve(hash(contextKey));
        Files.createDirectories(directory);
    }

    synchronized void append(String eventId, String eventJson) throws IOException
    {
        validate(eventId, eventJson);
        try (LockedDirectory ignored = lock())
        {
            appendLocked(eventId, eventJson);
        }
    }

    private void appendLocked(String eventId, String eventJson) throws IOException
    {
        validate(eventId, eventJson);

        long maximumSequence = 0;
        String eventHash = hash(eventId);

        try (DirectoryStream<Path> files =
                 Files.newDirectoryStream(directory, "*.json"))
        {
            for (Path file : files)
            {
                Matcher name = eventFile(file);
                maximumSequence =
                    Math.max(maximumSequence, sequence(name, file));

                if (eventHash.equals(name.group(2)))
                {
                    Entry existing = read(file);

                    if (!eventId.equals(existing.eventId)
                        || !eventJson.equals(existing.eventJson))
                    {
                        throw new IOException(
                            "Event ID already has a different immutable payload");
                    }

                    return;
                }
            }
        }

        if (maximumSequence == Long.MAX_VALUE)
        {
            throw new IOException("Event journal sequence exhausted");
        }

        Record record = new Record();
        record.version = FORMAT_VERSION;
        record.eventId = eventId;
        record.eventJson = eventJson;
        record.payloadHash = hash(eventJson);

        Path destination = directory.resolve(
            String.format(
                Locale.ROOT,
                "%020d_%s.json",
                maximumSequence + 1,
                eventHash));

        writeAtomic(destination, gson.toJson(record));
    }

    /** No dispatch is allowed until this entire migration has committed. */
    synchronized boolean legacyImported() throws IOException
    {
        return legacyImported("default");
    }

    synchronized boolean legacyImported(String sourceKey) throws IOException
    {
        try (LockedDirectory ignored = lock())
        {
            return Files.exists(legacyMarker(sourceKey));
        }
    }

    synchronized void importLegacy(
        List<Entry> entries,
        String stateJson) throws IOException
    {
        importLegacy(entries, stateJson, "default");
    }

    synchronized void importLegacy(
        List<Entry> entries,
        String stateJson,
        String sourceKey) throws IOException
    {
        try (LockedDirectory ignored = lock())
        {
            Path marker = legacyMarker(sourceKey);

            if (Files.exists(marker))
            {
                return;
            }

            for (Entry entry : entries)
            {
                appendLocked(entry.eventId, entry.eventJson);
            }

            if (stateJson != null
                && !Files.exists(directory.resolve(".account-state")))
            {
                writeAtomic(directory.resolve(".account-state"), stateJson);
            }

            writeAtomic(marker, "1");
        }
    }

    private Path legacyMarker(String sourceKey)
    {
        return directory.resolve(".legacy-imported-" + hash(sourceKey));
    }

    synchronized String readState() throws IOException
    {
        try (LockedDirectory ignored = lock())
        {
            Path state = directory.resolve(".account-state");

            return Files.exists(state)
                ? Files.readString(state, StandardCharsets.UTF_8)
                : null;
        }
    }

    synchronized void writeState(String stateJson) throws IOException
    {
        try (LockedDirectory ignored = lock())
        {
            writeAtomic(directory.resolve(".account-state"), stateJson);
        }
    }

    /** Bind pre-upgrade configuration once, before a pairing can change owner. */
    static String claimLegacyConnection(
        Path root,
        String proposed,
        Gson gson) throws IOException
    {
        return claimLegacyConnection(root, "default", proposed, gson);
    }

    static String claimLegacyConnection(
        Path root,
        String profileKey,
        String proposed,
        Gson gson) throws IOException
    {
        // A separate journal supplies the same cross-process lock and atomic writes.
        EventJournal binding = new EventJournal(
            root,
            "legacy-connection-binding-v1:" + profileKey,
            gson);

        synchronized (binding)
        {
            try (LockedDirectory ignored = binding.lock())
            {
                Path marker = binding.directory.resolve(".connection");

                if (!Files.exists(marker))
                {
                    writeAtomic(marker, proposed);
                }

                return Files.readString(marker, StandardCharsets.UTF_8);
            }
        }
    }

    private static void writeAtomic(
        Path destination,
        String value) throws IOException
    {
        Path temporary = Files.createTempFile(
            destination.getParent(),
            ".state-",
            ".tmp");

        try
        {
            try (FileChannel channel = FileChannel.open(
                temporary,
                StandardOpenOption.WRITE))
            {
                ByteBuffer buffer =
                    ByteBuffer.wrap(value.getBytes(StandardCharsets.UTF_8));

                while (buffer.hasRemaining())
                {
                    channel.write(buffer);
                }

                channel.force(true);
            }

            Files.move(
                temporary,
                destination,
                StandardCopyOption.ATOMIC_MOVE,
                StandardCopyOption.REPLACE_EXISTING);
        }
        finally
        {
            Files.deleteIfExists(temporary);
        }
    }

    synchronized List<Entry> readHead(int limit) throws IOException
    {
        if (limit < 0)
        {
            throw new IllegalArgumentException(
                "Head size cannot be negative");
        }

        if (limit == 0)
        {
            return Collections.emptyList();
        }

        try (LockedDirectory ignored = lock())
        {
            List<Entry> result = new ArrayList<>();

            for (Path file :
                headFiles(Math.min(limit, MAX_HEAD_ENTRIES)))
            {
                result.add(read(file));
            }

            return Collections.unmodifiableList(result);
        }
    }

    synchronized boolean acknowledge(
        String expectedHeadId) throws IOException
    {
        if (expectedHeadId == null || expectedHeadId.isEmpty())
        {
            return false;
        }

        try (LockedDirectory ignored = lock())
        {
            List<Path> head = headFiles(1);

            if (head.isEmpty()
                || !expectedHeadId.equals(read(head.get(0)).eventId))
            {
                return false;
            }

            Files.delete(head.get(0));
            return true;
        }
    }

    synchronized long size() throws IOException
    {
        try (LockedDirectory ignored = lock();
             DirectoryStream<Path> files =
                 Files.newDirectoryStream(directory, "*.json"))
        {
            long count = 0;

            for (Path file : files)
            {
                eventFile(file);
                count++;
            }

            return count;
        }
    }

    synchronized boolean isEmpty() throws IOException
    {
        try (LockedDirectory ignored = lock())
        {
            return headFiles(1).isEmpty();
        }
    }

    private List<Path> headFiles(int limit) throws IOException
    {
        Comparator<Path> order =
            Comparator.comparing(file -> file.getFileName().toString());

        PriorityQueue<Path> head =
            new PriorityQueue<>(limit, order.reversed());

        try (DirectoryStream<Path> files =
                 Files.newDirectoryStream(directory, "*.json"))
        {
            for (Path file : files)
            {
                eventFile(file);
                head.add(file);

                if (head.size() > limit)
                {
                    head.poll();
                }
            }
        }

        List<Path> ordered = new ArrayList<>(head);
        ordered.sort(order);

        return ordered;
    }

    private Entry read(Path file) throws IOException
    {
        Matcher filename = eventFile(file);

        try
        {
            Record record = gson.fromJson(
                Files.readString(file, StandardCharsets.UTF_8),
                Record.class);

            if (record == null || record.version != FORMAT_VERSION)
            {
                throw new IllegalArgumentException(
                    "Unknown event journal format");
            }

            validate(record.eventId, record.eventJson);

            if (!filename.group(2).equals(hash(record.eventId))
                || !hash(record.eventJson).equals(record.payloadHash))
            {
                throw new IllegalArgumentException(
                    "Event journal checksum mismatch");
            }

            return new Entry(record.eventId, record.eventJson);
        }
        catch (RuntimeException exception)
        {
            throw new IOException(
                "Unreadable event journal entry: " + file.getFileName(),
                exception);
        }
    }

    private static Matcher eventFile(Path file) throws IOException
    {
        Matcher matcher =
            EVENT_FILE.matcher(file.getFileName().toString());

        if (!matcher.matches()
            || !Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS))
        {
            throw new IOException(
                "Invalid event journal file: " + file.getFileName());
        }

        sequence(matcher, file);

        return matcher;
    }

    private static long sequence(
        Matcher filename,
        Path file) throws IOException
    {
        try
        {
            long value = Long.parseLong(filename.group(1));

            if (value <= 0)
            {
                throw new NumberFormatException(
                    "Nonpositive sequence");
            }

            return value;
        }
        catch (NumberFormatException exception)
        {
            throw new IOException(
                "Invalid event journal sequence: " + file.getFileName(),
                exception);
        }
    }

    private static void validate(
        String eventId,
        String eventJson)
    {
        if (eventId == null
            || eventId.trim().isEmpty()
            || eventJson == null
            || !new JsonParser().parse(eventJson).isJsonObject())
        {
            throw new IllegalArgumentException(
                "An event ID and JSON object are required");
        }
    }

    private static String hash(String value)
    {
        try
        {
            byte[] digest = MessageDigest
                .getInstance("SHA-256")
                .digest(value.getBytes(StandardCharsets.UTF_8));

            StringBuilder result =
                new StringBuilder(digest.length * 2);

            for (byte part : digest)
            {
                result.append(
                    Character.forDigit((part >>> 4) & 15, 16));
                result.append(
                    Character.forDigit(part & 15, 16));
            }

            return result.toString();
        }
        catch (NoSuchAlgorithmException exception)
        {
            throw new IllegalStateException(
                "SHA-256 is required by Java",
                exception);
        }
    }

    private LockedDirectory lock() throws IOException
    {
        FileChannel channel = FileChannel.open(
            directory.resolve(".lock"),
            StandardOpenOption.CREATE,
            StandardOpenOption.WRITE,
            LinkOption.NOFOLLOW_LINKS);

        try
        {
            FileLock lock = channel.tryLock();

            if (lock == null)
            {
                throw new IOException(
                    "Event journal is in use by another client");
            }

            return new LockedDirectory(channel, lock);
        }
        catch (IOException | OverlappingFileLockException exception)
        {
            channel.close();

            throw new IOException(
                "Could not lock the event journal",
                exception);
        }
    }

    static final class Entry
    {
        final String eventId;
        final String eventJson;

        Entry(String eventId, String eventJson)
        {
            this.eventId = eventId;
            this.eventJson = eventJson;
        }
    }

    private static final class Record
    {
        int version;
        String eventId;
        String eventJson;
        String payloadHash;
    }

    private static final class LockedDirectory
        implements AutoCloseable
    {
        private final FileChannel channel;
        private final FileLock lock;

        private LockedDirectory(
            FileChannel channel,
            FileLock lock)
        {
            this.channel = channel;
            this.lock = lock;
        }

        @Override
        public void close() throws IOException
        {
            try
            {
                lock.release();
            }
            finally
            {
                channel.close();
            }
        }
    }
}

package com.osrsflipper.sync;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Keeps the prices chosen for a flip separate from the GE slot that currently
 * contains its buy or sell offer. A slot can become EMPTY or be reused while
 * the bought items still belong to the same unfinished flip cycle.
 */
final class FlipCyclePlanBook
{
    private static final int MAX_RETAINED_CYCLES = 128;

    private final Map<String, Cycle> cycles = new HashMap<>();

    void clear()
    {
        cycles.clear();
    }

    void restore(Cycle[] persisted)
    {
        cycles.clear();
        if (persisted == null)
        {
            return;
        }
        for (Cycle raw : persisted)
        {
            Cycle cycle = sanitizedCopy(raw);
            if (cycle != null)
            {
                cycles.put(cycle.cycleId, cycle);
            }
        }
        trimClosedCycles();
    }

    Cycle[] persistedCycles()
    {
        List<Cycle> persisted = new ArrayList<>();
        for (Cycle cycle : cycles.values())
        {
            if (cycle != null)
            {
                persisted.add(cycle.copy());
            }
        }
        persisted.sort(Comparator
            .comparingLong((Cycle cycle) -> cycle.lastEventAt)
            .thenComparing(cycle -> cycle.cycleId));
        return persisted.toArray(new Cycle[0]);
    }

    void recordBuy(
        String cycleId,
        String buyOfferId,
        int slotNumber,
        int itemId,
        String itemName,
        int frozenBuyPrice,
        int sellTargetPrice,
        int lowestSellPrice,
        int totalQuantity,
        int filledQuantity,
        String status,
        long startedAt,
        long lastEventAt)
    {
        String safeCycleId = clean(cycleId);
        String safeOfferId = clean(buyOfferId);
        if (safeCycleId.isEmpty() || safeOfferId.isEmpty() || itemId <= 0)
        {
            return;
        }

        Cycle cycle = cycles.get(safeCycleId);
        if (cycle == null && ("empty".equals(status) ||
            (filledQuantity <= 0 && !isOpenStatus(status))))
        {
            return;
        }
        if (cycle == null)
        {
            cycle = new Cycle();
            cycles.put(safeCycleId, cycle);
        }
        int previousFill = cycle.buyFills.getOrDefault(safeOfferId, 0);
        boolean lifecycleChanged = clean(cycle.cycleId).isEmpty() ||
            !safeOfferId.equals(clean(cycle.currentBuyOfferId)) ||
            cycle.buyTotalQuantity != Math.max(cycle.buyTotalQuantity, Math.max(0, totalQuantity)) ||
            previousFill < Math.max(0, filledQuantity) ||
            !clean(cycle.buyStatus).equals(clean(status));
        cycle.cycleId = safeCycleId;
        cycle.currentBuyOfferId = safeOfferId;
        cycle.slotNumber = positiveOrFallback(cycle.slotNumber, slotNumber);
        cycle.itemId = itemId;
        if (!clean(itemName).isEmpty())
        {
            cycle.itemName = itemName.trim();
        }
        if (cycle.frozenBuyPrice <= 0 && frozenBuyPrice > 0)
        {
            cycle.frozenBuyPrice = frozenBuyPrice;
        }
        cycle.sellTargetPrice = SellTargetPriceResolver.raiseOnly(
            cycle.sellTargetPrice,
            sellTargetPrice);
        if (cycle.lowestSellPrice <= 0 && lowestSellPrice > 0)
        {
            cycle.lowestSellPrice = lowestSellPrice;
        }
        cycle.startedAt = cycle.startedAt > 0 ? cycle.startedAt : Math.max(0, startedAt);
        if (lifecycleChanged)
        {
            cycle.lastEventAt = Math.max(cycle.lastEventAt, Math.max(0, lastEventAt));
        }
        cycle.buyTotalQuantity = Math.max(cycle.buyTotalQuantity, Math.max(0, totalQuantity));
        cycle.buyStatus = clean(status);
        int acquiredBefore = cycle.acquiredQuantity();
        cycle.buyFills.put(
            safeOfferId,
            Math.max(cycle.buyFills.getOrDefault(safeOfferId, 0), Math.max(0, filledQuantity)));
        if (cycle.acquiredQuantity() > acquiredBefore)
        {
            cycle.lastAcquiredAt = Math.max(cycle.lastAcquiredAt, Math.max(0, lastEventAt));
        }
        if (cycle.acquiredQuantity() <= 0 && !cycle.isBuyOpen())
        {
            cycles.remove(safeCycleId);
            return;
        }
        trimClosedCycles();
    }

    void recordSell(
        String cycleId,
        String sellOfferId,
        int slotNumber,
        int itemId,
        String itemName,
        int frozenBuyPrice,
        int sellTargetPrice,
        int lowestSellPrice,
        int totalQuantity,
        int filledQuantity,
        String status,
        long startedAt,
        long lastEventAt)
    {
        String safeCycleId = clean(cycleId);
        String safeOfferId = clean(sellOfferId);
        if (safeCycleId.isEmpty() || safeOfferId.isEmpty() || itemId <= 0)
        {
            return;
        }

        Cycle cycle = cycles.computeIfAbsent(safeCycleId, ignored -> new Cycle());
        Sale existingAllocation = cycle.sales.get(safeOfferId);
        boolean lifecycleChanged = clean(cycle.cycleId).isEmpty() ||
            existingAllocation == null ||
            existingAllocation.totalQuantity != Math.max(
                existingAllocation.totalQuantity,
                Math.max(0, totalQuantity)) ||
            existingAllocation.filledQuantity < Math.max(0, filledQuantity) ||
            !clean(existingAllocation.status).equals(clean(status));
        cycle.cycleId = safeCycleId;
        cycle.slotNumber = positiveOrFallback(cycle.slotNumber, slotNumber);
        cycle.itemId = itemId;
        if (!clean(itemName).isEmpty())
        {
            cycle.itemName = itemName.trim();
        }
        if (cycle.frozenBuyPrice <= 0 && frozenBuyPrice > 0)
        {
            cycle.frozenBuyPrice = frozenBuyPrice;
        }
        cycle.sellTargetPrice = SellTargetPriceResolver.raiseOnly(
            cycle.sellTargetPrice,
            sellTargetPrice);
        if (cycle.lowestSellPrice <= 0 && lowestSellPrice > 0)
        {
            cycle.lowestSellPrice = lowestSellPrice;
        }
        cycle.startedAt = cycle.startedAt > 0 ? cycle.startedAt : Math.max(0, startedAt);
        if (lifecycleChanged)
        {
            cycle.lastEventAt = Math.max(cycle.lastEventAt, Math.max(0, lastEventAt));
        }

        if (cycle.acquiredQuantity() <= 0)
        {
            cycle.recoveredAcquiredQuantity = Math.max(
                cycle.recoveredAcquiredQuantity,
                Math.max(0, totalQuantity));
            cycle.lastAcquiredAt = Math.max(
                cycle.lastAcquiredAt,
                Math.max(0, startedAt));
        }
        Sale allocation = cycle.sales.computeIfAbsent(safeOfferId, ignored -> new Sale());
        allocation.offerId = safeOfferId;
        allocation.totalQuantity = Math.max(allocation.totalQuantity, Math.max(0, totalQuantity));
        allocation.filledQuantity = Math.max(allocation.filledQuantity, Math.max(0, filledQuantity));
        allocation.status = clean(status);
        allocation.lastEventAt = Math.max(allocation.lastEventAt, Math.max(0, lastEventAt));
        trimClosedCycles();
    }

    void releaseSell(String cycleId, String sellOfferId, int filledQuantity, long lastEventAt)
    {
        Cycle cycle = cycles.get(clean(cycleId));
        if (cycle == null)
        {
            return;
        }
        Sale allocation = cycle.sales.get(clean(sellOfferId));
        if (allocation == null)
        {
            return;
        }
        allocation.filledQuantity = Math.max(allocation.filledQuantity, Math.max(0, filledQuantity));
        allocation.status = "cancelled";
        allocation.lastEventAt = Math.max(allocation.lastEventAt, Math.max(0, lastEventAt));
        cycle.lastEventAt = Math.max(cycle.lastEventAt, allocation.lastEventAt);
    }

    Cycle selectForSetup(int itemId)
    {
        return select(itemId, 0, 0, false);
    }

    Cycle selectOpenBuy(int itemId)
    {
        if (itemId <= 0)
        {
            return null;
        }
        return cycles.values().stream()
            .filter(cycle -> cycle != null &&
                cycle.itemId == itemId &&
                cycle.frozenBuyPrice > 0 &&
                cycle.lowestSellPrice > 0 &&
                cycle.isBuyOpen())
            .max(cycleRanking(0))
            .map(Cycle::copy)
            .orElse(null);
    }

    Cycle selectForSell(int itemId, int quantity, long sellStartedAt)
    {
        return select(itemId, quantity, sellStartedAt, true);
    }

    Cycle cycle(String cycleId)
    {
        Cycle cycle = cycles.get(clean(cycleId));
        return cycle == null ? null : cycle.copy();
    }

    /**
     * A matching server slot can identify the same offer by a different ID.
     * Keep the local cycle key (and all its sell links) stable, but replace the
     * cumulative observation key so the next fill is not counted as a new buy.
     */
    void adoptOfferIdentity(
        String cycleId, int itemId, String side, String previousOfferId, String serverOfferId)
    {
        Cycle cycle = cycles.get(clean(cycleId));
        String previousId = clean(previousOfferId);
        String serverId = clean(serverOfferId);
        if (cycle == null || cycle.itemId != itemId || previousId.isEmpty() ||
            serverId.isEmpty() || previousId.equals(serverId))
        {
            return;
        }
        if ("buy".equals(side))
        {
            Integer previousFill = cycle.buyFills.remove(previousId);
            if (previousFill != null)
            {
                cycle.buyFills.merge(serverId, previousFill, Math::max);
            }
            if (previousId.equals(cycle.currentBuyOfferId))
            {
                cycle.currentBuyOfferId = serverId;
            }
        }
        else if ("sell".equals(side))
        {
            Sale previousSale = cycle.sales.remove(previousId);
            if (previousSale == null)
            {
                return;
            }
            previousSale.offerId = serverId;
            Sale serverSale = cycle.sales.get(serverId);
            if (serverSale == null)
            {
                cycle.sales.put(serverId, previousSale);
                return;
            }
            serverSale.totalQuantity = Math.max(serverSale.totalQuantity, previousSale.totalQuantity);
            serverSale.filledQuantity = Math.max(serverSale.filledQuantity, previousSale.filledQuantity);
            if (previousSale.lastEventAt > serverSale.lastEventAt ||
                (previousSale.lastEventAt == serverSale.lastEventAt && !previousSale.isOpen()))
            {
                serverSale.status = previousSale.status;
            }
            serverSale.lastEventAt = Math.max(serverSale.lastEventAt, previousSale.lastEventAt);
        }
    }

    void adoptFrozenBuyPlan(String cycleId, int serverBuyPrice, int serverLowestSellPrice)
    {
        Cycle cycle = cycles.get(clean(cycleId));
        if (cycle == null || cycle.isClosed())
        {
            return;
        }
        if (serverBuyPrice > 0)
        {
            cycle.frozenBuyPrice = serverBuyPrice;
        }
        if (serverLowestSellPrice > 0)
        {
            cycle.lowestSellPrice = serverLowestSellPrice;
        }
    }

    int size()
    {
        return cycles.size();
    }

    Set<Integer> openItemIds()
    {
        Set<Integer> itemIds = new HashSet<>();
        for (Cycle cycle : cycles.values())
        {
            if (cycle != null && cycle.itemId > 0 && !cycle.isClosed())
            {
                itemIds.add(cycle.itemId);
            }
        }
        return itemIds;
    }

    boolean needsSellTarget(int itemId)
    {
        if (itemId <= 0)
        {
            return false;
        }
        return cycles.values().stream()
            .anyMatch(cycle -> cycle != null &&
                cycle.itemId == itemId &&
                !cycle.isClosed() &&
                cycle.sellTargetPrice <= 0);
    }

    boolean raiseSellTarget(int itemId, int candidatePrice)
    {
        int safeCandidate = Math.max(0, candidatePrice);
        if (itemId <= 0 || safeCandidate <= 0)
        {
            return false;
        }
        boolean changed = false;
        for (Cycle cycle : cycles.values())
        {
            if (cycle == null || cycle.itemId != itemId || cycle.isClosed() ||
                safeCandidate <= cycle.sellTargetPrice)
            {
                continue;
            }
            cycle.sellTargetPrice = safeCandidate;
            changed = true;
        }
        return changed;
    }

    boolean raiseSellTarget(String cycleId, int candidatePrice)
    {
        Cycle cycle = cycles.get(clean(cycleId));
        int safeCandidate = Math.max(0, candidatePrice);
        if (cycle == null || cycle.isClosed() || safeCandidate <= cycle.sellTargetPrice)
        {
            return false;
        }
        cycle.sellTargetPrice = safeCandidate;
        return true;
    }

    int expireOpenCycles(int itemId, long clearedAt)
    {
        if (itemId <= 0 || clearedAt <= 0)
        {
            return 0;
        }
        int removed = 0;
        Iterator<Map.Entry<String, Cycle>> iterator = cycles.entrySet().iterator();
        while (iterator.hasNext())
        {
            Cycle cycle = iterator.next().getValue();
            // Bij gelijke seconden kan de lokale cyclus al de nieuwe generatie
            // zijn terwijl de oudere Workerrespons nog onderweg was. Alleen
            // aantoonbaar oudere (of legacy ongedateerde) cycli vervallen.
            if (cycle == null || cycle.itemId != itemId || cycle.isClosed() ||
                (cycle.startedAt > 0 && cycle.startedAt >= clearedAt))
            {
                continue;
            }
            iterator.remove();
            removed++;
        }
        return removed;
    }

    private Cycle select(int itemId, int quantity, long sellStartedAt, boolean requireQuantity)
    {
        if (itemId <= 0 || quantity < 0)
        {
            return null;
        }
        return cycles.values().stream()
            .filter(cycle -> cycle != null &&
                cycle.itemId == itemId &&
                cycle.frozenBuyPrice > 0 &&
                cycle.lowestSellPrice > 0 &&
                !cycle.isClosed() &&
                cycle.availableQuantity() > 0 &&
                (!requireQuantity || cycle.availableQuantity() >= quantity) &&
                (sellStartedAt <= 0 ||
                    (cycle.startedAt <= sellStartedAt &&
                        cycle.lastAcquiredAt <= sellStartedAt)))
            .max(cycleRanking(quantity))
            .map(Cycle::copy)
            .orElse(null);
    }

    private static Comparator<Cycle> cycleRanking(int quantity)
    {
        return Comparator
            .comparingInt((Cycle cycle) -> quantity > 0 && cycle.availableQuantity() == quantity ? 1 : 0)
            .thenComparingLong(cycle -> cycle.lastEventAt)
            .thenComparingLong(cycle -> cycle.startedAt)
            .thenComparingInt(cycle -> -cycle.slotNumber)
            .thenComparing(cycle -> cycle.cycleId);
    }

    private void trimClosedCycles()
    {
        if (cycles.size() <= MAX_RETAINED_CYCLES)
        {
            return;
        }
        List<Cycle> closed = new ArrayList<>();
        for (Cycle cycle : cycles.values())
        {
            if (cycle != null && cycle.isClosed())
            {
                closed.add(cycle);
            }
        }
        closed.sort(Comparator
            .comparingLong((Cycle cycle) -> cycle.lastEventAt)
            .thenComparing(cycle -> cycle.cycleId));
        int removeCount = Math.min(closed.size(), cycles.size() - MAX_RETAINED_CYCLES);
        for (int index = 0; index < removeCount; index++)
        {
            cycles.remove(closed.get(index).cycleId);
        }
    }

    private static Cycle sanitizedCopy(Cycle raw)
    {
        if (raw == null || clean(raw.cycleId).isEmpty() || raw.itemId <= 0)
        {
            return null;
        }
        Cycle copy = new Cycle();
        copy.cycleId = clean(raw.cycleId);
        copy.currentBuyOfferId = clean(raw.currentBuyOfferId);
        copy.slotNumber = Math.max(0, raw.slotNumber);
        copy.itemId = raw.itemId;
        copy.itemName = clean(raw.itemName);
        copy.frozenBuyPrice = Math.max(0, raw.frozenBuyPrice);
        copy.sellTargetPrice = Math.max(0, raw.sellTargetPrice);
        copy.lowestSellPrice = Math.max(0, raw.lowestSellPrice);
        copy.buyTotalQuantity = Math.max(0, raw.buyTotalQuantity);
        copy.buyStatus = clean(raw.buyStatus);
        copy.recoveredAcquiredQuantity = Math.max(0, raw.recoveredAcquiredQuantity);
        copy.lastAcquiredAt = Math.max(0, raw.lastAcquiredAt);
        copy.startedAt = Math.max(0, raw.startedAt);
        copy.lastEventAt = Math.max(0, raw.lastEventAt);
        if (raw.buyFills != null)
        {
            for (Map.Entry<String, Integer> fill : raw.buyFills.entrySet())
            {
                String offerId = clean(fill.getKey());
                if (!offerId.isEmpty())
                {
                    copy.buyFills.put(offerId, Math.max(0, fill.getValue() == null ? 0 : fill.getValue()));
                }
            }
        }
        if (raw.sales != null)
        {
            for (Map.Entry<String, Sale> sale : raw.sales.entrySet())
            {
                Sale value = Sale.sanitized(sale.getKey(), sale.getValue());
                if (value != null)
                {
                    copy.sales.put(value.offerId, value);
                }
            }
        }
        if (copy.lastAcquiredAt <= 0 && copy.acquiredQuantity() > 0)
        {
            copy.lastAcquiredAt = copy.startedAt;
        }
        return copy;
    }

    private static int positiveOrFallback(int preferred, int fallback)
    {
        return preferred > 0 ? preferred : Math.max(0, fallback);
    }

    private static String clean(String value)
    {
        return value == null ? "" : value.trim();
    }

    private static boolean isOpenStatus(String status)
    {
        return "active".equals(status) || "partially_filled".equals(status);
    }

    static final class Cycle
    {
        String cycleId = "";
        String currentBuyOfferId = "";
        int slotNumber;
        int itemId;
        String itemName = "";
        int frozenBuyPrice;
        int sellTargetPrice;
        int lowestSellPrice;
        int buyTotalQuantity;
        String buyStatus = "";
        int recoveredAcquiredQuantity;
        long lastAcquiredAt;
        long startedAt;
        long lastEventAt;
        Map<String, Integer> buyFills = new HashMap<>();
        Map<String, Sale> sales = new HashMap<>();

        int acquiredQuantity()
        {
            long acquired = Math.max(0, recoveredAcquiredQuantity);
            long observed = 0;
            for (Integer quantity : buyFills.values())
            {
                observed += Math.max(0, quantity == null ? 0 : quantity);
            }
            return clampQuantity(Math.max(acquired, observed));
        }

        int soldQuantity()
        {
            long sold = 0;
            for (Sale sale : sales.values())
            {
                if (sale != null)
                {
                    sold += Math.max(0, sale.filledQuantity);
                }
            }
            return clampQuantity(sold);
        }

        int reservedQuantity()
        {
            long reserved = 0;
            for (Sale sale : sales.values())
            {
                if (sale != null && sale.isOpen())
                {
                    reserved += Math.max(0, sale.totalQuantity - sale.filledQuantity);
                }
            }
            return clampQuantity(reserved);
        }

        int availableQuantity()
        {
            return Math.max(0, acquiredQuantity() - soldQuantity() - reservedQuantity());
        }

        int displayedBuyQuantity()
        {
            return isBuyOpen()
                ? Math.max(buyTotalQuantity, acquiredQuantity())
                : acquiredQuantity();
        }

        boolean isBuyOpen()
        {
            return isOpenStatus(buyStatus);
        }

        boolean isClosed()
        {
            int acquired = acquiredQuantity();
            return !isBuyOpen() && acquired > 0 && soldQuantity() >= acquired;
        }

        Cycle copy()
        {
            Cycle copy = new Cycle();
            copy.cycleId = cycleId;
            copy.currentBuyOfferId = currentBuyOfferId;
            copy.slotNumber = slotNumber;
            copy.itemId = itemId;
            copy.itemName = itemName;
            copy.frozenBuyPrice = frozenBuyPrice;
            copy.sellTargetPrice = sellTargetPrice;
            copy.lowestSellPrice = lowestSellPrice;
            copy.buyTotalQuantity = buyTotalQuantity;
            copy.buyStatus = buyStatus;
            copy.recoveredAcquiredQuantity = recoveredAcquiredQuantity;
            copy.lastAcquiredAt = lastAcquiredAt;
            copy.startedAt = startedAt;
            copy.lastEventAt = lastEventAt;
            copy.buyFills.putAll(buyFills);
            for (Map.Entry<String, Sale> sale : sales.entrySet())
            {
                copy.sales.put(sale.getKey(), sale.getValue().copy());
            }
            return copy;
        }

        private static int clampQuantity(long value)
        {
            return value >= Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) Math.max(0, value);
        }
    }

    static final class Sale
    {
        String offerId = "";
        int totalQuantity;
        int filledQuantity;
        String status = "";
        long lastEventAt;

        boolean isOpen()
        {
            return "active".equals(status) || "partially_filled".equals(status);
        }

        Sale copy()
        {
            Sale copy = new Sale();
            copy.offerId = offerId;
            copy.totalQuantity = totalQuantity;
            copy.filledQuantity = filledQuantity;
            copy.status = status;
            copy.lastEventAt = lastEventAt;
            return copy;
        }

        static Sale sanitized(String key, Sale raw)
        {
            if (raw == null)
            {
                return null;
            }
            String offerId = clean(raw.offerId).isEmpty() ? clean(key) : clean(raw.offerId);
            if (offerId.isEmpty())
            {
                return null;
            }
            Sale copy = new Sale();
            copy.offerId = offerId;
            copy.totalQuantity = Math.max(0, raw.totalQuantity);
            copy.filledQuantity = Math.max(0, raw.filledQuantity);
            copy.status = clean(raw.status);
            copy.lastEventAt = Math.max(0, raw.lastEventAt);
            return copy;
        }
    }
}

package com.osrsflipper.sync;

final class FlipPriceResolver
{
    private FlipPriceResolver()
    {
    }

    static int buyPrice(
        RuneliteOverviewView.Opportunity opportunity,
        LastTradePriceView priceTest)
    {
        int wikiInstantSell = opportunity == null ? 0 : Math.max(0, opportunity.instantSell);
        int fallbackBuyPrice = opportunity == null ? 0 : Math.max(0, opportunity.buyPrice);
        return buyPrice(wikiInstantSell, fallbackBuyPrice, priceTest);
    }

    static int buyPrice(
        int wikiInstantSell,
        int fallbackBuyPrice,
        LastTradePriceView priceTest)
    {
        int lastSellPrice = priceTest == null ? 0 : Math.max(0, priceTest.lastSellPrice);
        if (lastSellPrice > 0)
        {
            return plusOne(lastSellPrice);
        }
        wikiInstantSell = Math.max(0, wikiInstantSell);
        if (wikiInstantSell > 0)
        {
            return plusOne(wikiInstantSell);
        }
        return Math.max(0, fallbackBuyPrice);
    }

    static int sellPrice(
        RuneliteOverviewView.Opportunity opportunity,
        LastTradePriceView priceTest)
    {
        int wikiInstantBuy = opportunity == null ? 0 : Math.max(0, opportunity.instantBuy);
        int fallbackSellPrice = opportunity == null ? 0 : Math.max(0, opportunity.sellPrice);
        return sellPrice(wikiInstantBuy, fallbackSellPrice, priceTest);
    }

    static int sellPrice(
        int wikiInstantBuy,
        int fallbackSellPrice,
        LastTradePriceView priceTest)
    {
        int lastBuyPrice = priceTest == null ? 0 : Math.max(0, priceTest.lastBuyPrice);
        if (lastBuyPrice > 0)
        {
            return minusOne(lastBuyPrice);
        }
        wikiInstantBuy = Math.max(0, wikiInstantBuy);
        if (wikiInstantBuy > 0)
        {
            return minusOne(wikiInstantBuy);
        }
        return Math.max(0, fallbackSellPrice);
    }

    static int displayedBuyPrice(
        RuneliteOverviewView.Opportunity opportunity,
        LastTradePriceView priceTest)
    {
        return isFixedSelection(opportunity)
            ? Math.max(0, opportunity.buyPrice)
            : buyPrice(opportunity, priceTest);
    }

    static int displayedSellPrice(
        RuneliteOverviewView.Opportunity opportunity,
        LastTradePriceView priceTest)
    {
        return isFixedSelection(opportunity)
            ? Math.max(0, opportunity.sellPrice)
            : sellPrice(opportunity, priceTest);
    }

    static int editorPrice(
        String side,
        RuneliteOverviewView.Opportunity opportunity,
        MarketPriceView market,
        LastTradePriceView priceTest)
    {
        if (isFixedSelection(opportunity))
        {
            return "buy".equals(side)
                ? Math.max(0, opportunity.buyPrice)
                : ("sell".equals(side) ? Math.max(0, opportunity.sellPrice) : 0);
        }
        if ("buy".equals(side))
        {
            int wikiInstantSell = market != null && market.instantSellPrice > 0
                ? market.instantSellPrice
                : (opportunity == null ? 0 : opportunity.instantSell);
            int fallbackBuyPrice = opportunity == null ? 0 : opportunity.buyPrice;
            return buyPrice(wikiInstantSell, fallbackBuyPrice, priceTest);
        }
        if ("sell".equals(side))
        {
            int wikiInstantBuy = market != null && market.instantBuyPrice > 0
                ? market.instantBuyPrice
                : (opportunity == null ? 0 : opportunity.instantBuy);
            int fallbackSellPrice = opportunity == null ? 0 : opportunity.sellPrice;
            return sellPrice(wikiInstantBuy, fallbackSellPrice, priceTest);
        }
        return 0;
    }

    private static boolean isActiveOffer(RuneliteOverviewView.Opportunity opportunity)
    {
        return opportunity != null &&
            ("active_buy".equals(opportunity.ranking) ||
                "active_sell".equals(opportunity.ranking));
    }

    private static boolean isFixedSelection(RuneliteOverviewView.Opportunity opportunity)
    {
        return isActiveOffer(opportunity) ||
            SelectedGeOpportunityResolver.isSelectedSetup(opportunity) ||
            SelectedGeOpportunityResolver.isOpenFlipCycle(opportunity);
    }

    private static int plusOne(int value)
    {
        return value >= Integer.MAX_VALUE ? Integer.MAX_VALUE : Math.max(0, value) + 1;
    }

    private static int minusOne(int value)
    {
        return value > 1 ? value - 1 : Math.max(0, value);
    }
}

