import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** One immutable client-thread snapshot for one Swing update. */
final class FlipperPanelView
{
    final List<FlipperOfferView> offers;
    final RuneliteOverviewView overview;
    final Map<Integer, LastTradePriceView> lastTradePrices;
    final Map<Integer, MarketPriceView> marketPrices;
    final int focusedItemId;
    final String focusedSide;
    final RuneliteOverviewView.Opportunity focusedOpportunity;
    final String healthText;

    FlipperPanelView(
        List<FlipperOfferView> offers,
        RuneliteOverviewView overview,
        Map<Integer, LastTradePriceView> lastTradePrices,
        int focusedItemId,
        String focusedSide,
        RuneliteOverviewView.Opportunity focusedOpportunity,
        String healthText)
    {
        this(offers, overview, lastTradePrices, focusedItemId, focusedSide,
            focusedOpportunity, healthText, Collections.emptyMap());
    }

    FlipperPanelView(
        List<FlipperOfferView> offers,
        RuneliteOverviewView overview,
        Map<Integer, LastTradePriceView> lastTradePrices,
        int focusedItemId,
        String focusedSide,
        RuneliteOverviewView.Opportunity focusedOpportunity,
        String healthText,
        Map<Integer, MarketPriceView> marketPrices)
    {
        List<FlipperOfferView> sortedOffers = new ArrayList<>(offers == null
            ? Collections.emptyList() : offers);
        sortedOffers.sort(Comparator.comparingInt(value -> value.slotNumber));
        this.offers = Collections.unmodifiableList(sortedOffers);
        this.overview = overview == null ? RuneliteOverviewView.empty() : overview;
        this.lastTradePrices = Collections.unmodifiableMap(new LinkedHashMap<>(lastTradePrices == null
            ? Collections.emptyMap() : lastTradePrices));
        this.marketPrices = Collections.unmodifiableMap(new LinkedHashMap<>(marketPrices == null
            ? Collections.emptyMap() : marketPrices));
        this.focusedItemId = Math.max(0, focusedItemId);
        this.focusedSide = this.focusedItemId > 0 && ("buy".equals(focusedSide) || "sell".equals(focusedSide))
            ? focusedSide : "";
        this.focusedOpportunity = focusedOpportunity != null && focusedOpportunity.itemId == this.focusedItemId
            ? focusedOpportunity : null;
        this.healthText = healthText == null ? "" : healthText;
    }
}

package com.osrsflipper.sync;

import java.util.Locale;
import java.util.List;
import net.runelite.api.GrandExchangeOfferState;

final class FocusedGeItemResolver
{
    enum EditorContext
    {
        NONE,
        NEW_SETUP,
        EXISTING_OFFER
    }

    private FocusedGeItemResolver()
    {
    }

    static int resolve(
        boolean setupVisible,
        int setupItemId,
        int searchedItemId,
        boolean detailsVisible,
        int detailsItemId,
        int selectedOfferItemId)
    {
        if (setupVisible && setupItemId > 0)
        {
            return setupItemId;
        }
        if (setupVisible && searchedItemId > 0)
        {
            return searchedItemId;
        }
        if (detailsVisible && selectedOfferItemId > 0)
        {
            return selectedOfferItemId;
        }
        if (detailsVisible && detailsItemId > 0)
        {
            return detailsItemId;
        }
        return 0;
    }

    static int selectedOfferIndex(int selectedSlot, int offerCount)
    {
        int index = selectedSlot - 1;
        return index >= 0 && index < offerCount ? index : -1;
    }

    static EditorContext editorContext(
        boolean setupVisible,
        boolean detailsVisible,
        EditorContext previousContext,
        int selectedSlot,
        int previousExistingSlot,
        boolean exactSelectedOffer)
    {
        if (detailsVisible)
        {
            return exactSelectedOffer ? EditorContext.EXISTING_OFFER : EditorContext.NONE;
        }
        if (!setupVisible)
        {
            return EditorContext.NONE;
        }
        return previousContext == EditorContext.EXISTING_OFFER &&
            selectedSlot > 0 && selectedSlot == previousExistingSlot && exactSelectedOffer
            ? EditorContext.EXISTING_OFFER
            : EditorContext.NEW_SETUP;
    }

    static int priceEditorItemId(int setupItemId, int focusedItemId, int searchedItemId)
    {
        if (setupItemId > 0)
        {
            return setupItemId;
        }
        if (focusedItemId > 0)
        {
            return focusedItemId;
        }
        return Math.max(0, searchedItemId);
    }

    static FlipperOfferView exactSelectedOffer(
        int selectedSlot,
        int selectedOfferItemId,
        GrandExchangeOfferState selectedOfferState,
        int editorItemId,
        String editorSide,
        List<FlipperOfferView> candidates)
    {
        if (selectedSlot <= 0 || selectedOfferState == null ||
            selectedOfferState == GrandExchangeOfferState.EMPTY ||
            selectedOfferItemId <= 0 || selectedOfferItemId != editorItemId)
        {
            return null;
        }
        String selectedSide = resolveSide(false, "", true, selectedOfferState);
        if (selectedSide.isEmpty() || !selectedSide.equals(editorSide) || candidates == null)
        {
            return null;
        }
        for (FlipperOfferView candidate : candidates)
        {
            if (candidate != null && candidate.slotNumber == selectedSlot &&
                candidate.itemId == editorItemId && selectedSide.equals(candidate.side) &&
                !"empty".equals(candidate.status))
            {
                return candidate;
            }
        }
        return null;
    }

    static String resolveSide(
        boolean setupVisible,
        String setupText,
        boolean detailsVisible,
        GrandExchangeOfferState selectedOfferState)
    {
        if (setupVisible)
        {
            String normalized = setupText == null
                ? ""
                : setupText.toLowerCase(Locale.ROOT);
            if (normalized.contains("buy offer"))
            {
                return "buy";
            }
            if (normalized.contains("sell offer"))
            {
                return "sell";
            }
        }
        if (!detailsVisible || selectedOfferState == null)
        {
            return "";
        }
        switch (selectedOfferState)
        {
            case BUYING:
            case BOUGHT:
            case CANCELLED_BUY:
                return "buy";
            case SELLING:
            case SOLD:
            case CANCELLED_SELL:
                return "sell";
            default:
                return "";
        }
    }
}

package com.osrsflipper.sync;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Remembers when an item with personal price guidance disappeared from every
 * local GE slot. This book never clears prices itself: the Worker owns the
 * account-wide decision and returns the authoritative tombstone.
 */
final class GeItemPresenceBook
{
    static final long ABSENCE_REFRESH_SECONDS = 5 * 60;
    static final long REFRESH_RETRY_SECONDS = 60;
    private static final int MAX_ITEMS = 500;

    private final Map<Integer, Entry> entries = new HashMap<>();

    void clear()
    {
        entries.clear();
    }

    void restore(Entry[] persisted)
    {
        entries.clear();
        if (persisted == null)
        {
            return;
        }
        for (Entry raw : persisted)
        {
            if (raw == null || raw.itemId <= 0)
            {
                continue;
            }
            Entry entry = new Entry();
            entry.itemId = raw.itemId;
            entry.present = raw.present;
            entry.absentSinceAt = Math.max(0, raw.absentSinceAt);
            entry.lastRefreshRequestedAt = Math.max(0, raw.lastRefreshRequestedAt);
            entry.lastTransitionAt = Math.max(0, raw.lastTransitionAt);
            entries.put(entry.itemId, entry);
        }
        trimOldest();
    }

    List<Entry> persistedEntries()
    {
        List<Entry> result = new ArrayList<>();
        for (Entry entry : entries.values())
        {
            result.add(entry.copy());
        }
        result.sort(Comparator.comparingInt(entry -> entry.itemId));
        return result;
    }

    boolean observe(long observedAt, Set<Integer> presentItemIds, Set<Integer> trackedItemIds)
    {
        long now = Math.max(0, observedAt);
        Set<Integer> present = positiveIds(presentItemIds);
        Set<Integer> tracked = positiveIds(trackedItemIds);
        boolean changed = false;

        Iterator<Map.Entry<Integer, Entry>> existing = entries.entrySet().iterator();
        while (existing.hasNext())
        {
            if (!tracked.contains(existing.next().getKey()))
            {
                existing.remove();
                changed = true;
            }
        }

        for (Integer itemId : tracked)
        {
            Entry entry = entries.get(itemId);
            boolean isPresent = present.contains(itemId);
            if (entry == null)
            {
                entry = new Entry();
                entry.itemId = itemId;
                entry.present = isPresent;
                entry.absentSinceAt = isPresent ? 0 : now;
                entry.lastTransitionAt = now;
                entries.put(itemId, entry);
                changed = true;
                continue;
            }

            boolean overdueUnconfirmed = entry.absentSinceAt > 0 &&
                now >= entry.absentSinceAt &&
                now - entry.absentSinceAt >= ABSENCE_REFRESH_SECONDS;
            if (isPresent)
            {
                if (overdueUnconfirmed)
                {
                    if (!entry.present)
                    {
                        entry.present = true;
                        entry.lastTransitionAt = now;
                        changed = true;
                    }
                    continue;
                }
                if (!entry.present || entry.absentSinceAt > 0 || entry.lastRefreshRequestedAt > 0)
                {
                    entry.present = true;
                    entry.absentSinceAt = 0;
                    entry.lastRefreshRequestedAt = 0;
                    entry.lastTransitionAt = now;
                    changed = true;
                }
                continue;
            }

            if (overdueUnconfirmed)
            {
                if (entry.present)
                {
                    entry.present = false;
                    entry.lastTransitionAt = now;
                    changed = true;
                }
                continue;
            }
            if (entry.present || entry.absentSinceAt <= 0)
            {
                entry.present = false;
                entry.absentSinceAt = now;
                entry.lastRefreshRequestedAt = 0;
                entry.lastTransitionAt = now;
                changed = true;
            }
        }

        trimOldest();
        return changed;
    }

    boolean markAuthoritativeRefreshDue(long observedAt)
    {
        long now = Math.max(0, observedAt);
        boolean due = false;
        for (Entry entry : entries.values())
        {
            if (entry.absentSinceAt <= 0 || now < entry.absentSinceAt ||
                now - entry.absentSinceAt < ABSENCE_REFRESH_SECONDS ||
                (entry.lastRefreshRequestedAt > 0 &&
                    now - entry.lastRefreshRequestedAt < REFRESH_RETRY_SECONDS))
            {
                continue;
            }
            entry.lastRefreshRequestedAt = now;
            due = true;
        }
        return due;
    }

    void forget(Collection<Integer> itemIds)
    {
        if (itemIds == null)
        {
            return;
        }
        for (Integer itemId : itemIds)
        {
            if (itemId != null)
            {
                entries.remove(itemId);
            }
        }
    }

    long absentSinceAt(int itemId)
    {
        Entry entry = entries.get(itemId);
        return entry == null ? 0 : entry.absentSinceAt;
    }

    long lastRefreshRequestedAt(int itemId)
    {
        Entry entry = entries.get(itemId);
        return entry == null ? 0 : entry.lastRefreshRequestedAt;
    }

    boolean isPresent(int itemId)
    {
        Entry entry = entries.get(itemId);
        return entry != null && entry.present;
    }

    private void trimOldest()
    {
        while (entries.size() > MAX_ITEMS)
        {
            Integer oldest = entries.values().stream()
                .min(Comparator.comparingLong(entry -> Math.max(
                    entry.lastTransitionAt,
                    Math.max(entry.absentSinceAt, entry.lastRefreshRequestedAt))))
                .map(entry -> entry.itemId)
                .orElse(null);
            if (oldest == null)
            {
                return;
            }
            entries.remove(oldest);
        }
    }

    private static Set<Integer> positiveIds(Set<Integer> itemIds)
    {
        Set<Integer> result = new HashSet<>();
        if (itemIds == null)
        {
            return result;
        }
        for (Integer itemId : itemIds)
        {
            if (itemId != null && itemId > 0)
            {
                result.add(itemId);
            }
        }
        return result;
    }

    static final class Entry
    {
        int itemId;
        boolean present;
        long absentSinceAt;
        long lastRefreshRequestedAt;
        long lastTransitionAt;

        Entry copy()
        {
            Entry copy = new Entry();
            copy.itemId = itemId;
            copy.present = present;
            copy.absentSinceAt = absentSinceAt;
            copy.lastRefreshRequestedAt = lastRefreshRequestedAt;
            copy.lastTransitionAt = lastTransitionAt;
            return copy;
        }
    }
}

package com.osrsflipper.sync;

/**
 * Pure transition logic for the locally persisted GE slot timer.
 */
final class GeSlotTimerLifecycle
{
    private GeSlotTimerLifecycle()
    {
    }

    static State advance(
        long previousTimerStartedAt,
        long previousLastFillAt,
        long previousStartedAt,
        int previousFillHighWaterMark,
        int previousFilledQuantity,
        int nextFilledQuantity,
        boolean sameOffer,
        boolean continuingReplacement,
        long nextStartedAt,
        long eventAt)
    {
        long safeEventAt = Math.max(0, eventAt);
        long fallbackStartedAt = firstPositive(nextStartedAt, safeEventAt);
        boolean continuesPreviousTimer = sameOffer || continuingReplacement;

        long timerStartedAt = continuesPreviousTimer
            ? firstPositive(
                previousTimerStartedAt,
                previousLastFillAt,
                previousStartedAt,
                fallbackStartedAt)
            : fallbackStartedAt;
        long lastFillAt = continuesPreviousTimer ? Math.max(0, previousLastFillAt) : 0;

        int fillBaseline = sameOffer
            ? Math.max(Math.max(0, previousFillHighWaterMark), Math.max(0, previousFilledQuantity))
            : 0;
        boolean fillIncreased = sameOffer
            ? nextFilledQuantity > fillBaseline
            : nextFilledQuantity > 0;
        if (fillIncreased)
        {
            long fillAt = firstPositive(safeEventAt, fallbackStartedAt);
            timerStartedAt = fillAt;
            lastFillAt = fillAt;
        }

        int fillHighWaterMark = Math.max(fillBaseline, Math.max(0, nextFilledQuantity));
        return new State(timerStartedAt, lastFillAt, fillHighWaterMark);
    }

    private static long firstPositive(long... candidates)
    {
        for (long candidate : candidates)
        {
            if (candidate > 0)
            {
                return candidate;
            }
        }
        return 0;
    }

    static final class State
    {
        final long timerStartedAt;
        final long lastFillAt;
        final int fillHighWaterMark;

        private State(long timerStartedAt, long lastFillAt, int fillHighWaterMark)
        {
            this.timerStartedAt = timerStartedAt;
            this.lastFillAt = lastFillAt;
            this.fillHighWaterMark = fillHighWaterMark;
        }
    }
}

package com.osrsflipper.sync;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.Collections;
import java.util.Deque;
import java.util.IdentityHashMap;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.util.Text;

/**
 * Draws elapsed offer time next to the native Buy/Sell label in every occupied
 * Grand Exchange slot. As a canvas overlay it does not add clickable widgets or
 * otherwise change the Grand Exchange interface tree.
 */
final class GeSlotTimerOverlay extends Overlay
{
    private static final int TEXT_GAP = 4;
    private static final int SLOT_PADDING = 3;
    private static final float MIN_TIMER_FONT_SIZE = 6.0F;
    private static final Color FALLBACK_TIMER_COLOR = new Color(0xFF981F);

    private static final int[] SLOT_WIDGET_IDS =
    {
        InterfaceID.GeOffers.INDEX_0,
        InterfaceID.GeOffers.INDEX_1,
        InterfaceID.GeOffers.INDEX_2,
        InterfaceID.GeOffers.INDEX_3,
        InterfaceID.GeOffers.INDEX_4,
        InterfaceID.GeOffers.INDEX_5,
        InterfaceID.GeOffers.INDEX_6,
        InterfaceID.GeOffers.INDEX_7
    };

    private final Client client;
    private final OsrsFlipperSyncPlugin plugin;
    private final SlotRenderCache[] slotRenderCaches = createSlotRenderCaches();

    @Inject
    GeSlotTimerOverlay(Client client, OsrsFlipperSyncPlugin plugin)
    {
        super(plugin);
        this.client = client;
        this.plugin = plugin;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.MANUAL);
        setPriority(OverlayPriority.HIGH);
        drawAfterInterface(InterfaceID.GE_OFFERS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        GrandExchangeOffer[] liveOffers = client.getGrandExchangeOffers();
        if (liveOffers == null || liveOffers.length == 0)
        {
            return null;
        }

        Font previousFont = graphics.getFont();
        Color previousColor = graphics.getColor();
        graphics.setFont(timerFont(FontManager.getRunescapeSmallFont()));

        try
        {
            FontMetrics metrics = graphics.getFontMetrics();
            long nowEpochSeconds = Instant.now().getEpochSecond();
            int slotCount = Math.min(SLOT_WIDGET_IDS.length, liveOffers.length);

            for (int zeroBasedSlot = 0; zeroBasedSlot < slotCount; zeroBasedSlot++)
            {
                Widget slotWidget = client.getWidget(SLOT_WIDGET_IDS[zeroBasedSlot]);
                SlotRenderCache slotCache = slotRenderCaches[zeroBasedSlot];
                slotCache.observeRoot(slotWidget);

                GrandExchangeOffer liveOffer = liveOffers[zeroBasedSlot];
                if (liveOffer == null || liveOffer.getState() == GrandExchangeOfferState.EMPTY ||
                    !isVisible(slotWidget))
                {
                    continue;
                }

                GeSlotTimerView timer = plugin.geSlotTimerView(zeroBasedSlot, liveOffer);
                if (timer == null)
                {
                    continue;
                }

                String sideLabel = timer.sideLabel();
                Widget offerLabel = slotCache.offerLabel(slotWidget, sideLabel);
                if (offerLabel == null)
                {
                    continue;
                }

                Rectangle slotBounds = slotWidget.getBounds();
                Rectangle labelBounds = offerLabel.getBounds();
                if (!hasArea(slotBounds) || !hasArea(labelBounds))
                {
                    continue;
                }

                String timerText = slotCache.timerText(timer, nowEpochSeconds);
                Point location = timerLocation(
                    labelBounds,
                    slotBounds,
                    offerLabel.getXTextAlignment(),
                    metrics.stringWidth(sideLabel),
                    metrics.stringWidth(timerText),
                    metrics.getHeight(),
                    metrics.getAscent());

                Color timerColor = widgetTextColor(offerLabel);
                graphics.setColor(Color.BLACK);
                graphics.drawString(timerText, location.x + 1, location.y + 1);
                graphics.setColor(timerColor);
                graphics.drawString(timerText, location.x, location.y);
            }
        }
        finally
        {
            graphics.setFont(previousFont);
            graphics.setColor(previousColor);
        }

        return null;
    }

    static boolean isMatchingOfferLabelText(String widgetText, String expectedSideLabel)
    {
        if (widgetText == null || expectedSideLabel == null)
        {
            return false;
        }

        String visibleText = Text.removeTags(widgetText).trim();
        return visibleText.equalsIgnoreCase(expectedSideLabel.trim());
    }

    static Font timerFont(Font baseFont)
    {
        float timerSize = Math.max(MIN_TIMER_FONT_SIZE, baseFont.getSize2D() - 2.0F);
        return baseFont.deriveFont(timerSize);
    }

    static Point timerLocation(
        Rectangle labelBounds,
        Rectangle slotBounds,
        int labelHorizontalAlignment,
        int labelTextWidth,
        int timerTextWidth,
        int fontHeight,
        int fontAscent)
    {
        int renderedLabelX;
        switch (labelHorizontalAlignment)
        {
            case WidgetTextAlignment.RIGHT:
                renderedLabelX = labelBounds.x + labelBounds.width - labelTextWidth;
                break;
            case WidgetTextAlignment.CENTER:
                renderedLabelX = labelBounds.x + (labelBounds.width - labelTextWidth) / 2;
                break;
            case WidgetTextAlignment.LEFT:
            default:
                renderedLabelX = labelBounds.x;
                break;
        }

        int timerX = renderedLabelX + labelTextWidth + TEXT_GAP;
        int minimumX = slotBounds.x + SLOT_PADDING;
        int maximumX = slotBounds.x + slotBounds.width - timerTextWidth - SLOT_PADDING;
        timerX = Math.max(minimumX, Math.min(timerX, Math.max(minimumX, maximumX)));

        int timerY = labelBounds.y + Math.max(0, (labelBounds.height - fontHeight) / 2) + fontAscent;
        int minimumY = slotBounds.y + fontAscent;
        int maximumY = slotBounds.y + slotBounds.height - SLOT_PADDING;
        timerY = Math.max(minimumY, Math.min(timerY, Math.max(minimumY, maximumY)));

        return new Point(timerX, timerY);
    }

    static boolean isCachedOfferLabelValid(Widget candidate, Widget slotRoot, String expectedSideLabel)
    {
        return isVisible(candidate) &&
            isMatchingOfferLabelText(candidate.getText(), expectedSideLabel) &&
            isDescendantOf(candidate, slotRoot);
    }

    private static Widget findVisibleOfferLabel(Widget root, String expectedSideLabel)
    {
        Deque<Widget> remaining = new ArrayDeque<>();
        addChildren(remaining, root);

        Set<Widget> visited = Collections.newSetFromMap(new IdentityHashMap<>());
        while (!remaining.isEmpty())
        {
            Widget candidate = remaining.removeFirst();
            if (!visited.add(candidate))
            {
                continue;
            }

            if (isCachedOfferLabelValid(candidate, root, expectedSideLabel))
            {
                return candidate;
            }

            addChildren(remaining, candidate);
        }

        return null;
    }

    private static boolean isDescendantOf(Widget candidate, Widget expectedRoot)
    {
        if (candidate == null || expectedRoot == null || candidate == expectedRoot)
        {
            return false;
        }

        Widget current = candidate.getParent();
        for (int depth = 0; current != null && depth < 64; depth++)
        {
            if (current == expectedRoot)
            {
                return true;
            }
            if (current == candidate)
            {
                return false;
            }
            current = current.getParent();
        }
        return false;
    }

    private static void addChildren(Deque<Widget> destination, Widget parent)
    {
        if (parent == null)
        {
            return;
        }

        addChildren(destination, parent.getStaticChildren());
        addChildren(destination, parent.getDynamicChildren());
        addChildren(destination, parent.getNestedChildren());
    }

    private static void addChildren(Deque<Widget> destination, Widget[] children)
    {
        if (children == null)
        {
            return;
        }

        for (Widget child : children)
        {
            if (child != null)
            {
                destination.addLast(child);
            }
        }
    }

    private static boolean isVisible(Widget widget)
    {
        return widget != null && !widget.isHidden() && hasArea(widget.getBounds());
    }

    private static boolean hasArea(Rectangle bounds)
    {
        return bounds != null && bounds.width > 0 && bounds.height > 0;
    }

    private static Color widgetTextColor(Widget widget)
    {
        int rgb = widget.getTextColor() & 0x00FFFFFF;
        return rgb == 0 ? FALLBACK_TIMER_COLOR : new Color(rgb);
    }

    private static SlotRenderCache[] createSlotRenderCaches()
    {
        SlotRenderCache[] caches = new SlotRenderCache[SLOT_WIDGET_IDS.length];
        for (int slot = 0; slot < caches.length; slot++)
        {
            caches[slot] = new SlotRenderCache();
        }
        return caches;
    }

    static final class SlotRenderCache
    {
        private final GeSlotTimerView.TextCache textCache = new GeSlotTimerView.TextCache();
        private Widget slotRoot;
        private Widget offerLabel;

        void observeRoot(Widget currentRoot)
        {
            if (slotRoot == currentRoot)
            {
                return;
            }

            slotRoot = currentRoot;
            offerLabel = null;
            textCache.clear();
        }

        Widget offerLabel(Widget currentRoot, String expectedSideLabel)
        {
            observeRoot(currentRoot);
            if (isCachedOfferLabelValid(offerLabel, currentRoot, expectedSideLabel))
            {
                return offerLabel;
            }

            offerLabel = findVisibleOfferLabel(currentRoot, expectedSideLabel);
            return offerLabel;
        }

        String timerText(GeSlotTimerView view, long nowEpochSeconds)
        {
            return textCache.timerText(view, nowEpochSeconds);
        }
    }
}

package com.osrsflipper.sync;

import java.util.Locale;

/**
 * Immutable, UI-only view of a single Grand Exchange slot timer.
 */
final class GeSlotTimerView
{
    private static final String BUY = "buy";
    private static final String SELL = "sell";

    private final String side;
    private final long startedAt;
    private final long endedAt;

    private GeSlotTimerView(String side, long startedAt, long endedAt)
    {
        this.side = side;
        this.startedAt = startedAt;
        this.endedAt = endedAt;
    }

    /**
     * Builds a timer only for a known buy/sell side and a usable start time.
     * Returning {@code null} keeps corrupt or incomplete persisted state out of
     * the game UI without making overlay rendering fail.
     */
    static GeSlotTimerView create(String side, long startedAt, long endedAt)
    {
        String normalizedSide = normalizeSide(side);
        if (normalizedSide == null || startedAt <= 0)
        {
            return null;
        }

        return new GeSlotTimerView(normalizedSide, startedAt, Math.max(0, endedAt));
    }

    String getSide()
    {
        return side;
    }

    long getStartedAt()
    {
        return startedAt;
    }

    long getEndedAt()
    {
        return endedAt;
    }

    String sideLabel()
    {
        return BUY.equals(side) ? "Buy" : "Sell";
    }

    String timerText(long nowEpochSeconds)
    {
        long stopAt = endedAt >= startedAt ? endedAt : nowEpochSeconds;
        long elapsedSeconds = stopAt > startedAt ? stopAt - startedAt : 0;
        long hours = elapsedSeconds / 3600;
        long minutes = (elapsedSeconds % 3600) / 60;
        long seconds = elapsedSeconds % 60;
        return String.format(Locale.US, "%02d:%02d:%02d", hours, minutes, seconds);
    }

    private static String normalizeSide(String side)
    {
        if (side == null)
        {
            return null;
        }

        String normalized = side.trim().toLowerCase(Locale.ROOT);
        return BUY.equals(normalized) || SELL.equals(normalized) ? normalized : null;
    }

    /**
     * Per-slot formatter cache. A timer can only change once per epoch second;
     * state fields are part of the key so an offer transition in that same
     * second is still reflected immediately.
     */
    static final class TextCache
    {
        private String side;
        private long startedAt = Long.MIN_VALUE;
        private long endedAt = Long.MIN_VALUE;
        private long epochSecond = Long.MIN_VALUE;
        private String text;

        String timerText(GeSlotTimerView view, long nowEpochSeconds)
        {
            if (text != null &&
                epochSecond == nowEpochSeconds &&
                startedAt == view.startedAt &&
                endedAt == view.endedAt &&
                view.side.equals(side))
            {
                return text;
            }

            side = view.side;
            startedAt = view.startedAt;
            endedAt = view.endedAt;
            epochSecond = nowEpochSeconds;
            text = view.timerText(nowEpochSeconds);
            return text;
        }

        void clear()
        {
            side = null;
            startedAt = Long.MIN_VALUE;
            endedAt = Long.MIN_VALUE;
            epochSecond = Long.MIN_VALUE;
            text = null;
        }
    }
}

package com.osrsflipper.sync;

/** Local GE tax and price arithmetic; no session inventory or statistics state. */
final class GeTax
{
    private GeTax() {}

    static int calculateTaxPerItem(int sellPrice, int itemId)
    {
        if (sellPrice < 50 || isTaxExempt(itemId))
        {
            return 0;
        }
        return Math.min(sellPrice / 50, 5_000_000);
    }

    /**
     * Tradeable item IDs; never infer an exemption from a display name.
     * Rules: Jagex Grand Exchange Tax & Item Sink (9 Dec 2021), and
     * Yama CAs & More! (29 May 2025). Item list cross-checked against the
     * OSRS Wiki Grand Exchange exemption list and RuneLite ItemID (1.12.37).
     * https://secure.runescape.com/m=news/grand-exchange-tax--item-sink?oldschool=1
     * https://secure.runescape.com/m=news/yama-cas--more?oldschool=1
     * https://oldschool.runescape.wiki/w/Grand_Exchange#Exempt_from_tax
     */
    private static boolean isTaxExempt(int itemId)
    {
        switch (itemId)
        {
            case 13190: // Old school bond
            case 233: // Pestle and mortar
            case 952: // Spade
            case 1733: // Needle
            case 1735: // Shears
            case 1755: // Chisel
            case 1785: // Glassblowing pipe
            case 2347: // Hammer
            case 5325: // Gardening trowel
            case 5329: // Secateurs
            case 5331: // Watering can (0)
            case 5341: // Rake
            case 5343: // Seed dibber
            case 8794: // Saw
            case 3008: // Energy potion (4)
            case 3010: // Energy potion (3)
            case 3012: // Energy potion (2)
            case 3014: // Energy potion (1)
            case 558: // Mind rune
            case 806: // Bronze dart
            case 807: // Iron dart
            case 808: // Steel dart
            case 882: // Bronze arrow
            case 884: // Iron arrow
            case 886: // Steel arrow
            case 315: // Shrimps
            case 329: // Salmon
            case 347: // Herring
            case 351: // Pike
            case 355: // Mackerel
            case 361: // Tuna
            case 365: // Bass
            case 379: // Lobster
            case 1891: // Cake
            case 2140: // Cooked chicken
            case 2142: // Cooked meat
            case 2309: // Bread
            case 2327: // Meat pie
            case 2552: // Ring of dueling (8)
            case 3853: // Games necklace (8)
            case 8007: // Varrock teleport
            case 8008: // Lumbridge teleport
            case 8009: // Falador teleport
            case 8010: // Camelot teleport
            case 8011: // Ardougne teleport
            case 8013: // Teleport to house
            case 28790: // Kourend castle teleport
            case 28824: // Civitas illa fortis teleport
                return true;
            default:
                return false;
        }
    }

    static long calculateProfitPerItem(int buyPrice, int sellPrice, int itemId)
    {
        if (buyPrice <= 0 || sellPrice <= 0)
        {
            return 0L;
        }
        return (long) sellPrice - buyPrice - calculateTaxPerItem(sellPrice, itemId);
    }

    static int calculateLowestBreakEvenSellPrice(int buyPrice, int itemId)
    {
        if (buyPrice <= 0)
        {
            return 0;
        }

        long low = buyPrice;
        long high = Math.min((long) Integer.MAX_VALUE, (long) buyPrice + 5_000_000L);
        if (high - calculateTaxPerItem((int) high, itemId) < buyPrice)
        {
            return 0;
        }

        while (low < high)
        {
            long middle = low + ((high - low) / 2L);
            long netSellPrice = middle - calculateTaxPerItem((int) middle, itemId);
            if (netSellPrice >= buyPrice)
            {
                high = middle;
            }
            else
            {
                low = middle + 1L;
            }
        }
        return (int) low;
    }
}

package com.osrsflipper.sync;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

final class LastTradePriceBook
{
    private static final int MAX_ITEMS = 500;
    private static final long MAX_PRICE_TEST_SECONDS = 30;
    private static final int PRICE_TEST_FORMAT_VERSION = 1;
    private final Map<Integer, Entry> entries = new LinkedHashMap<>();
    private long localRevision;

    void clear()
    {
        entries.clear();
        localRevision++;
    }

    void recordTransition(
        int itemId,
        String side,
        int previousFilled,
        int previousSpent,
        int filled,
        int spent,
        int totalQuantity,
        String status,
        int fallbackPrice,
        long eventAt)
    {
        int quantity = Math.max(0, filled - Math.max(0, previousFilled));
        if (itemId <= 0 || (!"buy".equals(side) && !"sell".equals(side)))
        {
            return;
        }
        Entry existing = entries.get(itemId);
        boolean singleItemFill = quantity == 1 && totalQuantity == 1 && filled == 1 &&
            ("partially_filled".equals(status) || "completed".equals(status));
        if (!singleItemFill)
        {
            // Het actieve tegenoffer heeft nog geen fill en mag de zojuist
            // vastgelegde 1x1-aankoop niet wissen. Een echte andere fill wel.
            if (quantity > 0 && existing != null &&
                (existing.pendingTestBuyPrice > 0 || existing.pendingTestBuyAt > 0))
            {
                clearPending(existing);
                markPendingChanged(existing);
            }
            return;
        }
        long amount = Math.max(0L, (long) spent - Math.max(0, previousSpent));
        int unitPrice = amount > 0
            ? (int) Math.min(Integer.MAX_VALUE, Math.round((double) amount / quantity))
            : Math.max(0, fallbackPrice);
        if (unitPrice <= 0)
        {
            return;
        }

        Entry entry = entries.computeIfAbsent(itemId, ignored -> new Entry());
        entry.itemId = itemId;
        entry.priceTestVersion = PRICE_TEST_FORMAT_VERSION;
        if ("buy".equals(side))
        {
            if (eventAt < Math.max(entry.clearedAt, entry.highestAuthoritativeClearAt))
            {
                return;
            }
            entry.pendingTestBuyPrice = unitPrice;
            entry.pendingTestBuyAt = Math.max(0, eventAt);
            markPendingChanged(entry);
        }
        else
        {
            long sellAt = Math.max(0, eventAt);
            long elapsed = sellAt - entry.pendingTestBuyAt;
            if (entry.pendingTestBuyAt > 0 &&
                elapsed >= 0 && elapsed <= MAX_PRICE_TEST_SECONDS)
            {
                entry.lastBuyPrice = entry.pendingTestBuyPrice;
                entry.lastSellPrice = unitPrice;
                entry.lastBuyAt = entry.pendingTestBuyAt;
                entry.lastSellAt = sellAt;
                entry.clearedAt = 0;
                markPublishedChanged(entry);
            }
            boolean pendingChanged = entry.pendingTestBuyPrice > 0 || entry.pendingTestBuyAt > 0;
            clearPending(entry);
            if (pendingChanged)
            {
                markPendingChanged(entry);
            }
        }
        trimOldest();
    }

    long revision()
    {
        return localRevision;
    }

    private void markPublishedChanged(Entry entry)
    {
        localRevision++;
        entry.modifiedRevision = localRevision;
        entry.publishedModifiedRevision = localRevision;
    }

    private void markPendingChanged(Entry entry)
    {
        localRevision++;
        entry.modifiedRevision = localRevision;
        entry.pendingModifiedRevision = localRevision;
    }

    private static void clearPending(Entry entry)
    {
        if (entry == null)
        {
            return;
        }
        entry.pendingTestBuyPrice = 0;
        entry.pendingTestBuyAt = 0;
    }

    void restore(Entry[] stored)
    {
        entries.clear();
        if (stored == null)
        {
            return;
        }
        for (Entry entry : stored)
        {
            if (entry != null && entry.itemId > 0 &&
                entry.priceTestVersion == PRICE_TEST_FORMAT_VERSION)
            {
                entry.lastBuyPrice = Math.max(0, entry.lastBuyPrice);
                entry.lastSellPrice = Math.max(0, entry.lastSellPrice);
                entry.lastBuyAt = Math.max(0, entry.lastBuyAt);
                entry.lastSellAt = Math.max(0, entry.lastSellAt);
                entry.pendingTestBuyPrice = Math.max(0, entry.pendingTestBuyPrice);
                entry.pendingTestBuyAt = Math.max(0, entry.pendingTestBuyAt);
                entry.clearedAt = Math.max(0, entry.clearedAt);
                entry.highestAuthoritativeClearAt = Math.max(
                    Math.max(0, entry.highestAuthoritativeClearAt),
                    entry.clearedAt);
                entry.modifiedRevision = 0;
                entry.publishedModifiedRevision = 0;
                entry.pendingModifiedRevision = 0;
                if (entry.clearedAt > 0 && entry.clearedAt >= latestPriceTestAt(entry))
                {
                    clearPublished(entry);
                    // Een lokale buy die in exact dezelfde epochseconde als
                    // de tombstone begon, is de nieuwe generatie. Dit moet
                    // na een herstart hetzelfde blijven als tijdens runtime.
                    if (entry.pendingTestBuyAt < entry.clearedAt)
                    {
                        clearPending(entry);
                    }
                }
                entries.put(entry.itemId, entry);
            }
        }
        trimOldest();
    }

    Map<Integer, LastTradePriceView> snapshot()
    {
        Map<Integer, LastTradePriceView> result = new LinkedHashMap<>();
        for (Entry entry : entries.values())
        {
            if (entry.clearedAt > 0 && entry.clearedAt >= latestPriceTestAt(entry))
            {
                continue;
            }
            result.put(entry.itemId, new LastTradePriceView(
                entry.itemId,
                entry.lastBuyPrice,
                entry.lastSellPrice,
                entry.lastBuyAt,
                entry.lastSellAt,
                entry.clearedAt));
        }
        return result;
    }

    Map<Integer, Long> mergeAuthoritative(Iterable<LastTradePriceView> serverEntries)
    {
        return mergeAuthoritative(serverEntries, Long.MAX_VALUE);
    }

    Map<Integer, Long> mergeAuthoritative(
        Iterable<LastTradePriceView> serverEntries,
        long requestLocalRevision)
    {
        Map<Integer, Long> advancedTombstones = new LinkedHashMap<>();
        if (serverEntries == null)
        {
            return advancedTombstones;
        }
        for (LastTradePriceView server : serverEntries)
        {
            if (server == null || server.itemId <= 0)
            {
                continue;
            }
            Entry local = entries.get(server.itemId);
            long serverPriceAt = Math.max(server.lastBuyAt, server.lastSellAt);
            long serverAt = Math.max(serverPriceAt, server.clearedAt);
            Entry merged = local == null ? new Entry() : local;
            merged.itemId = server.itemId;
            merged.priceTestVersion = PRICE_TEST_FORMAT_VERSION;
            boolean authoritativeTombstone = server.clearedAt > 0 &&
                server.lastBuyPrice <= 0 && server.lastSellPrice <= 0 &&
                server.clearedAt >= serverPriceAt;
            if (authoritativeTombstone)
            {
                boolean authoritativeClearAdvanced =
                    server.clearedAt > merged.highestAuthoritativeClearAt;
                if (!authoritativeClearAdvanced)
                {
                    // Een positieve generatie kan dezelfde serverseconde als
                    // haar voorganger-tombstone dragen. Onthoud daarom los van
                    // de zichtbare clear welke tombstones al verwerkt zijn;
                    // een stale cache mag die generatie niet opnieuw wissen.
                    continue;
                }
                long localPriceAt = latestPriceTestAt(merged);
                long localPendingAt = Math.max(0, merged.pendingTestBuyAt);
                boolean publishedChangedAfterRequest =
                    merged.publishedModifiedRevision > requestLocalRevision;
                boolean pendingChangedAfterRequest =
                    merged.pendingModifiedRevision > requestLocalRevision;
                boolean publishedClearAccepted = !publishedChangedAfterRequest &&
                    localPriceAt <= server.clearedAt;
                if (publishedClearAccepted)
                {
                    clearPublished(merged);
                }
                if (!pendingChangedAfterRequest &&
                    localPendingAt > 0 && localPendingAt < server.clearedAt)
                {
                    clearPending(merged);
                }
                boolean protectedPublishedWouldBeHidden = publishedChangedAfterRequest &&
                    localPriceAt > 0 && localPriceAt <= server.clearedAt;
                boolean protectedPendingWouldBeLostOnRestore = pendingChangedAfterRequest &&
                    localPendingAt > 0 && localPendingAt < server.clearedAt;
                if (!protectedPublishedWouldBeHidden && !protectedPendingWouldBeLostOnRestore)
                {
                    merged.clearedAt = Math.max(merged.clearedAt, server.clearedAt);
                }
                merged.highestAuthoritativeClearAt = server.clearedAt;
                entries.put(server.itemId, merged);
                // Rapporteer elke nieuw waargenomen tombstone ook wanneer een
                // nieuwere lokale prijsmeting terecht blijft bestaan. De
                // caller gebruikt clearedAt als bovengrens en kan daardoor
                // oude flipcycli opruimen zonder de nieuwe generatie te raken.
                advancedTombstones.put(server.itemId, server.clearedAt);
                continue;
            }
            long localAt = local == null ? 0 : Math.max(
                Math.max(latestPriceTestAt(local), local.pendingTestBuyAt),
                local.clearedAt);
            if (server.lastBuyPrice <= 0 || server.lastSellPrice <= 0 ||
                (server.clearedAt > 0 && server.clearedAt > serverPriceAt))
            {
                continue;
            }
            merged.highestAuthoritativeClearAt = Math.max(
                merged.highestAuthoritativeClearAt,
                server.clearedAt);
            // Een positieve response is een snapshot van het requestmoment.
            // Een lokale prijstest die daarna wijzigde wint daarom altijd,
            // ook wanneer beide generaties dezelfde epochseconde dragen.
            if (local != null && local.modifiedRevision > requestLocalRevision)
            {
                entries.put(server.itemId, merged);
                continue;
            }
            if (local != null && localAt > 0 && localAt > serverAt)
            {
                continue;
            }
            merged.lastBuyPrice = server.lastBuyPrice;
            merged.lastSellPrice = server.lastSellPrice;
            merged.lastBuyAt = server.lastBuyAt;
            merged.lastSellAt = server.lastSellAt;
            // Een positieve authoritatieve generatie vervangt de historische
            // tombstone, ook wanneer beide servermomenten in dezelfde seconde
            // vallen. De Worker gebruikt de hogere flip-id als tie-breaker.
            merged.clearedAt = 0;
            clearPending(merged);
            entries.put(server.itemId, merged);
        }
        trimOldest();
        return advancedTombstones;
    }

    List<Entry> persistedEntries()
    {
        return new ArrayList<>(entries.values());
    }

    private void trimOldest()
    {
        while (entries.size() > MAX_ITEMS)
        {
            Integer oldest = entries.values().stream()
                .min(Comparator.comparingLong(entry -> Math.max(
                    Math.max(entry.lastBuyAt, entry.lastSellAt),
                    Math.max(
                        entry.pendingTestBuyAt,
                        Math.max(entry.clearedAt, entry.highestAuthoritativeClearAt)))))
                .map(entry -> entry.itemId)
                .orElse(null);
            if (oldest == null)
            {
                return;
            }
            entries.remove(oldest);
        }
    }

    private static long latestPriceTestAt(Entry entry)
    {
        return entry == null ? 0 : Math.max(entry.lastBuyAt, entry.lastSellAt);
    }

    private static void clearPublished(Entry entry)
    {
        if (entry == null)
        {
            return;
        }
        entry.lastBuyPrice = 0;
        entry.lastSellPrice = 0;
        entry.lastBuyAt = 0;
        entry.lastSellAt = 0;
    }

    static final class Entry
    {
        int itemId;
        int priceTestVersion;
        int lastBuyPrice;
        int lastSellPrice;
        long lastBuyAt;
        long lastSellAt;
        int pendingTestBuyPrice;
        long pendingTestBuyAt;
        long clearedAt;
        long highestAuthoritativeClearAt;
        transient long modifiedRevision;
        transient long publishedModifiedRevision;
        transient long pendingModifiedRevision;
    }
}

