package com.osrsflipper.sync;

import java.util.HashMap;
import java.util.Map;

/** Client-thread pacing for the public price source, independent of financial delivery. */
final class MarketPriceRefreshPolicy
{
    private final Map<Integer, Long> requestedAt = new HashMap<>();
    private final Map<Integer, Integer> failures = new HashMap<>();
    private final Map<Integer, Long> retryAt = new HashMap<>();
    private long sourceRetryAt;
    private long nextRequestAt;

    boolean due(int itemId, MarketPriceView cached, long now, long interval, boolean force)
    {
        return now >= sourceRetryAt && now >= retryAt.getOrDefault(itemId, 0L) &&
            now >= requestedAt.getOrDefault(itemId, 0L) + 1 &&
            (force || cached == null || now >= cached.fetchedAt + interval);
    }

    boolean sourceReady(long now) { return now >= Math.max(sourceRetryAt, nextRequestAt); }
    boolean itemReady(int itemId, long now) { return now >= retryAt.getOrDefault(itemId, 0L); }
    void started(int itemId, long now)
    {
        requestedAt.put(itemId, now);
        nextRequestAt = now + 1;
    }

    void succeeded(int itemId)
    {
        failures.remove(itemId);
        retryAt.remove(itemId);
    }

    void failed(int itemId, int status, long now, long retryAfter)
    {
        int count = Math.min(6, failures.getOrDefault(itemId, 0) + 1);
        failures.put(itemId, count);
        long delay = Math.max(Math.min(300, 15L << (count - 1)), Math.min(3600, Math.max(0, retryAfter)));
        retryAt.put(itemId, now + delay);
        if (status == 0 || status == 429 || status >= 500) sourceRetryAt = Math.max(sourceRetryAt, now + delay);
    }

    void clear()
    {
        requestedAt.clear();
        failures.clear();
        retryAt.clear();
        sourceRetryAt = 0;
        nextRequestAt = 0;
    }

    static long retryAfterSeconds(String header, long now)
    {
        if (header == null) return 0;
        try { return Math.max(0, Long.parseLong(header.trim())); }
        catch (NumberFormatException ignored)
        {
            try
            {
                return Math.max(0, java.time.ZonedDateTime.parse(header.trim(),
                    java.time.format.DateTimeFormatter.RFC_1123_DATE_TIME).toEpochSecond() - now);
            }
            catch (java.time.format.DateTimeParseException invalid) { return 0; }
        }
    }
}

package com.osrsflipper.sync;

final class MarketPriceView
{
    final int itemId;
    final int instantBuyPrice;
    final int instantSellPrice;
    final long instantBuyAt;
    final long instantSellAt;
    final long fetchedAt;
    final boolean instantBuyTimeExact;
    final boolean instantSellTimeExact;

    MarketPriceView(
        int itemId,
        int instantBuyPrice,
        int instantSellPrice,
        long instantBuyAt,
        long instantSellAt,
        long fetchedAt)
    {
        this(itemId, instantBuyPrice, instantSellPrice, instantBuyAt, instantSellAt, fetchedAt, true, true);
    }

    MarketPriceView(int itemId, int instantBuyPrice, int instantSellPrice,
        long instantBuyAt, long instantSellAt, long fetchedAt,
        boolean instantBuyTimeExact, boolean instantSellTimeExact)
    {
        this.itemId = itemId;
        this.instantBuyPrice = Math.max(0, instantBuyPrice);
        this.instantSellPrice = Math.max(0, instantSellPrice);
        this.instantBuyAt = Math.max(0, instantBuyAt);
        this.instantSellAt = Math.max(0, instantSellAt);
        this.fetchedAt = Math.max(0, fetchedAt);
        this.instantBuyTimeExact = instantBuyTimeExact;
        this.instantSellTimeExact = instantSellTimeExact;
    }

    /** Keeps observed transactions across sources without inventing a Wiki check time. */
    static MarketPriceView accept(MarketPriceView previous, MarketPriceView incoming, long now)
    {
        boolean high = valid(incoming.instantBuyPrice, incoming.instantBuyAt, now);
        boolean low = valid(incoming.instantSellPrice, incoming.instantSellAt, now);
        if (!high && !low) return null;
        boolean useHigh = high && (previous == null || previous.instantBuyPrice <= 0 || newer(
            incoming.instantBuyAt, incoming.instantBuyTimeExact, previous.instantBuyAt, previous.instantBuyTimeExact));
        boolean useLow = low && (previous == null || previous.instantSellPrice <= 0 || newer(
            incoming.instantSellAt, incoming.instantSellTimeExact, previous.instantSellAt, previous.instantSellTimeExact));
        return new MarketPriceView(incoming.itemId,
            useHigh ? incoming.instantBuyPrice : previous == null ? 0 : previous.instantBuyPrice,
            useLow ? incoming.instantSellPrice : previous == null ? 0 : previous.instantSellPrice,
            useHigh ? incoming.instantBuyAt : previous == null ? 0 : previous.instantBuyAt,
            useLow ? incoming.instantSellAt : previous == null ? 0 : previous.instantSellAt,
            incoming.fetchedAt > 0 ? incoming.fetchedAt : previous == null ? 0 : previous.fetchedAt,
            useHigh ? incoming.instantBuyTimeExact : previous != null && previous.instantBuyTimeExact,
            useLow ? incoming.instantSellTimeExact : previous != null && previous.instantSellTimeExact);
    }

    private static boolean valid(int price, long at, long now)
    {
        return price > 0 && at > 0 && at <= now + 600;
    }

    private static boolean newer(long incomingAt, boolean incomingExact, long previousAt, boolean previousExact)
    {
        // An aggregate max(highTime, lowTime) is not proof of either side's age.
        // Prefer actual side times; otherwise compare like-for-like timestamps.
        return incomingExact != previousExact ? incomingExact : incomingAt >= previousAt;
    }
}

package com.osrsflipper.sync;

import java.util.Collection;
import java.util.Comparator;
import java.util.Set;

final class OfferGuidanceResolver
{
    private OfferGuidanceResolver()
    {
    }

    static Guidance buy(
        int actualOrderPrice,
        int currentSellCandidate,
        int itemId,
        Guidance previous,
        boolean continuingOffer)
    {
        Guidance safePrevious = previous == null ? Guidance.empty() : previous;
        int frozenBuyPrice = continuingOffer && safePrevious.buyPrice > 0
            ? safePrevious.buyPrice
            : Math.max(0, actualOrderPrice);
        Guidance repriced = reprice(
            "buy",
            frozenBuyPrice,
            currentSellCandidate,
            continuingOffer ? safePrevious : Guidance.empty());
        int lowestSellPrice = freezeLowestSellPrice(
            repriced.lowestSellPrice,
            repriced.buyPrice,
            itemId);
        return new Guidance(
            repriced.buyPrice,
            repriced.sellPrice,
            repriced.sourceBuyOfferId,
            lowestSellPrice);
    }

    static int freezeLowestSellPrice(int existingLowestSellPrice, int buyPrice, int itemId)
    {
        if (existingLowestSellPrice > 0)
        {
            return existingLowestSellPrice;
        }
        return GeTax.calculateLowestBreakEvenSellPrice(
            buyPrice,
            itemId);
    }

    static int adoptServerLowestSellPrice(int localLowestSellPrice, int serverLowestSellPrice)
    {
        return serverLowestSellPrice > 0
            ? serverLowestSellPrice
            : Math.max(0, localLowestSellPrice);
    }

    static boolean continuesOfferLifecycle(boolean sameOfferShape, String previousStatus)
    {
        return sameOfferShape &&
            !"completed".equals(previousStatus) &&
            !"cancelled".equals(previousStatus);
    }

    /**
     * RuneLite normally reports Modify offer as a cancelled offer followed
     * directly by a replacement in the same GE slot. Under event coalescing the
     * intermediate CANCELLED observation can be absent. In both cases the lack
     * of an EMPTY state and the original/remaining quantity identify the direct
     * successor, whose frozen cycle guidance must be retained.
     */
    static boolean continuesCancelledReprice(
        boolean sameItemAndSide,
        String previousStatus,
        int previousPrice,
        int nextPrice,
        int previousTotalQuantity,
        int previousFilledQuantity,
        int nextTotalQuantity)
    {
        boolean replaceableStatus = "cancelled".equals(previousStatus) ||
            "active".equals(previousStatus) ||
            "partially_filled".equals(previousStatus);
        if (!sameItemAndSide || !replaceableStatus ||
            previousPrice <= 0 || nextPrice <= 0 ||
            previousTotalQuantity <= 0 || nextTotalQuantity <= 0)
        {
            return false;
        }

        int remainingQuantity = Math.max(
            0,
            previousTotalQuantity - Math.max(0, previousFilledQuantity));
        return (previousFilledQuantity <= 0 &&
                nextPrice != previousPrice &&
                nextTotalQuantity == previousTotalQuantity) ||
            (remainingQuantity > 0 && nextTotalQuantity == remainingQuantity);
    }

    static BuyCandidate frozenBuyCandidate(
        int slotNumber,
        int itemId,
        int filledQuantity,
        long startedAt,
        long lastEventAt,
        String offerId,
        int buyPrice,
        int sellPrice,
        int lowestSellPrice)
    {
        int safeBuyPrice = Math.max(0, buyPrice);
        return new BuyCandidate(
            slotNumber,
            itemId,
            filledQuantity,
            startedAt,
            lastEventAt,
            offerId,
            safeBuyPrice,
            sellPrice,
            freezeLowestSellPrice(lowestSellPrice, safeBuyPrice, itemId));
    }

    static Guidance reprice(
        String side,
        int actualOrderPrice,
        int currentSellCandidate,
        Guidance previous)
    {
        Guidance safePrevious = previous == null ? Guidance.empty() : previous;
        int buyPrice = "buy".equals(side)
            ? Math.max(0, actualOrderPrice)
            : safePrevious.buyPrice;
        int sellCandidate = "sell".equals(side)
            ? Math.max(Math.max(0, actualOrderPrice), Math.max(0, currentSellCandidate))
            : Math.max(0, currentSellCandidate);
        int sellPrice = SellTargetPriceResolver.raiseOnly(
            safePrevious.sellPrice,
            sellCandidate);
        return new Guidance(
            buyPrice,
            sellPrice,
            safePrevious.sourceBuyOfferId,
            safePrevious.lowestSellPrice);
    }

    static Guidance linkedSell(
        int actualSellOrderPrice,
        int currentSellCandidate,
        int fallbackBuyPrice,
        BuyCandidate source)
    {
        int buyPrice = source != null && source.buyPrice > 0
            ? source.buyPrice
            : Math.max(0, fallbackBuyPrice);
        int previousSellTarget = source == null ? 0 : source.sellPrice;
        int sellPrice = SellTargetPriceResolver.raiseOnly(
            previousSellTarget,
            Math.max(Math.max(0, actualSellOrderPrice), Math.max(0, currentSellCandidate)));
        return new Guidance(
            buyPrice,
            sellPrice,
            source == null ? "" : source.offerId,
            source == null ? 0 : source.lowestSellPrice);
    }

    static BuyCandidate selectBuyForSell(
        int sellSlotNumber,
        int itemId,
        int sellQuantity,
        long sellStartedAt,
        Collection<BuyCandidate> candidates,
        Set<String> alreadyLinkedOfferIds)
    {
        if (itemId <= 0 || sellQuantity <= 0 || candidates == null || candidates.isEmpty())
        {
            return null;
        }
        Set<String> linked = alreadyLinkedOfferIds == null
            ? java.util.Collections.emptySet()
            : alreadyLinkedOfferIds;
        Comparator<BuyCandidate> ranking = Comparator
            .comparingInt((BuyCandidate candidate) -> candidate.filledQuantity == sellQuantity ? 1 : 0)
            .thenComparingLong(candidate -> candidate.lastEventAt)
            .thenComparingLong(candidate -> candidate.startedAt)
            .thenComparingInt(candidate -> candidate.slotNumber == sellSlotNumber ? 1 : 0)
            .thenComparingInt(candidate -> -candidate.slotNumber)
            .thenComparing(candidate -> candidate.offerId);
        return candidates.stream()
            .filter(candidate -> candidate != null &&
                candidate.itemId == itemId &&
                candidate.filledQuantity >= sellQuantity &&
                candidate.buyPrice > 0 &&
                candidate.startedAt <= sellStartedAt &&
                // A legacy snapshot has cumulative fills but no acquisition
                // history. Do not attribute its later-observed stock to an
                // earlier sale. Known cycles use their lastAcquiredAt instead.
                candidate.lastEventAt <= sellStartedAt &&
                !candidate.offerId.isEmpty() &&
                !linked.contains(candidate.offerId))
            .max(ranking)
            .orElse(null);
    }

    static final class Guidance
    {
        final int buyPrice;
        final int sellPrice;
        final String sourceBuyOfferId;
        final int lowestSellPrice;

        Guidance(int buyPrice, int sellPrice, String sourceBuyOfferId)
        {
            this(buyPrice, sellPrice, sourceBuyOfferId, 0);
        }

        Guidance(int buyPrice, int sellPrice, String sourceBuyOfferId, int lowestSellPrice)
        {
            this.buyPrice = Math.max(0, buyPrice);
            this.sellPrice = Math.max(0, sellPrice);
            this.sourceBuyOfferId = sourceBuyOfferId == null ? "" : sourceBuyOfferId;
            this.lowestSellPrice = Math.max(0, lowestSellPrice);
        }

        static Guidance empty()
        {
            return new Guidance(0, 0, "", 0);
        }
    }

    static final class BuyCandidate
    {
        final int slotNumber;
        final int itemId;
        final int filledQuantity;
        final long startedAt;
        final long lastEventAt;
        final String offerId;
        final int buyPrice;
        final int sellPrice;
        final int lowestSellPrice;

        BuyCandidate(
            int slotNumber,
            int itemId,
            int filledQuantity,
            long startedAt,
            long lastEventAt,
            String offerId,
            int buyPrice,
            int sellPrice)
        {
            this(slotNumber, itemId, filledQuantity, startedAt, lastEventAt,
                offerId, buyPrice, sellPrice, 0);
        }

        BuyCandidate(
            int slotNumber,
            int itemId,
            int filledQuantity,
            long startedAt,
            long lastEventAt,
            String offerId,
            int buyPrice,
            int sellPrice,
            int lowestSellPrice)
        {
            this.slotNumber = slotNumber;
            this.itemId = itemId;
            this.filledQuantity = Math.max(0, filledQuantity);
            this.startedAt = Math.max(0, startedAt);
            this.lastEventAt = Math.max(0, lastEventAt);
            this.offerId = offerId == null ? "" : offerId;
            this.buyPrice = Math.max(0, buyPrice);
            this.sellPrice = Math.max(0, sellPrice);
            this.lowestSellPrice = Math.max(0, lowestSellPrice);
        }
    }
}

