    private void applyHealth(String text)
    {
        String next = text == null ? "" : text;
        if (next.equals(healthText))
        {
            return;
        }
        healthText = next;
        healthBanner.setText(html(escapeHtml(next).replace("\n", "<br>"), 158));
        healthBanner.setVisible(!next.isEmpty());
        revalidate();
        repaint();
    }

