            lastTradePrices = view.lastTradePrices;
            marketPrices = view.marketPrices;
            focusedItemId = view.focusedItemId;
            focusedOfferSide = view.focusedSide;
            resolvedFocusedOpportunity = view.focusedOpportunity;
            applyOverview(view.overview);
            applyHealth(view.healthText);
            rebuildSlots();
            rebuildOpportunities();
            rebuildStats();
        });
    }

    void updateOffers(List<FlipperOfferView> nextOffers)
    {
        List<FlipperOfferView> copy = new ArrayList<>(nextOffers == null
            ? Collections.emptyList()
            : nextOffers);
        copy.sort(Comparator.comparingInt(value -> value.slotNumber));
        SwingUtilities.invokeLater(() ->
        {
            offers = copy;
            rebuildSlots();
            rebuildOpportunities();
        });
    }

