            entry.getValue().setForeground(selected ? GOLD : Color.LIGHT_GRAY);
            entry.getValue().setBackground(selected
                ? ColorScheme.DARKER_GRAY_COLOR
                : ColorScheme.DARK_GRAY_COLOR);
        }
    }

