    private void submitCash()
    {
        if (saveCashAction == null)
        {
            return;
        }
        try
        {
            saveCashAction.accept(parseCashBalance(cashInput.getText()));
            cashInput.setToolTipText("Gehele GP, bijvoorbeeld 1000000 of 1 000 000; maximaal 2 147 483 647");
        }
        catch (NumberFormatException ignored)
        {
            cashInput.setToolTipText("Ongeldige invoer: gebruik gehele GP van 0 t/m 2 147 483 647, met alleen optionele duizendtals-spaties");
        }
    }

    static long parseCashBalance(String input)
    {
        String normalized = input == null ? "" : input
            .replace('\u00a0', ' ').replace('\u202f', ' ').trim();
        if (!normalized.matches("(?:[0-9]+|[0-9]{1,3}(?: [0-9]{3})+)"))
        {
            throw new NumberFormatException("Expected whole GP with optional grouped spaces");
        }
        long value = Long.parseLong(normalized.replace(" ", ""));
        if (value > Integer.MAX_VALUE)
        {
            throw new NumberFormatException("Cash balance exceeds the GP limit");
        }
        return value;
    }

    private void rebuildSlots()
    {
        slotsList.removeAll();
        offerCards.clear();
        if (offers.isEmpty())
        {
            slotsList.add(emptyMessage("Geen actieve GE-offers gevonden."));
        }
        else
        {
            for (FlipperOfferView offer : offers)
            {
                OfferCard card = new OfferCard(offer);
                offerCards.add(card);
                slotsList.add(card.panel);
                slotsList.add(Box.createVerticalStrut(6));
            }
        }
        slotsList.revalidate();
        slotsList.repaint();
    }

    private void rebuildOpportunities()
    {
        opportunitiesList.removeAll();
        priceCheckLabels.clear();
        visiblePriceItems = Collections.emptyList();
        opportunityPricesUpdatedAt = 0;
        if (focusedItemId > 0)
        {
            RuneliteOverviewView.Opportunity focused = resolvedFocusedOpportunity;
            addOpportunitySection(
                "Geselecteerde flip",
                focused == null ? Collections.emptyList() : Collections.singletonList(focused),
                "Voor dit geopende item zijn nog geen scanner- of slotprijzen beschikbaar.");
            opportunityPricesUpdatedAt = focused == null ? 0 : focused.priceUpdatedAt;
            opportunityPricesAgePrefix = "Itemprijzen: ";
        }
        else if (!overview.topOpportunitiesLoaded)
        {
            opportunitiesList.add(emptyMessage(overview.marketAvailable
                ? "Persoonlijke flips worden opgehaald..."
                : "Flips tijdelijk niet beschikbaar. Marktgegevens worden opnieuw opgehaald."));
        }
        else
        {
            List<RuneliteOverviewView.Opportunity> candidates = visibleCycleOpportunities(overview.hourly, offers);
            List<RuneliteOverviewView.Opportunity> visible = rankedCycleOpportunities(
                candidates, marketPrices, lastTradePrices,
                overview.cash.updatedAt > 0 || overview.cash.version >= 0 ? overview.cash.available : null);
            List<Integer> priceItems = new ArrayList<>();
            for (RuneliteOverviewView.Opportunity item : visible)
            {
                priceItems.add(item.itemId);
            }
            // Keep checking rejected candidates when there is room. An empty
            // recommendation list must still recover from a later Wiki quote,
            // within the existing five-item polling budget.
            for (RuneliteOverviewView.Opportunity item : candidates)
            {
                if (priceItems.size() >= TOP_OPPORTUNITY_LIMIT) break;
                if (!priceItems.contains(item.itemId)) priceItems.add(item.itemId);
            }
            visiblePriceItems = Collections.unmodifiableList(priceItems);
            if (!overview.marketAvailable || overview.marketStale)
            {
                String warningText = overview.marketAvailable
                    ? "Marktoverzicht is verouderd. Itemprijzen kunnen recenter zijn; zie de prijscontrole."
                    : visible.isEmpty()
                        ? "Marktgegevens tijdelijk niet beschikbaar. Nieuwe gegevens worden opgehaald."
                        : "Marktgegevens tijdelijk niet beschikbaar. Je ziet de laatst opgehaalde flips.";
                JLabel warning = emptyMessage(warningText);
                warning.setForeground(GOLD);
                opportunitiesList.add(warning);
            }
            addOpportunitySection(
                "Top flipwaarde",
                visible,
                emptyTopOpportunitiesMessage(candidates));
            opportunityPricesUpdatedAt = overview.generatedAt;
            opportunityPricesAgePrefix = "Overzicht: ";
        }
        if (opportunityPricesUpdatedAt > 0)
        {
            updateOpportunityPricesAge(Instant.now().getEpochSecond());
            opportunitiesList.add(opportunityPricesAge);
        }
        opportunitiesList.revalidate();
        opportunitiesList.repaint();
    }

    private String emptyTopOpportunitiesMessage(List<RuneliteOverviewView.Opportunity> candidates)
    {
        if (!overview.hourly.isEmpty() && candidates.isEmpty())
        {
            return "Alle gevonden flips staan al in je GE-slots.";
        }
        if (!overview.marketAvailable)
        {
            return "Geen bewaarde flips om te tonen. Wacht op nieuwe marktgegevens.";
        }
        if (overview.marketStale)
        {
            return "Wacht op actuele marktprijzen om uitvoerbare flips te bepalen.";
        }
        if (overview.cash.available <= 0)
        {
            return "Geen vrije GP beschikbaar voor een nieuwe flip. Controleer je cash en GE-offers.";
        }
        return "Nog geen uitvoerbare flip met minstens 100k GP flipwaarde.";
    }

    private void addOpportunitySection(
        String title,
        List<RuneliteOverviewView.Opportunity> opportunities,
        String emptyText)
    {
        JLabel heading = new JLabel(title);
        heading.setForeground(GOLD);
        heading.setFont(heading.getFont().deriveFont(Font.BOLD));
        heading.setAlignmentX(Component.LEFT_ALIGNMENT);
        opportunitiesList.add(heading);
        opportunitiesList.add(Box.createVerticalStrut(4));
        if (opportunities == null || opportunities.isEmpty())
        {
            opportunitiesList.add(emptyMessage(emptyText));
            return;
        }
        int rank = 1;
        for (RuneliteOverviewView.Opportunity opportunity : opportunities)
        {
            opportunitiesList.add(opportunityCard(opportunity, rank++));
            opportunitiesList.add(Box.createVerticalStrut(5));
        }
    }

    private JPanel opportunityCard(
        RuneliteOverviewView.Opportunity opportunity,
        int rank)
    {
        JPanel card = cardPanel();
        JPanel header = itemHeader(opportunity.itemId, opportunity.itemName);
        JLabel rankLabel = new JLabel("#" + rank);
        rankLabel.setForeground(MUTED);
        rankLabel.setFont(rankLabel.getFont().deriveFont(Font.BOLD));
        header.add(rankLabel, BorderLayout.EAST);
        card.add(header);

        boolean activeBuyOffer = "active_buy".equals(opportunity.ranking);
        boolean activeSellOffer = "active_sell".equals(opportunity.ranking);
        LastTradePriceView lastTrade = lastTradePrices.get(opportunity.itemId);
        int displayedBuyPrice = displayedBuyPrice(opportunity, lastTrade);
        int displayedSellPrice = displayedSellPrice(opportunity, lastTrade);
        long displayedCycleProfit = displayedCycleProfit(
            opportunity,
            displayedBuyPrice,
            displayedSellPrice);
        JLabel profit = new JLabel(activeBuyOffer
            ? "Actief koopoffer"
            : (activeSellOffer ? "Actief verkoopoffer" : cycleProfitText(opportunity, displayedCycleProfit)));
        profit.setForeground(!opportunity.hasQuantity() ? MUTED : activeSellOffer
            ? GOLD
            : (activeBuyOffer || displayedCycleProfit >= 0 ? GREEN : RED));
        profit.setFont(profit.getFont().deriveFont(Font.BOLD, 15f));
        profit.setAlignmentX(Component.LEFT_ALIGNMENT);
        profit.setBorder(new EmptyBorder(3, 0, 3, 0));
        card.add(profit);

        boolean focusedCard = opportunity.itemId == focusedItemId;
        boolean buying = focusedCard && "buy".equals(focusedOfferSide);
        boolean selling = focusedCard && "sell".equals(focusedOfferSide);
        card.add(compactMetric("Aantal", quantityText(opportunity)));
        if (!opportunity.quantityReason.isEmpty())
        {
            JLabel reason = wrapLabel("<small>" + escapeHtml(opportunity.quantityReason) + "</small>", 176);
            reason.setForeground(MUTED);
            reason.setAlignmentX(Component.LEFT_ALIGNMENT);
            card.add(reason);
        }
        if (opportunity.hasBuyLimit())
        {
            card.add(compactMetric("Limiet gebruikt", buyLimitUsage(opportunity)));
            card.add(compactMetric("Nog vrij", buyLimitRemaining(opportunity)));
        }
        card.add(coloredMetric("Koop", priceOrDash(displayedBuyPrice), GOLD, buying));
        card.add(coloredMetric("Verkoop", priceOrDash(displayedSellPrice), GOLD, selling));
        card.add(coloredMetric("Wiki instabuy", priceOrDash(opportunity.instantBuy), BLUE, selling));
        card.add(coloredMetric("Wiki instasell", priceOrDash(opportunity.instantSell), BLUE, buying));
        MarketPriceView checkedPrice = marketPrices.get(opportunity.itemId);
        if (checkedPrice != null && checkedPrice.fetchedAt > 0)
        {
            JLabel checked = new JLabel("Prijscontrole: " + relativeAge(checkedPrice.fetchedAt, Instant.now().getEpochSecond()));
            checked.setForeground(MUTED);
            checked.setFont(checked.getFont().deriveFont(10f));
            checked.setAlignmentX(Component.LEFT_ALIGNMENT);
            checked.putClientProperty("priceTimePrefix", "Prijscontrole: ");
            checked.setToolTipText("Laatste geslaagde controle bij de marktbron. Een controle betekent niet dat er een nieuwe transactie is.");
            priceCheckLabels.put(checked, checkedPrice.fetchedAt);
            card.add(checked);
            long tradedAt = Math.max(opportunity.instantBuyAt, opportunity.instantSellAt);
            if (tradedAt > 0)
            {
                JLabel traded = new JLabel("Nieuwste prijstransactie: " + relativeAge(tradedAt, Instant.now().getEpochSecond()));
                traded.setForeground(MUTED);
                traded.setFont(traded.getFont().deriveFont(10f));
                traded.setAlignmentX(Component.LEFT_ALIGNMENT);
                traded.putClientProperty("priceTimePrefix", "Nieuwste prijstransactie: ");
                priceCheckLabels.put(traded, tradedAt);
                card.add(traded);
            }
        }
        if (lastTrade != null && lastTrade.lastBuyPrice > 0)
        {
            card.add(coloredMetric("Last buy price", priceOrDash(lastTrade.lastBuyPrice), PURPLE, selling));
        }
        if (lastTrade != null && lastTrade.lastSellPrice > 0)
        {
            card.add(coloredMetric("Last sell price", priceOrDash(lastTrade.lastSellPrice), PURPLE, buying));
        }
        if (focusedCard)
        {
            int lowestPrice = opportunity.lowestSellPrice;
            if (lowestPrice <= 0 &&
                SelectedGeOpportunityResolver.isSelectedSetup(opportunity) &&
                displayedBuyPrice > 0)
            {
                lowestPrice = GeTax.calculateLowestBreakEvenSellPrice(
                    displayedBuyPrice,
                    opportunity.itemId);
            }
            card.add(coloredMetric("Lowest price", priceOrDash(lowestPrice), GOLD, selling));
        }
        if (displayedBuyPrice > 0 && displayedSellPrice > 0)
        {
            long profitPerItem = GeTax.calculateProfitPerItem(
                displayedBuyPrice,
                displayedSellPrice,
                opportunity.itemId);
            card.add(coloredMetric(
                "Winst/item",
                formatSignedGp(profitPerItem),
                profitPerItem >= 0 ? GREEN : RED,
                false));
        }
        else
        {
            card.add(compactMetric("Winst/item", "—"));
        }
        return card;
    }

