        heartbeatRetryAttempts = 0;
        heartbeatNextAttemptAt = 0;
        serverStateRetryAttempts = 0;
        serverStateNextAttemptAt = 0;
        cashRetryAttempts = 0;
        workerBackoffUntil = 0;
        heartbeatTicks = HEARTBEAT_GAME_TICKS;
        serverStateTicks = SERVER_STATE_GAME_TICKS;
