            result.put("suggested_sell_price", Math.max(0, suggestedSellPrice));
            result.put("lowest_sell_price", Math.max(0, lowestSellPrice));
            return result;
        }
    }

    private static final class SyncEvent
    {
        String eventId;
        String eventType;
        int slotNumber;
        int itemId;
