            result.put("snapshot_at", snapshotAt);
            result.put("reason", reason);
            result.put("plugin_version", PLUGIN_VERSION);
            result.put("slots", slots == null ? Collections.emptyList() : slots);
            return result;
        }
    }

    private static final class QueuedEvent
    {
