package com.osrsflipper.sync;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.nio.file.attribute.AclEntry;
import java.nio.file.attribute.AclEntryPermission;
import java.nio.file.attribute.AclEntryType;
import java.nio.file.attribute.AclFileAttributeView;
import java.nio.file.attribute.PosixFileAttributeView;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.Collections;
import java.util.EnumSet;

/** Local user-only files: never put bearer tokens through ConfigManager or its logs/cloud sync. */
final class PairingCredentialStore
{
    private final Path root;
    private final Gson gson;

    PairingCredentialStore(Path root, Gson gson)
    {
        this.root = root;
        this.gson = gson;
    }

    PairingCredentials read(String profile) throws IOException
    {
        Path file = file(profile);
        if (!Files.exists(file, LinkOption.NOFOLLOW_LINKS)) return null;
        protect(root, true);
        protect(file, false);
        if (Files.size(file) > 4096) throw new IOException("Invalid credential file size");
        try
        {
            PairingCredentials value = gson.fromJson(Files.readString(file), PairingCredentials.class);
            if (value == null || !value.isValid() || !profile.equals(value.profile))
                throw new IOException("Invalid local credential binding");
            return value;
        }
        catch (RuntimeException exception)
        {
            // JSON parser exceptions can contain the token. Never propagate their text/cause.
            throw new IOException("Unreadable local credential binding");
        }
    }

    void write(PairingCredentials credentials) throws IOException
    {
        if (credentials == null || !credentials.isValid()) throw new IOException("Invalid credential binding");
        ByteBuffer bytes = StandardCharsets.UTF_8.encode(gson.toJson(credentials));
        if (bytes.remaining() > 4096) throw new IOException("Invalid credential file size");
        Files.createDirectories(root);
        protect(root, true);
        Path target = file(credentials.profile);
        Path temporary = Files.createTempFile(root, "pairing-", ".tmp");
        try
        {
            protect(temporary, false);
            try (FileChannel channel = FileChannel.open(temporary, StandardOpenOption.WRITE))
            {
                while (bytes.hasRemaining()) channel.write(bytes);
                channel.force(true);
            }
            Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        }
        finally
        {
            Files.deleteIfExists(temporary);
        }
    }

    void delete(String profile) throws IOException
    {
        Files.deleteIfExists(file(profile));
    }

    private Path file(String profile)
    {
        if (profile == null || !profile.matches("default|[0-9]{1,20}"))
            throw new IllegalArgumentException("Invalid RuneLite profile identity");
        return root.resolve(profile + ".json");
    }

    private static void protect(Path path, boolean directory) throws IOException
    {
        if (Files.isSymbolicLink(path)) throw new IOException("Credential paths must not be symbolic links");
        PosixFileAttributeView posix = Files.getFileAttributeView(path, PosixFileAttributeView.class);
        if (posix != null)
        {
            posix.setPermissions(PosixFilePermissions.fromString(directory ? "rwx------" : "rw-------"));
            return;
        }
        AclFileAttributeView acl = Files.getFileAttributeView(path, AclFileAttributeView.class);
        if (acl == null) throw new IOException("User-only credential permissions are unavailable");
        acl.setAcl(Collections.singletonList(AclEntry.newBuilder().setType(AclEntryType.ALLOW)
            .setPrincipal(acl.getOwner()).setPermissions(EnumSet.allOf(AclEntryPermission.class)).build()));
    }
}

package com.osrsflipper.sync;

import java.util.Locale;
import java.util.Objects;
import okhttp3.HttpUrl;

/** A bearer token is valid only for the profile, origin and identity that paired it. */
final class PairingCredentials
{
    String profile;
    String origin;
    String owner;
    String device;
    String token;

    static PairingCredentials create(String profile, HttpUrl endpoint, String owner, String device, String token)
    {
        PairingCredentials result = new PairingCredentials();
        result.profile = profile;
        result.origin = origin(endpoint);
        result.owner = clean(owner).toLowerCase(Locale.ROOT);
        result.device = clean(device);
        result.token = clean(token);
        if (!result.isValid()) throw new IllegalArgumentException("Invalid pairing credentials");
        return result;
    }

    boolean isValid()
    {
        return profile != null && profile.matches("default|[0-9]{1,20}") && origin != null && origin.length() <= 2048 &&
            origin.equals(origin(HttpUrl.parse(origin))) && owner != null && !owner.isEmpty() && owner.length() <= 254 &&
            device != null && !device.isEmpty() && device.length() <= 128 &&
            token != null && token.matches("rlt_[A-Za-z0-9_-]{40,120}");
    }

    boolean matches(String profile, HttpUrl endpoint, String owner, String device)
    {
        return isValid() && Objects.equals(this.profile, profile) &&
            Objects.equals(origin, origin(endpoint)) &&
            this.owner.equals(clean(owner).toLowerCase(Locale.ROOT)) && this.device.equals(clean(device));
    }

    static String origin(HttpUrl endpoint)
    {
        if (endpoint == null || !"https".equals(endpoint.scheme()) ||
            !endpoint.username().isEmpty() || !endpoint.password().isEmpty()) return null;
        return endpoint.newBuilder().encodedPath("/").query(null).fragment(null).build().toString();
    }

    private static String clean(String value) { return value == null ? "" : value.trim(); }
}

package com.osrsflipper.sync;

import java.util.UUID;

/** One user cash command; its identity survives transport retries and persistence. */
final class PendingCashUpdate
{
    final String requestId;
    final long balance;

    private PendingCashUpdate(String requestId, long balance)
    {
        this.requestId = requestId;
        this.balance = balance;
    }

    static PendingCashUpdate create(long balance)
    {
        if (balance < 0 || balance > Integer.MAX_VALUE) throw new IllegalArgumentException("Cash balance out of range");
        return new PendingCashUpdate(UUID.randomUUID().toString(), balance);
    }

    boolean isValid()
    {
        return balance >= 0 && balance <= Integer.MAX_VALUE && requestId != null &&
            requestId.matches("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}");
    }

    boolean hasSameIdentity(PendingCashUpdate other)
    {
        return other != null && requestId != null && requestId.equals(other.requestId);
    }
}

package com.osrsflipper.sync;

/** Already fetched Worker limits, repriced locally for the selected GE setup. */
final class QuantityCapacity
{
    final long cashAvailable;
    final double buyVolumePerHour;
    final double sellVolumePerHour;
    final long guidePrice;

    QuantityCapacity(long cashAvailable, double buyVolumePerHour, double sellVolumePerHour, long guidePrice)
    {
        this.cashAvailable = cashAvailable;
        this.buyVolumePerHour = buyVolumePerHour;
        this.sellVolumePerHour = sellVolumePerHour;
        this.guidePrice = guidePrice;
    }

    Estimate atPrices(int itemId, int buyPrice, int sellPrice, int remainingLimit, Long currentCash)
    {
        if (cashAvailable < 0 || !Double.isFinite(buyVolumePerHour) || buyVolumePerHour < 0 ||
            !Double.isFinite(sellVolumePerHour) || sellVolumePerHour < 0 || guidePrice <= 0 ||
            remainingLimit < 0 || buyPrice <= 0 || sellPrice <= 0)
        {
            return new Estimate(-1, 0, 0, "Capaciteit niet beschikbaar");
        }
        if (remainingLimit == 0) return new Estimate(0, 0, 0, "Buy limit volledig gebruikt");
        // The Worker applies its guide rule to the price references, before
        // the existing +1 buy / -1 sell tick adjustment.
        if ((long) buyPrice - 1 > guidePrice || (long) sellPrice + 1 > guidePrice)
            return new Estimate(0, 0, 0, "Prijs boven GE-richtprijs");
        long profit = GeTax.calculateProfitPerItem(buyPrice, sellPrice, itemId);
        if (profit <= 0) return new Estimate(0, 0, 0, "Geen winst na GE-tax");
        long available = Math.max(0, currentCash == null ? cashAvailable : currentCash);
        long affordable = available / buyPrice;
        if (affordable == 0) return new Estimate(0, 0, 0, "Onvoldoende beschikbare cash");
        int buyCapacity = (int) Math.min(Integer.MAX_VALUE, Math.floor(buyVolumePerHour));
        int sellCapacity = (int) Math.min(Integer.MAX_VALUE, Math.floor(sellVolumePerHour * 2));
        int quantity = (int) Math.min(Math.min(remainingLimit, affordable), Math.min(buyCapacity, sellCapacity));
        if (quantity == 0) return new Estimate(0, 0, 0, "Onvoldoende recent handelsvolume");
        long total = profit * quantity;
        long hourly = Math.round(total / (1 + quantity / sellVolumePerHour));
        return new Estimate(quantity, total, hourly, "");
    }

    static final class Estimate
    {
        final int quantity;
        final long cycleProfit;
        final long profitPerHour;
        final String reason;

        Estimate(int quantity, long cycleProfit, long profitPerHour, String reason)
        {
            this.quantity = quantity;
            this.cycleProfit = cycleProfit;
            this.profitPerHour = profitPerHour;
            this.reason = reason;
        }
    }
}

