            String quantityReason, long instantBuyAt, long instantSellAt)
        {
            this.itemId = Math.max(0, itemId);
            this.itemName = itemName == null ? "" : itemName;
            this.ranking = ranking == null ? "" : ranking;
            this.quantityCapacity = quantityCapacity;
            this.quantityReason = quantityReason == null ? "" : quantityReason;
            this.buyPrice = Math.max(0, buyPrice);
            this.sellPrice = Math.max(0, sellPrice);
            this.instantBuy = Math.max(0, instantBuy);
            this.instantSell = Math.max(0, instantSell);
            this.expectedQuantity = Math.max(0, expectedQuantity);
            this.expectedProfit = Math.max(0, expectedProfit);
            this.quantityAvailable = maximumQuantity >= 0;
            this.maximumQuantity = Math.max(0, maximumQuantity);
            this.maximumProfitPerHour = Math.max(0, maximumProfitPerHour);
            this.maximumCycleProfit = Math.max(0, maximumCycleProfit);
            this.priceUpdatedAt = Math.max(0, priceUpdatedAt);
            this.instantBuyAt = Math.max(0, instantBuyAt);
            this.instantSellAt = Math.max(0, instantSellAt);
            this.lowestSellPrice = Math.max(0, lowestSellPrice);
            this.buyLimitAvailable = officialBuyLimit > 0 && usedBuyLimit >= 0;
            this.officialBuyLimit = this.buyLimitAvailable
                ? officialBuyLimit
                : 0;
            this.usedBuyLimit = this.buyLimitAvailable
                ? Math.max(0, usedBuyLimit)
                : 0;
            int calculatedRemaining = Math.max(0, this.officialBuyLimit - this.usedBuyLimit);
            this.remainingBuyLimit = this.buyLimitAvailable
                ? (remainingBuyLimit >= 0
                    ? Math.min(Math.max(0, remainingBuyLimit), calculatedRemaining)
                    : calculatedRemaining)
                : 0;
        }

        boolean hasBuyLimit()
        {
            return buyLimitAvailable;
        }

        boolean hasQuantity()
        {
            return quantityAvailable;
        }

        int effectiveMaximumQuantity()
        {
            return buyLimitAvailable
                ? Math.min(maximumQuantity, remainingBuyLimit)
                : maximumQuantity;
        }
    }

    static final class PeriodStats
    {
        final long realizedProfit;
        final double roiPercent;
        final long profitPerHour;
        final long geTax;
        final long tradingVolume;
        final int completedFlips;
        final List<PeriodItem> items;
        final boolean attributionComplete;
        final String attributionError;

        PeriodStats(
            long realizedProfit,
            double roiPercent,
            long profitPerHour,
            long geTax,
            long tradingVolume,
            int completedFlips)
        {
            this(realizedProfit, roiPercent, profitPerHour, geTax, tradingVolume,
                completedFlips, Collections.emptyList());
        }

        PeriodStats(
            long realizedProfit,
            double roiPercent,
            long profitPerHour,
            long geTax,
            long tradingVolume,
            int completedFlips,
            List<PeriodItem> items)
        {
            this(realizedProfit, roiPercent, profitPerHour, geTax, tradingVolume,
                completedFlips, items, true, "");
        }

        PeriodStats(
            long realizedProfit,
            double roiPercent,
            long profitPerHour,
            long geTax,
            long tradingVolume,
            int completedFlips,
            List<PeriodItem> items,
            boolean attributionComplete,
            String attributionError)
        {
            this.realizedProfit = realizedProfit;
            this.roiPercent = Double.isFinite(roiPercent) ? roiPercent : 0;
            this.profitPerHour = profitPerHour;
            this.geTax = Math.max(0, geTax);
            this.tradingVolume = Math.max(0, tradingVolume);
            this.completedFlips = Math.max(0, completedFlips);
            this.items = immutableItems(items);
            this.attributionComplete = attributionComplete;
            String reason = attributionError == null ? "" : attributionError.trim();
            this.attributionError = reason.isEmpty() && !attributionComplete
                ? "Onvoldoende historische verkoopgegevens om deze periode betrouwbaar te verdelen."
                : reason;
        }

        static PeriodStats empty()
        {
            return new PeriodStats(0, 0, 0, 0, 0, 0);
        }
    }

    static final class PeriodItem
    {
        final int itemId;
        final String itemName;
        final long realizedProfit;
        final int completedFlips;

        PeriodItem(int itemId, String itemName, long realizedProfit, int completedFlips)
        {
            this.itemId = Math.max(0, itemId);
            this.itemName = itemName == null ? "" : itemName;
            this.realizedProfit = realizedProfit;
            this.completedFlips = Math.max(0, completedFlips);
        }
    }

    static final class CashBalance
    {
        final long available;
        final long reserved;
        final long total;
        final long updatedAt;
        final long version;
        final long snapshotAtMs;

        CashBalance(long available, long reserved, long total, long updatedAt)
        {
            this(available, reserved, total, updatedAt, -1, 0);
        }

        CashBalance(long available, long reserved, long total, long updatedAt, long version, long snapshotAtMs)
        {
            this.available = available;
            this.reserved = reserved;
            this.total = total;
            this.updatedAt = updatedAt;
            this.version = version;
            this.snapshotAtMs = snapshotAtMs;
        }

        CashBalance accept(CashBalance incoming)
        {
            if (incoming == null || incoming.version < version) return this;
            if (incoming.version == version)
            {
                if (snapshotAtMs > 0 && incoming.snapshotAtMs > 0 && incoming.snapshotAtMs < snapshotAtMs)
                    return this;
                if (incoming.updatedAt < updatedAt) return this;
            }
            return incoming;
        }

        static CashBalance empty()
        {
            return new CashBalance(0, 0, 0, 0);
        }
    }
}

package com.osrsflipper.sync;

import java.util.Collections;

final class SelectedGeOpportunityResolver
{
    private static final String SELECTED_SETUP = "selected_setup";
    private static final String OPEN_FLIP_CYCLE = "open_flip_cycle";

    private SelectedGeOpportunityResolver()
    {
    }

    static Resolution resolve(
        FocusedGeItemResolver.EditorContext context,
        int itemId,
        String itemName,
        String side,
        RuneliteOverviewView.Opportunity scannerOpportunity,
        MarketPriceView market,
        LastTradePriceView priceTest,
        FlipperOfferView exactActiveOffer)
    {
        return resolve(
            context,
            itemId,
            itemName,
            side,
            scannerOpportunity,
            market,
            priceTest,
            exactActiveOffer,
            null);
    }

    static Resolution resolve(
        FocusedGeItemResolver.EditorContext context,
        int itemId,
        String itemName,
        String side,
        RuneliteOverviewView.Opportunity scannerOpportunity,
        MarketPriceView market,
        LastTradePriceView priceTest,
        FlipperOfferView exactActiveOffer,
        FlipperOfferView openCycle)
    {
        return resolve(context, itemId, itemName, side, scannerOpportunity, market,
            priceTest, exactActiveOffer, openCycle, null);
    }

    static Resolution resolve(
        FocusedGeItemResolver.EditorContext context, int itemId, String itemName, String side,
        RuneliteOverviewView.Opportunity scannerOpportunity, MarketPriceView market,
        LastTradePriceView priceTest, FlipperOfferView exactActiveOffer,
        FlipperOfferView openCycle, Long currentCash)
    {
        if (itemId <= 0 || (!"buy".equals(side) && !"sell".equals(side)))
        {
            return Resolution.empty();
        }
        if (context == FocusedGeItemResolver.EditorContext.EXISTING_OFFER && exactActiveOffer != null)
        {
            int liveInstantBuy = market != null && market.instantBuyPrice > 0
                ? market.instantBuyPrice
                : exactActiveOffer.wikiInstantBuyPrice;
            int liveInstantSell = market != null && market.instantSellPrice > 0
                ? market.instantSellPrice
                : exactActiveOffer.wikiInstantSellPrice;
            FlipperOfferView liveOffer = new FlipperOfferView(
                exactActiveOffer.slotNumber,
                exactActiveOffer.itemId,
                exactActiveOffer.itemName,
                exactActiveOffer.side,
                exactActiveOffer.price,
                exactActiveOffer.totalQuantity,
                exactActiveOffer.filledQuantity,
                exactActiveOffer.status,
                exactActiveOffer.startedAt,
                exactActiveOffer.endedAt,
                exactActiveOffer.suggestedBuyPrice,
                exactActiveOffer.suggestedSellPrice,
                liveInstantBuy,
                liveInstantSell,
                exactActiveOffer.lowestSellPrice);
            RuneliteOverviewView.Opportunity active = OsrsFlipperSyncPanel.activeOfferOpportunity(
                itemId,
                side,
                Collections.singletonList(liveOffer));
            return active == null ? Resolution.empty() : new Resolution(active);
        }
        if (context != FocusedGeItemResolver.EditorContext.NEW_SETUP)
        {
            return Resolution.empty();
        }

        if ("sell".equals(side) && openCycle != null &&
            openCycle.itemId == itemId && side.equals(openCycle.side))
        {
            boolean matchingMarket = market != null && market.itemId == itemId;
            int instantBuy = matchingMarket && market.instantBuyPrice > 0
                ? market.instantBuyPrice
                : openCycle.wikiInstantBuyPrice;
            int instantSell = matchingMarket && market.instantSellPrice > 0
                ? market.instantSellPrice
                : openCycle.wikiInstantSellPrice;
            int buyPrice = openCycle.suggestedBuyPrice > 0
                ? openCycle.suggestedBuyPrice
                : openCycle.price;
            int sellPrice = openCycle.suggestedSellPrice > 0
                ? openCycle.suggestedSellPrice
                : openCycle.price;
            long priceUpdatedAt = matchingMarket
                ? Math.max(market.instantBuyAt, market.instantSellAt)
                : 0;
            RuneliteOverviewView.Opportunity frozen = new RuneliteOverviewView.Opportunity(
                itemId,
                openCycle.itemName,
                OPEN_FLIP_CYCLE,
                buyPrice,
                sellPrice,
                instantBuy,
                instantSell,
                openCycle.totalQuantity,
                0,
                openCycle.totalQuantity,
                0,
                0,
                priceUpdatedAt,
                openCycle.lowestSellPrice);
            return new Resolution(frozen);
        }

        boolean matchingMarket = market != null && market.itemId == itemId;
        long scannerUpdatedAt = scannerOpportunity == null ? 0 : scannerOpportunity.priceUpdatedAt;
        long scannerBuyAt = scannerOpportunity == null ? 0 : scannerOpportunity.instantBuyAt;
        long scannerSellAt = scannerOpportunity == null ? 0 : scannerOpportunity.instantSellAt;
        // A cached local Wiki record must not undo a newer overview. Compare
        // each price's transaction time, not when an old record was downloaded.
        int marketInstantBuy = matchingMarket && market.instantBuyAt >= scannerBuyAt
            ? market.instantBuyPrice : 0;
        int marketInstantSell = matchingMarket && market.instantSellAt >= scannerSellAt
            ? market.instantSellPrice : 0;
        if (scannerOpportunity == null && marketInstantBuy <= 0 && marketInstantSell <= 0)
        {
            return Resolution.empty();
        }

        int instantBuy = marketInstantBuy > 0
            ? marketInstantBuy
            : (scannerOpportunity == null ? 0 : scannerOpportunity.instantBuy);
        int instantSell = marketInstantSell > 0
            ? marketInstantSell
            : (scannerOpportunity == null ? 0 : scannerOpportunity.instantSell);
        int fallbackBuy = scannerOpportunity == null ? 0 : scannerOpportunity.buyPrice;
        int fallbackSell = scannerOpportunity == null ? 0 : scannerOpportunity.sellPrice;
        int buyPrice = FlipPriceResolver.buyPrice(instantSell, fallbackBuy, priceTest);
        int sellPrice = FlipPriceResolver.sellPrice(instantBuy, fallbackSell, priceTest);
        long priceUpdatedAt = Math.max(scannerUpdatedAt, Math.max(
            marketInstantBuy > 0 ? market.instantBuyAt : 0,
            marketInstantSell > 0 ? market.instantSellAt : 0));
        long instantBuyAt = marketInstantBuy > 0 ? market.instantBuyAt : scannerBuyAt;
        long instantSellAt = marketInstantSell > 0 ? market.instantSellAt : scannerSellAt;
        String resolvedItemName = itemName == null ? "" : itemName.trim();
        if (resolvedItemName.isEmpty() && scannerOpportunity != null)
        {
            resolvedItemName = scannerOpportunity.itemName;
        }

        boolean samePrices = scannerOpportunity != null &&
            scannerOpportunity.buyPrice == buyPrice && scannerOpportunity.sellPrice == sellPrice;
        QuantityCapacity capacity = scannerOpportunity == null ? null : scannerOpportunity.quantityCapacity;
        int quantity = scannerOpportunity != null && samePrices && scannerOpportunity.hasQuantity()
            ? scannerOpportunity.effectiveMaximumQuantity() : -1;
        String quantityReason = quantity < 0 ? "Aantal wacht op actuele capaciteit" : "";
        long cycleProfit = samePrices ? scannerOpportunity.maximumCycleProfit : 0;
        long hourlyProfit = samePrices ? scannerOpportunity.maximumProfitPerHour : 0;
        if (capacity != null)
        {
            QuantityCapacity.Estimate estimate = capacity.atPrices(itemId, buyPrice, sellPrice,
                scannerOpportunity.hasBuyLimit() ? scannerOpportunity.remainingBuyLimit : -1, currentCash);
            quantity = estimate.quantity;
            cycleProfit = estimate.cycleProfit;
            hourlyProfit = estimate.profitPerHour;
            quantityReason = estimate.reason;
        }
        else if (quantity >= 0 && currentCash != null && buyPrice > 0)
        {
            quantity = (int) Math.min(quantity, Math.max(0, currentCash) / buyPrice);
            cycleProfit = Math.max(0, GeTax.calculateProfitPerItem(buyPrice, sellPrice, itemId)) * quantity;
            if (quantity == 0 && currentCash < buyPrice) quantityReason = "Onvoldoende beschikbare cash";
        }
        if (buyPrice > 0 && sellPrice > 0 && GeTax.calculateProfitPerItem(buyPrice, sellPrice, itemId) <= 0)
        {
            // Even a legacy response without volume capacity cannot make a
            // known loss executable. Keep the measured prices and explain zero.
            quantity = 0;
            cycleProfit = 0;
            hourlyProfit = 0;
            quantityReason = "Geen winst na GE-tax";
        }
        if (quantity == 0 && quantityReason.isEmpty())
        {
            quantityReason = scannerOpportunity != null && scannerOpportunity.hasBuyLimit() &&
                scannerOpportunity.remainingBuyLimit == 0 ? "Buy limit volledig gebruikt" : "Geen uitvoerbaar aantal";
        }

        RuneliteOverviewView.Opportunity resolved = new RuneliteOverviewView.Opportunity(
            itemId,
            resolvedItemName,
            SELECTED_SETUP,
            buyPrice,
            sellPrice,
            instantBuy,
            instantSell,
            samePrices && capacity == null ? scannerOpportunity.expectedQuantity : 0,
            samePrices && capacity == null ? scannerOpportunity.expectedProfit : 0,
            quantity,
            hourlyProfit,
            cycleProfit,
            priceUpdatedAt,
            0,
            scannerOpportunity != null && scannerOpportunity.hasBuyLimit()
                ? scannerOpportunity.officialBuyLimit
                : -1,
            scannerOpportunity != null && scannerOpportunity.hasBuyLimit()
                ? scannerOpportunity.usedBuyLimit
                : -1,
            scannerOpportunity != null && scannerOpportunity.hasBuyLimit()
                ? scannerOpportunity.remainingBuyLimit
                : -1,
            capacity,
            quantityReason, instantBuyAt, instantSellAt);
        return new Resolution(resolved);
    }

    static boolean isSelectedSetup(RuneliteOverviewView.Opportunity opportunity)
    {
        return opportunity != null && SELECTED_SETUP.equals(opportunity.ranking);
    }

    static boolean isOpenFlipCycle(RuneliteOverviewView.Opportunity opportunity)
    {
        return opportunity != null && OPEN_FLIP_CYCLE.equals(opportunity.ranking);
    }

    static final class Resolution
    {
        final RuneliteOverviewView.Opportunity opportunity;

        private Resolution(RuneliteOverviewView.Opportunity opportunity)
        {
            this.opportunity = opportunity;
        }

        static Resolution empty()
        {
            return new Resolution(null);
        }

        int price(String side)
        {
            if (opportunity == null)
            {
                return 0;
            }
            if ("buy".equals(side))
            {
                return opportunity.buyPrice;
            }
            return "sell".equals(side) ? opportunity.sellPrice : 0;
        }
    }
}

package com.osrsflipper.sync;

final class SellTargetPriceResolver
{
    private SellTargetPriceResolver()
    {
    }

    static int provisional(
        MarketPriceView market,
        RuneliteOverviewView.Opportunity opportunity)
    {
        return provisional(market, opportunity, null);
    }

    static int provisional(
        MarketPriceView market,
        RuneliteOverviewView.Opportunity opportunity,
        LastTradePriceView priceTest)
    {
        int wikiPrice = wikiInstantBuy(market, opportunity);
        int fallback = opportunity == null ? 0 : Math.max(0, opportunity.sellPrice);
        return FlipPriceResolver.sellPrice(wikiPrice, fallback, priceTest);
    }

    /**
     * Captures the sell target when a new flip cycle starts.
     *
     * A personal Last buy price remains the primary initial anchor. The live
     * Wiki target is included here as well, so a Wiki price that is already
     * higher at the first observation does not need a second refresh before it
     * becomes visible.
     */
    static int initial(
        MarketPriceView market,
        RuneliteOverviewView.Opportunity opportunity,
        LastTradePriceView priceTest)
    {
        return raiseOnly(
            provisional(market, opportunity, priceTest),
            liveWikiRaiseCandidate(market, opportunity));
    }

    /**
     * Returns the sole automatic raise candidate for an existing flip cycle.
     *
     * Last buy is deliberately absent: a later personal price test may never
     * rewrite a running cycle. Only Wiki instabuy minus one GP can raise the
     * already stored sell target; the caller applies this candidate raise-only.
     */
    static int liveWikiRaiseCandidate(
        MarketPriceView market,
        RuneliteOverviewView.Opportunity opportunity)
    {
        return oneBelow(wikiInstantBuy(market, opportunity));
    }

    static boolean needsFreshCapture(RuneliteOverviewView.Opportunity opportunity)
    {
        return scannerSnapshot(opportunity) <= 0;
    }

    static int captured(MarketPriceView market)
    {
        int wikiPrice = market == null ? 0 : Math.max(0, market.instantBuyPrice);
        return oneBelow(wikiPrice);
    }

    static int raiseOnly(int currentPrice, int candidatePrice)
    {
        return Math.max(Math.max(0, currentPrice), Math.max(0, candidatePrice));
    }

    private static int scannerSnapshot(RuneliteOverviewView.Opportunity opportunity)
    {
        return opportunity == null ? 0 : Math.max(0, opportunity.instantBuy);
    }

    static int wikiInstantBuy(
        MarketPriceView market,
        RuneliteOverviewView.Opportunity opportunity)
    {
        int marketPrice = market == null ? 0 : Math.max(0, market.instantBuyPrice);
        return Math.max(marketPrice, scannerSnapshot(opportunity));
    }

    private static int oneBelow(int value)
    {
        int safeValue = Math.max(0, value);
        return safeValue > 1 ? safeValue - 1 : safeValue;
    }
}

package com.osrsflipper.sync;

import java.util.Collection;

final class SnapshotSyncPolicy
{
    static final int LOCAL_RECONCILE_GAME_TICKS = 500;
    static final int HOURLY_SNAPSHOT_GAME_TICKS = 6000;

    enum TickAction
    {
        NONE,
        LOCAL_RECONCILE,
        HOURLY_SNAPSHOT
    }

    enum ReconcileMode
    {
        ALWAYS,
        WHEN_CHANGED,
        NEVER
    }

    private SnapshotSyncPolicy()
    {
    }

    static TickAction tickAction(int localTicks, int hourlyTicks)
    {
        if (hourlyTicks >= HOURLY_SNAPSHOT_GAME_TICKS)
        {
            return TickAction.HOURLY_SNAPSHOT;
        }
        if (localTicks >= LOCAL_RECONCILE_GAME_TICKS)
        {
            return TickAction.LOCAL_RECONCILE;
        }
        return TickAction.NONE;
    }

    static boolean shouldQueueSnapshot(ReconcileMode mode, boolean changed)
    {
        if (mode == ReconcileMode.ALWAYS)
        {
            return true;
        }
        if (mode == ReconcileMode.WHEN_CHANGED)
        {
            return changed;
        }
        return false;
    }

    static boolean isCompleteSlotSet(Collection<Integer> slotNumbers)
    {
        if (slotNumbers == null || slotNumbers.size() != 8)
        {
            return false;
        }

        boolean[] observed = new boolean[9];
        for (Integer slotNumber : slotNumbers)
        {
            if (slotNumber == null || slotNumber < 1 || slotNumber > 8 || observed[slotNumber])
            {
                return false;
            }
            observed[slotNumber] = true;
        }

        for (int slotNumber = 1; slotNumber <= 8; slotNumber++)
        {
            if (!observed[slotNumber])
            {
                return false;
            }
        }
        return true;
    }

    static boolean canUseSuccessfulSnapshotState(
        int status,
        boolean success,
        boolean reconcileRequired,
        Collection<Integer> slotNumbers)
    {
        return status >= 200 && status < 300 &&
            success &&
            !reconcileRequired &&
            isCompleteSlotSet(slotNumbers);
    }

    static boolean canFinishManualSync(
        boolean mismatch,
        boolean snapshotPending,
        boolean snapshotInFlight,
        boolean outboxEmpty)
    {
        return !mismatch && !snapshotPending && !snapshotInFlight && outboxEmpty;
    }
}

package com.osrsflipper.sync;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.EnumMap;
import java.util.Map;

/** Independent channels: a healthy Wiki/overview/heartbeat must not hide failed GE delivery. */
final class SyncHealthTracker
{
    enum Channel
    {
        OVERVIEW("Flips/statistieken"), FOCUS("Geselecteerd item"), EVENTS("GE-updates"), STATE("GE-controle"),
        STATUS("Verbindingscontrole"), HEARTBEAT("Heartbeat"), CONNECTION("Koppeling"), STORAGE("Lokale opslag");

        final String label;

        Channel(String label)
        {
            this.label = label;
        }
    }

    private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm:ss");
    private final Map<Channel, State> states = new EnumMap<>(Channel.class);

    void clear()
    {
        states.clear();
    }

    void fail(Channel channel, String safeReason, long now)
    {
        State state = states.computeIfAbsent(channel, ignored -> new State());
        state.reason = safeReason;
        state.failures = Math.min(10, state.failures + 1);
        state.retryAt = now + retryDelaySeconds(state.failures);
    }

    void succeed(Channel channel, long now)
    {
        State state = states.computeIfAbsent(channel, ignored -> new State());
        state.lastSuccess = now;
        state.reason = null;
        state.failures = 0;
        state.retryAt = 0;
    }

    boolean failed(Channel channel)
    {
        State state = states.get(channel);
        return state != null && state.reason != null;
    }

    long retryAt(Channel channel)
    {
        State state = states.get(channel);
        return state == null ? 0 : state.retryAt;
    }

    static long retryDelaySeconds(int failures)
    {
        return Math.min(300, 15L << Math.min(5, Math.max(0, failures - 1)));
    }

    String banner(int queuedEvents)
    {
        StringBuilder text = new StringBuilder();
        for (Map.Entry<Channel, State> entry : states.entrySet())
        {
            State state = entry.getValue();
            if (state.reason == null)
            {
                continue;
            }
            if (text.length() > 0)
            {
                text.append('\n');
            }
            text.append(entry.getKey().label).append(": ").append(state.reason)
                .append(". Laatst OK: ")
                .append(state.lastSuccess <= 0 ? "nog niet" : TIME.format(
                    Instant.ofEpochSecond(state.lastSuccess).atZone(ZoneId.systemDefault())));
        }
        if (text.length() > 0)
        {
            text.append(failed(Channel.CONNECTION)
                ? "\nGegevens mogelijk verouderd. Opnieuw koppelen via Sync."
                : "\nGegevens mogelijk verouderd. Automatisch herstel actief.")
                .append("\nGE-wachtrij: ").append(Math.max(0, queuedEvents));
        }
        return text.toString();
    }

    private static final class State
    {
        private String reason;
        private int failures;
        private long lastSuccess;
        private long retryAt;
    }
}

package com.osrsflipper.sync;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;
import okhttp3.HttpUrl;

/** Storage identity deliberately excludes the rotatable bearer token. */
final class SyncStorageContext
{
    final String connectionKey;
    final String accountKey;

    private SyncStorageContext(String connectionKey, long accountHash)
    {
        this.connectionKey = connectionKey;
        this.accountKey = digest(connectionKey + ":" + Long.toUnsignedString(accountHash));
    }

    static SyncStorageContext capture(OsrsFlipperSyncConfig config, long accountHash)
    {
        String address = clean(config.webappAddress());
        HttpUrl url = HttpUrl.parse(address);
        String origin = url == null ? address : url.scheme() + "://" + url.host() + ":" + url.port();
        String owner = clean(config.ownerEmail()).toLowerCase(Locale.ROOT);
        String device = clean(config.deviceId());
        // Length prefixes avoid ambiguity even with unexpected input characters.
        String connection = part(origin) + part(owner) + part(device);
        return new SyncStorageContext(digest(connection), accountHash);
    }

    private static String part(String value)
    {
        return value.length() + ":" + value;
    }

    private static String clean(String value)
    {
        return value == null ? "" : value.trim();
    }

    private static String digest(String value)
    {
        try
        {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder result = new StringBuilder(64);
            for (byte part : digest)
            {
                result.append(Character.forDigit((part >>> 4) & 15, 16));
                result.append(Character.forDigit(part & 15, 16));
            }
            return result.toString();
        }
        catch (NoSuchAlgorithmException exception)
        {
            throw new IllegalStateException("SHA-256 is required by Java", exception);
        }
    }
}

package com.osrsflipper.sync;

import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.LoggerContext;
import ch.qos.logback.classic.turbo.TurboFilter;
import ch.qos.logback.core.spi.FilterReply;
import org.slf4j.LoggerFactory;
import org.slf4j.Marker;

/** Suppress legacy ConfigManager token logs, including profile loads before plugin startup. */
public final class TokenLogFilter extends TurboFilter
{
    public static synchronized void install()
    {
        if (!(LoggerFactory.getILoggerFactory() instanceof LoggerContext)) return;
        LoggerContext context = (LoggerContext) LoggerFactory.getILoggerFactory();
        for (TurboFilter filter : context.getTurboFilterList())
            if (filter instanceof TokenLogFilter) return;
        TokenLogFilter filter = new TokenLogFilter();
        filter.start();
        context.addTurboFilter(filter);
    }

    @Override
    public FilterReply decide(Marker marker, Logger logger, Level level, String format,
        Object[] parameters, Throwable throwable)
    {
        if (containsSecret(format)) return FilterReply.DENY;
        if (parameters != null)
            for (Object parameter : parameters)
                if (parameter instanceof String && containsSecret((String) parameter)) return FilterReply.DENY;
        return FilterReply.NEUTRAL;
    }

    private static boolean containsSecret(String value)
    {
        return value != null && (value.contains("osrsflippersync.deviceToken") ||
            (value.contains("rlt_") && value.matches("(?s).*rlt_[A-Za-z0-9_-]{40,120}.*")));
    }
}

package com.osrsflipper.sync;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import com.google.gson.JsonObject;

/** Worker overview contract: validation and conversion without client or network state. */
final class WorkerOverviewResponse
{
    private boolean success;
    private long generated_at;
    private long market_generated_at;
    private Integer refresh_after_seconds;
    private OpportunityLists opportunities;
    private OverviewStats stats;
    private List<PriceTestData> price_tests;
    private JsonObject cash;
    private OverviewAvailability availability;
    private MarketRefresh market_refresh;

    boolean isComplete()
    {
        return success && generated_at > 0 && opportunities != null &&
            opportunities.hourly != null && validOpportunityRows(opportunities.hourly) &&
            validOpportunityRows(opportunities.expected) &&
            (opportunities.focus == null || opportunities.focus.item_id > 0) &&
            stats != null && stats.today != null &&
            stats.month != null && stats.total != null && stats.today.isComplete() &&
            stats.month.isComplete() && stats.total.isComplete() && cash != null &&
            WorkerResponseValidation.cashBalance(cash) != null && price_tests != null;
    }

    private static boolean validOpportunityRows(List<OpportunityData> rows)
    {
        if (rows == null) return true;
        for (OpportunityData row : rows)
        {
            if (row == null || row.item_id <= 0) return false;
        }
        return true;
    }

    boolean matchesFocusItem(int itemId)
    {
        return itemId <= 0 || opportunities == null || opportunities.focus == null ||
            opportunities.focus.item_id == itemId;
    }

    int refreshAfterSeconds()
    {
        return refresh_after_seconds == null ? 60 : Math.max(15, Math.min(60, refresh_after_seconds));
    }

    boolean opportunitiesAvailable()
    {
        // Oudere Worker-versies kenden availability nog niet en leverden bij
        // succes altijd volledige kansen. Dat antwoord blijft compatibel.
        return availability == null || availability.opportunities;
    }

    private boolean marketStale()
    {
        return (availability != null && availability.degraded) ||
            (market_refresh != null && (market_refresh.stale || market_refresh.degraded)) ||
            (market_generated_at > 0 && generated_at - market_generated_at > 15 * 60);
    }

    boolean topOpportunitiesAvailable()
    {
        // A degraded scanner can successfully return [] after discarding all
        // expired prices. That is not evidence that no profitable flips exist.
        return opportunitiesAvailable() && !(marketStale() &&
            opportunityViews(opportunities == null ? null : opportunities.hourly).isEmpty());
    }

    RuneliteOverviewView toView()
    {
        return toView(null);
    }

    RuneliteOverviewView toView(RuneliteOverviewView previous)
    {
        return toView(previous, 0);
    }

    RuneliteOverviewView toView(RuneliteOverviewView previous, int requestFocusItemId)
    {
        RuneliteOverviewView prior = previous == null ? RuneliteOverviewView.empty() : previous;
        boolean focused = requestFocusItemId > 0;
        boolean available = topOpportunitiesAvailable();
        boolean replaceTop = !focused && available;
        // The request scope is captured before HTTP starts. A focused scan is
        // only advice for that item, even when its hourly list happens to be empty.
        List<RuneliteOverviewView.Opportunity> expected = replaceTop
            ? opportunityViews(opportunities == null ? null : opportunities.expected) : prior.expected;
        List<RuneliteOverviewView.Opportunity> hourly = replaceTop
            ? opportunityViews(opportunities == null ? null : opportunities.hourly) : prior.hourly;
        RuneliteOverviewView.Opportunity focus = replaceTop ? null : prior.focus;
        if (opportunitiesAvailable() && opportunities != null && opportunities.focus != null)
        {
            focus = opportunities.focus.toView();
        }
        else if (focused && opportunitiesAvailable())
        {
            focus = null;
        }
        return new RuneliteOverviewView(
            expected,
            hourly,
            focus,
            periodView(stats == null ? null : stats.today),
            periodView(stats == null ? null : stats.month),
            periodView(stats == null ? null : stats.total),
            priceTestViews(price_tests),
            prior.cash.accept(WorkerResponseValidation.cashBalance(cash)),
            replaceTop ? (market_generated_at > 0 ? market_generated_at : generated_at) : prior.generatedAt,
            replaceTop || prior.topOpportunitiesLoaded,
            focused ? prior.marketAvailable : available,
            focused ? prior.marketStale : !available || marketStale());
    }

    private static List<LastTradePriceView> priceTestViews(List<PriceTestData> rows)
    {
        if (rows == null || rows.isEmpty())
        {
            return Collections.emptyList();
        }
        List<LastTradePriceView> result = new ArrayList<>();
        for (PriceTestData row : rows)
        {
            if (row != null && row.item_id > 0)
            {
                result.add(row.toView());
            }
        }
        return result;
    }

    private static List<RuneliteOverviewView.Opportunity> opportunityViews(List<OpportunityData> rows)
    {
        if (rows == null || rows.isEmpty())
        {
            return Collections.emptyList();
        }
        List<RuneliteOverviewView.Opportunity> result = new ArrayList<>();
        for (OpportunityData row : rows)
        {
            if (row != null && row.item_id > 0)
            {
                result.add(row.toView());
            }
        }
        return result;
    }

    private static RuneliteOverviewView.PeriodStats periodView(PeriodStatsData row)
    {
        if (row != null && Boolean.FALSE.equals(row.attribution_complete))
        {
            // Een expliciet onbetrouwbare periode is geen kapotte overview.
            // Negeer eventuele gedeeltelijke cijfers zonder de andere data te blokkeren.
            return new RuneliteOverviewView.PeriodStats(
                0, 0, 0, 0, 0, 0, Collections.emptyList(), false, row.attribution_error);
        }
        return row == null
            ? RuneliteOverviewView.PeriodStats.empty()
            : new RuneliteOverviewView.PeriodStats(
                row.realized_profit,
                row.roi_percent,
                row.profit_per_hour,
                row.ge_tax,
                row.trading_volume,
                row.completed_flips,
                periodItemViews(row.items));
    }

    private static List<RuneliteOverviewView.PeriodItem> periodItemViews(List<PeriodItemData> rows)
    {
        if (rows == null || rows.isEmpty())
        {
            return Collections.emptyList();
        }
        List<RuneliteOverviewView.PeriodItem> result = new ArrayList<>();
        for (PeriodItemData row : rows)
        {
            if (row != null && row.item_id > 0 && row.realized_profit != 0)
            {
                result.add(new RuneliteOverviewView.PeriodItem(
                    row.item_id,
                    row.item_name,
                    row.realized_profit,
                    row.completed_flips));
            }
        }
        return result;
    }
    List<MarketPriceView> marketPriceObservations()
    {
        List<MarketPriceView> result = new ArrayList<>();
        if (opportunities == null) return result;
        if (opportunities.expected != null)
            for (OpportunityData row : opportunities.expected) if (row != null) result.add(row.priceView());
        if (opportunities.hourly != null)
            for (OpportunityData row : opportunities.hourly) if (row != null) result.add(row.priceView());
        if (opportunities.focus != null) result.add(opportunities.focus.priceView());
        return result;
    }

    private static final class OpportunityLists
    {
        List<OpportunityData> expected;
        List<OpportunityData> hourly;
        OpportunityData focus;
    }

    private static final class OpportunityData
    {
        int item_id;
        String item_name;
        String ranking;
        int buy_price;
        int sell_price;
        int instant_buy;
        int instant_sell;
        int expected_quantity;
        long expected_profit;
        Integer maximum_quantity;
        int official_buy_limit;
        int used_buy_limit;
        int remaining_buy_limit;
        long maximum_profit_per_hour;
        long maximum_cycle_profit;
        long price_updated_at;
        Long instant_buy_at;
        Long instant_sell_at;
        QuantityCapacityData quantity_capacity;

        MarketPriceView priceView()
        {
            return new MarketPriceView(item_id, instant_buy, instant_sell,
                instant_buy_at == null ? price_updated_at : instant_buy_at,
                instant_sell_at == null ? price_updated_at : instant_sell_at, 0,
                instant_buy_at != null, instant_sell_at != null);
        }

        RuneliteOverviewView.Opportunity toView()
        {
            return new RuneliteOverviewView.Opportunity(
                item_id,
                item_name,
                ranking,
                buy_price,
                sell_price,
                instant_buy,
                instant_sell,
                expected_quantity,
                expected_profit,
                maximum_quantity == null ? -1 : maximum_quantity,
                maximum_profit_per_hour,
                maximum_cycle_profit,
                price_updated_at,
                0,
                official_buy_limit,
                used_buy_limit,
                remaining_buy_limit,
                quantity_capacity == null ? null : quantity_capacity.toView(),
                "", instant_buy_at == null ? price_updated_at : instant_buy_at,
                instant_sell_at == null ? price_updated_at : instant_sell_at);
        }
    }

    private static final class QuantityCapacityData
    {
        Long cash_available;
        Double buy_volume_per_hour;
        Double sell_volume_per_hour;
        Long guide_price;

        QuantityCapacity toView()
        {
            return cash_available == null || buy_volume_per_hour == null ||
                sell_volume_per_hour == null || guide_price == null
                ? null : new QuantityCapacity(cash_available, buy_volume_per_hour, sell_volume_per_hour, guide_price);
        }
    }

    private static final class OverviewStats
    {
        PeriodStatsData today;
        PeriodStatsData month;
        PeriodStatsData total;
    }

    private static final class PeriodStatsData
    {
        Long realized_profit;
        Double roi_percent;
        Long profit_per_hour;
        Long ge_tax;
        Long trading_volume;
        Integer completed_flips;
        List<PeriodItemData> items;
        Boolean attribution_complete;
        String attribution_error;

        boolean isComplete()
        {
            return Boolean.FALSE.equals(attribution_complete) ||
                realized_profit != null && roi_percent != null && Double.isFinite(roi_percent) &&
                profit_per_hour != null && ge_tax != null && trading_volume != null &&
                completed_flips != null && items != null;
        }
    }

    private static final class OverviewAvailability
    {
        boolean personal_data;
        boolean market_data;
        boolean opportunities;
        boolean degraded;
        String error_code;
    }

    private static final class MarketRefresh
    {
        boolean stale;
        boolean degraded;
    }

    private static final class PeriodItemData
    {
        int item_id;
        String item_name;
        long realized_profit;
        int completed_flips;
    }

    private static final class PriceTestData
    {
        int item_id;
        int last_buy_price;
        int last_sell_price;
        long last_buy_at;
        long last_sell_at;
        long cleared_at;

        LastTradePriceView toView()
        {
            return new LastTradePriceView(
                item_id,
                last_buy_price,
                last_sell_price,
                last_buy_at,
                last_sell_at,
                cleared_at);
        }
    }

}

package com.osrsflipper.sync;

import java.util.Objects;

/**
 * Owns the single in-flight request to the OSRS Flip Tracker Worker.
 *
 * <p>The Wiki price API deliberately does not use this coordinator. A request
 * token is normally the corresponding OkHttp {@code Call}; accepting an
 * opaque token keeps the scheduling rules independently testable.</p>
 */
final class WorkerRequestCoordinator
{
    enum Kind
    {
        PAIRING,
        STATUS,
        HEARTBEAT,
        EVENT,
        SNAPSHOT,
        STATE,
        OVERVIEW,
        CASH
    }

    enum Cancellation
    {
        NONE,
        OVERVIEW_PREEMPTED,
        CONTEXT_CHANGED,
        SHUTDOWN
    }

    enum CompletionStatus
    {
        CURRENT,
        LOCALLY_CANCELLED,
        STALE
    }

    static final class Completion
    {
        final CompletionStatus status;
        final Cancellation cancellation;

        private Completion(CompletionStatus status, Cancellation cancellation)
        {
            this.status = status;
            this.cancellation = cancellation;
        }

        boolean shouldHandleResponse()
        {
            return status == CompletionStatus.CURRENT;
        }
    }

    private Active active;

    synchronized boolean begin(Kind kind, Object token, Runnable cancel)
    {
        Objects.requireNonNull(kind, "kind");
        Objects.requireNonNull(token, "token");
        Objects.requireNonNull(cancel, "cancel");
        if (active != null)
        {
            return false;
        }
        active = new Active(kind, token, cancel);
        return true;
    }

    synchronized boolean isActive()
    {
        return active != null;
    }

    synchronized Kind activeKind()
    {
        return active == null ? null : active.kind;
    }

    boolean cancelOverview(Cancellation cancellation)
    {
        Runnable cancel = markCancelled(Kind.OVERVIEW, cancellation);
        if (cancel == null)
        {
            return false;
        }
        cancel.run();
        return true;
    }

    boolean cancelActive(Cancellation cancellation)
    {
        Runnable cancel;
        synchronized (this)
        {
            if (active == null)
            {
                return false;
            }
            if (active.cancellation != Cancellation.NONE)
            {
                return true;
            }
            active.cancellation = requireLocalCancellation(cancellation);
            cancel = active.cancel;
        }
        cancel.run();
        return true;
    }

    synchronized Completion complete(Kind kind, Object token)
    {
        if (active == null || active.kind != kind || active.token != token)
        {
            return new Completion(CompletionStatus.STALE, Cancellation.NONE);
        }
        Cancellation cancellation = active.cancellation;
        active = null;
        return new Completion(
            cancellation == Cancellation.NONE
                ? CompletionStatus.CURRENT
                : CompletionStatus.LOCALLY_CANCELLED,
            cancellation);
    }

    private synchronized Runnable markCancelled(Kind expectedKind, Cancellation cancellation)
    {
        if (active == null || active.kind != expectedKind)
        {
            return null;
        }
        if (active.cancellation != Cancellation.NONE)
        {
            return () -> {};
        }
        active.cancellation = requireLocalCancellation(cancellation);
        return active.cancel;
    }

    private static Cancellation requireLocalCancellation(Cancellation cancellation)
    {
        if (cancellation == null || cancellation == Cancellation.NONE)
        {
            throw new IllegalArgumentException("A local cancellation reason is required");
        }
        return cancellation;
    }

    private static final class Active
    {
        private final Kind kind;
        private final Object token;
        private final Runnable cancel;
        private Cancellation cancellation = Cancellation.NONE;

        private Active(Kind kind, Object token, Runnable cancel)
        {
            this.kind = kind;
            this.token = token;
            this.cancel = cancel;
        }
    }
}

package com.osrsflipper.sync;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.Locale;

/** Validate the existing Worker contracts before acknowledging local commands. */
final class WorkerResponseValidation
{
    static long snapshotContinuationDelaySeconds(String body, String snapshotId)
    {
        try
        {
            JsonObject root = new JsonParser().parse(body).getAsJsonObject();
            if (!explicitFalse(root, "success") || !bool(root, "retryable") ||
                !explicitFalse(root, "reconcile_required") ||
                !"snapshot_processing".equals(string(root, "code"))) return 0;
            // Legacy chunk responses may omit the ID. Their HTTP callback is
            // already bound to the same immutable snapshot and account context.
            if (root.has("snapshot_id") && !string(root, "snapshot_id").equals(snapshotId)) return 0;
            if (root.has("snapshot") &&
                !string(root.getAsJsonObject("snapshot"), "snapshot_id").equals(snapshotId)) return 0;
            if (!root.has("retry_after_ms")) return 1;
            long milliseconds = integer(root, "retry_after_ms");
            return milliseconds > 0 && milliseconds <= 30_000 ? Math.max(1, (milliseconds + 999) / 1000) : 0;
        }
        catch (RuntimeException exception) { return 0; }
    }

    private static boolean explicitFalse(JsonObject root, String name)
    {
        JsonElement value = root.get(name);
        return value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isBoolean() &&
            !value.getAsBoolean();
    }

    static long eventContinuationDelaySeconds(String body, String eventId)
    {
        try
        {
            JsonObject root = new JsonParser().parse(body).getAsJsonObject();
            JsonElement success = root.get("success");
            if (success == null || !success.isJsonPrimitive() || !success.getAsJsonPrimitive().isBoolean() ||
                success.getAsBoolean() || !bool(root, "retryable") ||
                !"event_processing".equals(string(root, "code")) ||
                eventId == null || !eventId.equals(string(root, "event_id"))) return 0;
            long milliseconds = integer(root, "retry_after_ms");
            return milliseconds > 0 && milliseconds <= 30_000 ? Math.max(1, (milliseconds + 999) / 1000) : 0;
        }
        catch (RuntimeException exception) { return 0; }
    }

    static boolean eventContinuationReady(int statusCode, String body, String eventId)
    {
        if (statusCode != 202 || eventContinuationDelaySeconds(body, eventId) <= 0) return false;
        return continuationReady(body);
    }

    static boolean snapshotContinuationReady(int statusCode, String body, String snapshotId)
    {
        if (statusCode != 202 || snapshotId == null || snapshotId.isEmpty() ||
            snapshotContinuationDelaySeconds(body, snapshotId) <= 0 || !continuationReady(body)) return false;
        try
        {
            JsonObject root = new JsonParser().parse(body).getAsJsonObject();
            // Fast progress must explicitly echo this durable intent. Legacy
            // responses without an identity retain their ordinary retry delay.
            return root.has("snapshot_id") && snapshotId.equals(string(root, "snapshot_id")) ||
                root.has("snapshot") && snapshotId.equals(string(root.getAsJsonObject("snapshot"), "snapshot_id"));
        }
        catch (RuntimeException exception) { return false; }
    }

    private static boolean continuationReady(String body)
    {
        try
        {
            JsonObject root = new JsonParser().parse(body).getAsJsonObject();
            return bool(root, "continuation_ready") && explicitFalse(root, "reconcile_required") &&
                root.has("retry_after_ms") && integer(root, "retry_after_ms") > 0;
        }
        catch (RuntimeException exception) { return false; }
    }

    static boolean cash(String body)
    {
        return cashBalance(body) != null;
    }

    static RuneliteOverviewView.CashBalance cashBalance(String body)
    {
        try { return cashBalance(successful(body).getAsJsonObject("cash")); }
        catch (RuntimeException exception) { return null; }
    }

    static RuneliteOverviewView.CashBalance cashBalance(JsonObject cash)
    {
        try
        {
            long available = integer(cash, "available");
            long reserved = integer(cash, "reserved");
            long updatedAt = integer(cash, "updated_at");
            long total = integer(cash, "available_plus_reserved");
            long version = cash.has("version") ? integer(cash, "version") : -1;
            long snapshotAtMs = cash.has("snapshot_at_ms") ? integer(cash, "snapshot_at_ms") : 0;
            if (reserved < 0 || updatedAt < 0 || snapshotAtMs < 0 ||
                (cash.has("version") && version < 0) || Math.addExact(available, reserved) != total)
                return null;
            // Reconciliation may legitimately report negative free cash. Keep
            // that signed balance instead of silently displaying an invented zero.
            return new RuneliteOverviewView.CashBalance(available, reserved, total,
                updatedAt, version, snapshotAtMs);
        }
        catch (RuntimeException exception) { return null; }
    }

    static boolean status(String body, String deviceId, String ownerEmail)
    {
        try
        {
            JsonObject root = successful(body);
            JsonObject device = root.getAsJsonObject("device");
            return integer(root, "server_time") > 0 && bool(device, "active") &&
                "active".equals(string(device, "status")) &&
                string(device, "device_id").equals(deviceId) &&
                sameOwner(string(root.getAsJsonObject("owner"), "email"), ownerEmail);
        }
        catch (RuntimeException exception) { return false; }
    }

    static boolean heartbeat(String body, String deviceId, String ownerEmail)
    {
        try
        {
            JsonObject root = successful(body);
            return integer(root, "heartbeat_at") > 0 && "active".equals(string(root, "status")) &&
                string(root, "device_id").equals(deviceId) &&
                sameOwner(string(root, "owner_email"), ownerEmail);
        }
        catch (RuntimeException exception) { return false; }
    }

    private static boolean sameOwner(String actual, String expected)
    {
        return expected != null && !actual.isEmpty() &&
            actual.trim().toLowerCase(Locale.ROOT).equals(expected.trim().toLowerCase(Locale.ROOT));
    }

    private static JsonObject successful(String body)
    {
        JsonObject root = new JsonParser().parse(body).getAsJsonObject();
        if (!bool(root, "success")) throw new IllegalArgumentException("Missing success acknowledgement");
        return root;
    }

    private static boolean bool(JsonObject object, String key)
    {
        JsonElement value = object.get(key);
        return value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isBoolean() && value.getAsBoolean();
    }

    private static String string(JsonObject object, String key)
    {
        JsonElement value = object.get(key);
        if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isString())
            throw new IllegalArgumentException("Missing string field");
        return value.getAsString();
    }

    private static long integer(JsonObject object, String key)
    {
        JsonElement value = object.get(key);
        if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber() ||
            !value.getAsString().matches("-?[0-9]+")) throw new IllegalArgumentException("Missing integer field");
        long result = Long.parseLong(value.getAsString());
        if (result < -9_007_199_254_740_991L || result > 9_007_199_254_740_991L)
            throw new IllegalArgumentException("Unsafe Worker integer");
        return result;
    }
}

package com.osrsflipper.sync;

import java.util.Arrays;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class ActiveOfferOpportunityTest
{
    @Test
    public void focusedExistingOfferFallsBackToMatchingLocalSlot()
    {
        FlipperOfferView buy = offer(1, "buy", 641, 756, 640);
        FlipperOfferView sell = offer(2, "sell", 700, 757, 639);

        RuneliteOverviewView.Opportunity opportunity =
            OsrsFlipperSyncPanel.activeOfferOpportunity(
                21163, "sell", Arrays.asList(buy, sell));

        assertEquals("active_sell", opportunity.ranking);
        assertEquals(700, opportunity.sellPrice);
        assertEquals(757, opportunity.instantBuy);
        assertEquals(639, opportunity.instantSell);
    }

    @Test
    public void missingSlotDoesNotInventAnOpportunity()
    {
        assertNull(OsrsFlipperSyncPanel.activeOfferOpportunity(
            999, "buy", Arrays.asList(offer(1, "buy", 100, 110, 90))));
    }

    @Test
    public void activeBuyKeepsItsFrozenGuidanceAheadOfLaterPriceTests()
    {
        FlipperOfferView buy = offer(1, "buy", 292_362, 302_073, 292_361);
        RuneliteOverviewView.Opportunity live = new RuneliteOverviewView.Opportunity(
            21163, "Emerald amulet", "focus",
            296_550, 300_168, 300_169, 296_549,
            50, 1_000, 50, 1_000, 100_000, 2);
        RuneliteOverviewView overview = new RuneliteOverviewView(
            java.util.Collections.emptyList(),
            java.util.Collections.emptyList(),
            live,
            null,
            null,
            null,
            2);

        RuneliteOverviewView.Opportunity focused = OsrsFlipperSyncPanel.focusedOpportunity(
            21163,
            "buy",
            overview,
            java.util.Collections.singletonList(buy));

        assertEquals(292_362, focused.buyPrice);
        assertEquals(700, focused.sellPrice);
        assertEquals(302_073, focused.instantBuy);
        assertEquals(292_361, focused.instantSell);

        LastTradePriceView laterPriceTest = new LastTradePriceView(
            21163,
            310_000,
            305_000,
            3,
            3);
        assertEquals(292_362,
            OsrsFlipperSyncPanel.displayedBuyPrice(focused, laterPriceTest));
        assertEquals(700,
