    @Test
    public void concurrentCallsOnOneJournalNeverLoseAnAppend() throws Exception
    {
        EventJournal journal = new EventJournal(
            temporary.newFolder().toPath(),
            "context",
            GSON);

        CountDownLatch start =
            new CountDownLatch(1);

        AtomicReference<Throwable> failure =
            new AtomicReference<>();

        List<Thread> writers =
            new ArrayList<>();

        for (int writer = 0; writer < 2; writer++)
        {
            final int writerId = writer;

            Thread thread = new Thread(
                () ->
                {
                    try
                    {
                        start.await();

                        for (int index = 0; index < 15; index++)
                        {
                            journal.append(
                                writerId + "-" + index,
                                payload(index));
                        }
                    }
                    catch (Throwable exception)
                    {
                        failure.compareAndSet(
                            null,
                            exception);
                    }
                });

            writers.add(thread);
            thread.start();
        }

        start.countDown();

        for (Thread writer : writers)
        {
            writer.join(10_000);

            assertFalse(
                "Writer did not finish",
                writer.isAlive());
        }

        if (failure.get() != null)
        {
            throw new AssertionError(
                failure.get());
        }

        assertEquals(
            30,
            journal.size());

        assertEquals(
            30,
            journal
                .readHead(500)
                .stream()
                .map(entry -> entry.eventId)
                .distinct()
                .count());
    }

    @Test
    public void migrationMarkerPreventsResurrectionAfterPartialImportAndAcknowledgement() throws Exception
    {
        Path root = temporary.newFolder().toPath();

        EventJournal partial =
            new EventJournal(root, "context", GSON);

        partial.append(
            "first",
            payload(1));

        assertFalse(
            partial.legacyImported());

        List<EventJournal.Entry> legacy = List.of(
            new EventJournal.Entry(
                "first",
                payload(1)),
            new EventJournal.Entry(
                "second",
                payload(2)));

        EventJournal resumed =
            new EventJournal(root, "context", GSON);

        resumed.importLegacy(
            legacy,
            "{\"pendingCash\":123}");

        assertTrue(
            resumed.legacyImported());

        assertEquals(
            2,
            resumed.size());

        assertTrue(
            resumed.acknowledge("first"));

        resumed.writeState(
            "{\"pendingCash\":456}");

        EventJournal afterAck =
            new EventJournal(root, "context", GSON);

        afterAck.importLegacy(
            legacy,
            "{\"pendingCash\":123}");

        assertEquals(
            1,
            afterAck.size());

        assertEquals(
            "second",
            afterAck.readHead(1).get(0).eventId);

        assertEquals(
            "{\"pendingCash\":456}",
            afterAck.readState());
    }

    @Test
    public void legacyConnectionIsBoundOnceBeforeAnyAccountIsLoaded() throws Exception
    {
        Path root =
            temporary.newFolder().toPath();

        assertEquals(
            "original-connection",
            EventJournal.claimLegacyConnection(
                root,
                "original-connection",
                GSON));

        assertEquals(
            "original-connection",
            EventJournal.claimLegacyConnection(
                root,
                "new-owner",
                GSON));
    }

    private static String payload(int value)
    {
        return "{\"event_sequence\":"
            + value
            + ",\"item_name\":\"Rune \\\"test\\\" \\n item\"}";
    }

    private static Path directory(Path root) throws IOException
    {
        try (Stream<Path> paths =
                 Files.list(root))
        {
            return paths
                .filter(Files::isDirectory)
                .findFirst()
                .orElseThrow(IOException::new);
        }
    }

    private static List<Path> entries(Path root) throws IOException
    {
        try (Stream<Path> paths =
                 Files.list(directory(root)))
        {
            return paths
                .filter(
                    path -> path
                        .toString()
                        .endsWith(".json"))
                .sorted(
                    Comparator.comparing(
                        path -> path
                            .getFileName()
                            .toString()))
                .collect(Collectors.toList());
        }
    }

    private static void expectIo(
        CheckedAction action) throws Exception
    {
        try
        {
            action.run();

            fail(
                "Expected an IOException without a queue mutation");
        }
        catch (IOException expected)
        {
            // Caller must surface this and preserve its durable queue.
        }
    }

    private interface CheckedAction
    {
        void run() throws Exception;
    }
}

