            eventAt);
    }

    private static void observeBuyGeneration(
        FlipCyclePlanBook book,
        String cycleId,
        String offerId,
        int filledQuantity,
        long eventAt)
    {
        book.recordBuy(
            cycleId,
            offerId,
            1,
            3004,
            "Snapdragon potion (unf)",
            7_631,
            7_888,
            7_786,
            Math.max(1, filledQuantity),
            filledQuantity,
            "completed",
            eventAt,
            eventAt);
    }

    private static void recordCompletedSell(
        FlipCyclePlanBook book,
        String cycleId,
        String offerId,
