    private static OsrsFlipperSyncPlugin pluginWithSnapshot(
        String side,
        String status,
        int itemId,
        int price,
        int totalQuantity,
        long startedAt,
        long endedAt) throws Exception
    {
        return pluginWithSnapshot(
            side, status, itemId, price, totalQuantity,
            startedAt, endedAt, 0, 0);
    }

    @SuppressWarnings("unchecked")
    private static OsrsFlipperSyncPlugin pluginWithSnapshot(
        String side,
        String status,
        int itemId,
        int price,
        int totalQuantity,
        long startedAt,
        long endedAt,
        long timerStartedAt,
        long lastFillAt) throws Exception
    {
        OsrsFlipperSyncPlugin plugin = new OsrsFlipperSyncPlugin();
        Object snapshot = snapshot(
            side, status, itemId, price, totalQuantity,
            startedAt, endedAt, timerStartedAt, lastFillAt);

        Field snapshotsField = OsrsFlipperSyncPlugin.class.getDeclaredField("slotSnapshots");
        snapshotsField.setAccessible(true);
        ((Map<Integer, Object>) snapshotsField.get(plugin)).put(1, snapshot);
        return plugin;
    }

    private static Object snapshot(
        String side,
        String status,
        int itemId,
        int price,
        int totalQuantity,
        long startedAt,
        long endedAt,
        long timerStartedAt,
        long lastFillAt) throws Exception
    {
        Class<?> snapshotType = Class.forName(
            "com.osrsflipper.sync.OsrsFlipperSyncPlugin$SlotSnapshot");
        Constructor<?> constructor = snapshotType.getDeclaredConstructor();
        constructor.setAccessible(true);
        Object snapshot = constructor.newInstance();
        set(snapshot, "slotNumber", 1);
        set(snapshot, "itemId", itemId);
        set(snapshot, "side", side);
        set(snapshot, "status", status);
        set(snapshot, "price", price);
        set(snapshot, "totalQuantity", totalQuantity);
        set(snapshot, "offerId", "timer-offer");
        set(snapshot, "startedAt", startedAt);
        set(snapshot, "endedAt", endedAt);
        set(snapshot, "timerStartedAt", timerStartedAt);
        set(snapshot, "lastFillAt", lastFillAt);
        return snapshot;
    }

    private static long field(Object target, String fieldName) throws Exception
    {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        Object value = field.get(target);
        return ((Number) value).longValue();
    }

    private static void assertSidebarTimer(
        OsrsFlipperSyncPlugin plugin, GeSlotTimerView overlay, long now, String expected) throws Exception
    {
        Object snapshot = snapshots(plugin).get(1);
        Method offerView = OsrsFlipperSyncPlugin.class.getDeclaredMethod("offerView", snapshot.getClass());
        offerView.setAccessible(true);
        FlipperOfferView sidebar = (FlipperOfferView) offerView.invoke(plugin, snapshot);
        assertEquals("The original offer creation time must stay intact", field(snapshot, "startedAt"), sidebar.startedAt);
        if (overlay == null)
        {
            assertNull(sidebar.timer);
        }
        else
        {
            assertNotNull(sidebar.timer);
            assertEquals(overlay.getStartedAt(), sidebar.timer.getStartedAt());
            assertEquals(overlay.getEndedAt(), sidebar.timer.getEndedAt());
            assertEquals(expected, overlay.timerText(now));
        }

        OsrsFlipperSyncPanel[] panel = new OsrsFlipperSyncPanel[1];
        SwingUtilities.invokeAndWait(() -> {
            panel[0] = new OsrsFlipperSyncPanel(null, () -> {}, () -> {}, () -> {}, () -> {}, ignored -> {});
            panel[0].updateOffers(Collections.singletonList(sidebar));
        });
        try
        {
            SwingUtilities.invokeAndWait(() -> {
                try
                {
                    Method tick = OsrsFlipperSyncPanel.class.getDeclaredMethod("updateClocks", long.class);
                    tick.setAccessible(true);
                    tick.invoke(panel[0], now);
                    Field cardsField = OsrsFlipperSyncPanel.class.getDeclaredField("offerCards");
                    cardsField.setAccessible(true);
                    List<?> cards = (List<?>) cardsField.get(panel[0]);
                    assertEquals(1, cards.size());
                    Field labelField = cards.get(0).getClass().getDeclaredField("elapsed");
                    labelField.setAccessible(true);
                    assertEquals(expected, ((JLabel) labelField.get(cards.get(0))).getText());
                }
                catch (Exception error)
                {
                    throw new AssertionError(error);
                }
            });
        }
        finally
        {
            SwingUtilities.invokeAndWait(() -> panel[0].dispose());
        }
    }

    @SuppressWarnings("unchecked")
    private static Map<Integer, Object> snapshots(OsrsFlipperSyncPlugin plugin) throws Exception
    {
        Field field = OsrsFlipperSyncPlugin.class.getDeclaredField("slotSnapshots");
        field.setAccessible(true);
        return (Map<Integer, Object>) field.get(plugin);
    }

    private static void set(Object target, String fieldName, Object value) throws Exception
    {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static GrandExchangeOffer offer(
        GrandExchangeOfferState state,
        int itemId,
        int price,
        int totalQuantity,
        int quantitySold)
    {
        return new GrandExchangeOffer()
        {
            @Override
            public int getQuantitySold()
            {
                return quantitySold;
            }

            @Override
            public int getItemId()
            {
                return itemId;
            }

            @Override
            public int getTotalQuantity()
            {
                return totalQuantity;
            }

            @Override
            public int getPrice()
            {
                return price;
            }

            @Override
            public int getSpent()
            {
                return price * quantitySold;
            }

            @Override
            public GrandExchangeOfferState getState()
            {
                return state;
            }
        };
    }
}

package com.osrsflipper.sync;

import java.awt.Font;
import java.awt.Point;
import java.awt.Rectangle;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetTextAlignment;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class GeSlotTimerOverlayTest
{
    @Test
    public void matchesOnlyTheExactVisibleBuyOrSellLabelText()
    {
        assertTrue(GeSlotTimerOverlay.isMatchingOfferLabelText("<col=ff981f>Buy</col>", "Buy"));
        assertTrue(GeSlotTimerOverlay.isMatchingOfferLabelText("  SELL  ", "Sell"));
        assertFalse(GeSlotTimerOverlay.isMatchingOfferLabelText("Buy offer", "Buy"));
        assertFalse(GeSlotTimerOverlay.isMatchingOfferLabelText("Sell", "Buy"));
        assertFalse(GeSlotTimerOverlay.isMatchingOfferLabelText(null, "Buy"));
    }

    @Test
    public void derivesTimerFontTwoPointsSmallerWithSafeMinimum()
    {
        Font base = new Font(Font.DIALOG, Font.BOLD, 12);
        Font smaller = GeSlotTimerOverlay.timerFont(base);
        Font minimum = GeSlotTimerOverlay.timerFont(base.deriveFont(6.0F));

        assertEquals(base.getFamily(), smaller.getFamily());
        assertEquals(base.getStyle(), smaller.getStyle());
        assertEquals(10.0F, smaller.getSize2D(), 0.0F);
        assertEquals(6.0F, minimum.getSize2D(), 0.0F);
    }

    @Test
    public void placesTimerImmediatelyAfterCenteredLabel()
    {
        Point location = GeSlotTimerOverlay.timerLocation(
            new Rectangle(10, 20, 100, 18),
            new Rectangle(10, 10, 160, 100),
            WidgetTextAlignment.CENTER,
            18,
            50,
            12,
            9);

        assertEquals(new Point(73, 32), location);
    }

    @Test
    public void keepsTimerInsideRightEdgeOfSlot()
    {
        Point location = GeSlotTimerOverlay.timerLocation(
            new Rectangle(100, 20, 60, 18),
            new Rectangle(100, 10, 80, 100),
            WidgetTextAlignment.RIGHT,
            20,
            55,
            12,
            9);

        assertEquals(122, location.x);
        assertEquals(32, location.y);
    }

    @Test
    public void cachedLabelMustRemainVisibleExactAndBelowTheSameRoot()
    {
        WidgetStub firstRoot = new WidgetStub("", false, new Rectangle(0, 0, 160, 100));
        WidgetStub firstLabel = new WidgetStub("<col=ff981f>Buy</col>", false,
            new Rectangle(40, 10, 80, 18));
        firstLabel.parent = firstRoot.widget;

        assertTrue(GeSlotTimerOverlay.isCachedOfferLabelValid(
            firstLabel.widget, firstRoot.widget, "Buy"));

        WidgetStub otherRoot = new WidgetStub("", false, new Rectangle(200, 0, 160, 100));
        assertFalse(GeSlotTimerOverlay.isCachedOfferLabelValid(
            firstLabel.widget, otherRoot.widget, "Buy"));

        firstLabel.hidden = true;
        assertFalse(GeSlotTimerOverlay.isCachedOfferLabelValid(
            firstLabel.widget, firstRoot.widget, "Buy"));
    }

    @Test
    public void slotCacheResetsLabelWhenRootIdentityChanges()
    {
        WidgetStub firstRoot = rootWithLabel("Buy", 0);
        WidgetStub secondRoot = rootWithLabel("Buy", 200);
        GeSlotTimerOverlay.SlotRenderCache cache = new GeSlotTimerOverlay.SlotRenderCache();

        Widget first = cache.offerLabel(firstRoot.widget, "Buy");
        Widget again = cache.offerLabel(firstRoot.widget, "Buy");
        Widget second = cache.offerLabel(secondRoot.widget, "Buy");

        assertSame(first, again);
        assertSame(secondRoot.staticChildren[0], second);
        assertFalse(first == second);

        ((WidgetStub) Proxy.getInvocationHandler(second)).parent = firstRoot.widget;
        assertNull(cache.offerLabel(secondRoot.widget, "Buy"));
    }

    private static WidgetStub rootWithLabel(String side, int x)
    {
        WidgetStub root = new WidgetStub("", false, new Rectangle(x, 0, 160, 100));
        WidgetStub label = new WidgetStub(side, false, new Rectangle(x + 40, 10, 80, 18));
        label.parent = root.widget;
        root.staticChildren = new Widget[] {label.widget};
        return root;
    }

    private static final class WidgetStub implements InvocationHandler
    {
        private final Widget widget;
        private final String text;
        private final Rectangle bounds;
        private boolean hidden;
        private Widget parent;
        private Widget[] staticChildren = new Widget[0];

        private WidgetStub(String text, boolean hidden, Rectangle bounds)
        {
            this.text = text;
            this.hidden = hidden;
            this.bounds = bounds;
            this.widget = (Widget) Proxy.newProxyInstance(
                Widget.class.getClassLoader(),
                new Class<?>[] {Widget.class},
                this);
        }

        @Override
        public Object invoke(Object proxy, Method method, Object[] arguments)
        {
            switch (method.getName())
            {
                case "getText":
                    return text;
                case "isHidden":
                    return hidden;
                case "getBounds":
                    return bounds;
                case "getParent":
                    return parent;
                case "getStaticChildren":
                    return staticChildren;
                case "getDynamicChildren":
                case "getNestedChildren":
                    return new Widget[0];
                case "toString":
                    return "WidgetStub(" + text + ")";
                default:
                    return defaultValue(method.getReturnType());
            }
        }

        private static Object defaultValue(Class<?> type)
        {
            if (!type.isPrimitive())
            {
                return null;
            }
            if (type == boolean.class)
            {
                return false;
            }
            if (type == byte.class)
            {
                return (byte) 0;
            }
            if (type == short.class)
            {
                return (short) 0;
            }
            if (type == int.class)
            {
                return 0;
            }
            if (type == long.class)
            {
                return 0L;
            }
            if (type == float.class)
            {
                return 0F;
            }
            if (type == double.class)
            {
                return 0D;
            }
            if (type == char.class)
            {
                return '\0';
            }
            return null;
        }
    }
}

