                set(h.plugin, deadline, 0L);
                if ("heartbeat".equals(route)) invoke(h.plugin, "sendHeartbeat");
                else invoke(h.plugin, "pumpWorkerRequests");
                TestCall retry = h.workerCalls().get(h.workerCalls().size() - 1);
