    private static void assertOwnerOnly(
        Path path,
        boolean directory) throws IOException
    {
        PosixFileAttributeView posix =
            Files.getFileAttributeView(
                path,
                PosixFileAttributeView.class);

        if (posix != null)
        {
            assertEquals(
                PosixFilePermissions.fromString(
                    directory
                        ? "rwx------"
                        : "rw-------"),
                posix.readAttributes()
                    .permissions());
        }
        else
        {
            AclFileAttributeView acl =
                Files.getFileAttributeView(
                    path,
                    AclFileAttributeView.class);

            assertNotNull(acl);

            List<AclEntry> entries =
                acl.getAcl();

            assertEquals(
                1,
                entries.size());

            assertEquals(
                AclEntryType.ALLOW,
                entries.get(0).type());

            assertEquals(
                acl.getOwner(),
                entries.get(0).principal());
        }
    }

    private static final class LogCapture
        implements AutoCloseable
    {
        final ListAppender<ILoggingEvent> appender =
            new ListAppender<>();

        final Logger pluginLogger =
            (Logger) LoggerFactory.getLogger(
                OsrsFlipperSyncPlugin.class);

        final Logger configLogger =
            (Logger) LoggerFactory.getLogger(
                ConfigManager.class);

        final Level pluginLevel =
            pluginLogger.getLevel();

        final Level configLevel =
            configLogger.getLevel();

        LogCapture()
        {
            appender.start();

            pluginLogger.addAppender(
                appender);

            configLogger.addAppender(
                appender);

            pluginLogger.setLevel(
                Level.DEBUG);

            configLogger.setLevel(
                Level.DEBUG);
        }

        @Override
        public void close()
        {
            pluginLogger.detachAppender(
                appender);

            configLogger.detachAppender(
                appender);

            pluginLogger.setLevel(
                pluginLevel);

            configLogger.setLevel(
                configLevel);

            appender.stop();
        }
    }

    private static final class Harness
        implements AutoCloseable
    {
        final OsrsFlipperSyncPlugin plugin =
            new OsrsFlipperSyncPlugin();

        final ScheduledExecutorService executor =
            Executors.newSingleThreadScheduledExecutor();

        final ConfigManager manager;
        final Path root;
        final List<Call> calls =
            new ArrayList<>();

        Harness(Path root) throws Exception
        {
            this.root = root;

            Client client =
                (Client) Proxy.newProxyInstance(
                    Client.class.getClassLoader(),
                    new Class<?>[]{
                        Client.class
                    },
                    (proxy, method, args) ->
                    {
                        if ("getGameState".equals(
                            method.getName()))
                        {
                            return GameState.LOGIN_SCREEN;
                        }

                        if ("getAccountHash".equals(
                            method.getName()))
                        {
                            return -1L;
                        }

                        if (method.getReturnType()
                            == boolean.class)
                        {
                            return false;
                        }

                        if (method.getReturnType()
                            == int.class)
                        {
                            return 0;
                        }

                        if (method.getReturnType()
                            == long.class)
                        {
                            return 0L;
                        }

                        return null;
                    });

            Constructor<?> constructor =
                ConfigManager.class
                    .getDeclaredConstructors()[0];

            constructor.setAccessible(true);

            manager =
                (ConfigManager) constructor.newInstance(
                    null,
                    executor,
                    new EventBus(),
                    client,
                    GSON,
                    null,
                    null,
                    null);

            profile(0L);

            Constructor<?> data =
                Class.forName(
                        "net.runelite.client.config.ConfigData")
                    .getDeclaredConstructor(
                        File.class);

            data.setAccessible(true);

            set(
                manager,
                "configProfile",
                data.newInstance(
                    root.resolveSibling(
                            "fixture.properties")
                        .toFile()));

            configure(
                "webappAddress",
                ADDRESS);

            configure(
                "ownerEmail",
                OWNER);

            configure(
                "deviceId",
                DEVICE);

            set(
                plugin,
                "configManager",
                manager);

            set(
                plugin,
                "gson",
                GSON);

            set(
                plugin,
                "client",
                client);

            set(
                plugin,
                "eventJournalRoot",
                root);

            set(
                plugin,
                "config",
                new OsrsFlipperSyncConfig()
                {
                    private String value(
                        String key)
                    {
                        return manager.getConfiguration(
                            OsrsFlipperSyncConfig.GROUP,
                            key);
                    }

                    @Override
                    public String webappAddress()
                    {
                        return value(
                            "webappAddress");
                    }

                    @Override
                    public String ownerEmail()
                    {
                        return value(
                            "ownerEmail");
                    }

                    @Override
                    public String deviceId()
                    {
                        return value(
                            "deviceId");
                    }

                    @Override
                    public String deviceToken()
                    {
                        return value(
                            "deviceToken");
                    }
                });

            set(
                plugin,
                "httpClient",
                new OkHttpClient()
                {
                    @Override
                    public Call newCall(
                        Request request)
                    {
                        Call call =
                            new TestCall(request);

                        calls.add(call);

                        return call;
                    }
                });
        }

        void configure(
            String key,
            String value)
        {
            manager.setConfiguration(
                OsrsFlipperSyncConfig.GROUP,
                key,
                value);
        }

        void profile(long id)
            throws Exception
        {
            Constructor<?> profile =
                Class.forName(
                        "net.runelite.client.config.ConfigProfile")
                    .getDeclaredConstructor(
                        long.class);

            profile.setAccessible(true);

            set(
                manager,
                "profile",
                profile.newInstance(id));
        }

        Request request(
            String address)
            throws Exception
        {
            return ((Request.Builder) invoke(
                plugin,
                "authorizedRequest",
                new Class<?>[]{
                    HttpUrl.class
                },
                HttpUrl.parse(address)))
                .get()
                .build();
        }

        @Override
        public void close()
        {
            executor.shutdownNow();
        }
    }

    private static final class TestCall
        implements Call
    {
        final Request request;
        boolean cancelled;

        TestCall(Request request)
        {
            this.request = request;
        }

        @Override
        public Request request()
        {
            return request;
        }

        @Override
        public Response execute()
        {
            throw new UnsupportedOperationException();
        }

        @Override
        public void enqueue(
            Callback callback)
        {
            throw new AssertionError(
                "Unexpected network request");
        }

        @Override
        public void cancel()
        {
            cancelled = true;
        }

        @Override
        public boolean isExecuted()
        {
            return false;
        }

        @Override
        public boolean isCanceled()
        {
            return cancelled;
        }

        @Override
        public Timeout timeout()
        {
            return Timeout.NONE;
        }

        @Override
        public Call clone()
        {
            return new TestCall(request);
        }
    }

    private static Object get(
        Object target,
        String name) throws Exception
    {
        Field field =
            target.getClass()
                .getDeclaredField(name);

        field.setAccessible(true);

        return field.get(target);
    }

    private static void set(
        Object target,
        String name,
        Object value) throws Exception
    {
        Field field =
            target.getClass()
                .getDeclaredField(name);

        field.setAccessible(true);

        field.set(
            target,
            value);
    }

    private static Object invoke(
        Object target,
        String name) throws Exception
    {
        return invoke(
            target,
            name,
            new Class<?>[0]);
    }

    private static Object invoke(
        Object target,
        String name,
        Class<?>[] types,
        Object... values) throws Exception
    {
        Method method =
            target.getClass()
                .getDeclaredMethod(
                    name,
                    types);

        method.setAccessible(true);

        return method.invoke(
            target,
            values);
    }
}

