import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class SnapshotSchedulingRegressionTest
{
    @Test
    public void completeConflictFreeSnapshotResponseReplacesImmediateStateRequest() throws Exception
    {
        OsrsFlipperSyncPlugin plugin = pluginWaitingForSnapshot("snapshot-complete");

        handleSnapshot(plugin, "snapshot-complete", completeEmptyState(true));

        assertFalse(booleanField(plugin, "serverStateCheckPending"));
        assertFalse(booleanField(plugin, "snapshotPending"));
        assertFalse(booleanField(plugin, "snapshotInFlight"));
        assertNull(field(plugin, "pendingSnapshot"));
        assertEquals(8, slotSnapshots(plugin).size());
    }

    @Test
    public void missingReconcileFlagFailsClosedToStateRequest() throws Exception
    {
        OsrsFlipperSyncPlugin plugin = pluginWaitingForSnapshot("snapshot-untrusted");

        handleSnapshot(plugin, "snapshot-untrusted", completeEmptyState(false));

        assertTrue(booleanField(plugin, "serverStateCheckPending"));
        assertFalse(booleanField(plugin, "snapshotPending"));
    }

    @Test
    public void dirtySnapshotKeepsItsFollowUpWhenResponseNoLongerMatches() throws Exception
    {
        OsrsFlipperSyncPlugin plugin = pluginWaitingForSnapshot("snapshot-dirty");
        set(plugin, "snapshotDirty", true);

        handleSnapshot(plugin, "snapshot-dirty", completeStateWithOccupiedFirstSlot());

        assertTrue(booleanField(plugin, "snapshotPending"));
        assertFalse(booleanField(plugin, "snapshotDirty"));
        assertFalse(booleanField(plugin, "serverStateCheckPending"));
        assertEquals("changed_during_snapshot", field(plugin, "snapshotReason"));
    }

    @Test
    public void conflictedSnapshotAlsoPreservesAChangeObservedDuringTheRequest() throws Exception
    {
        OsrsFlipperSyncPlugin plugin = pluginWaitingForSnapshot("snapshot-conflict");
        set(plugin, "snapshotDirty", true);

        handleSnapshot(
            plugin,
            "snapshot-conflict",
            409,
            "{\"success\":false,\"reconcile_required\":true,\"data\":[]}");

        assertTrue(booleanField(plugin, "snapshotPending"));
        assertFalse(booleanField(plugin, "snapshotDirty"));
        assertTrue(booleanField(plugin, "serverStateCheckPending"));
        assertEquals("changed_during_conflicted_snapshot", field(plugin, "snapshotReason"));
    }

    @Test
    public void temporaryHttpFailureRetainsTheSameDirtySnapshotIntent() throws Exception
    {
        OsrsFlipperSyncPlugin plugin = pluginWaitingForSnapshot("snapshot-retry-http");
        Object pending = field(plugin, "pendingSnapshot");
        set(plugin, "snapshotDirty", true);

        handleSnapshot(plugin, "snapshot-retry-http", 503, "{}");

        assertSame(pending, field(plugin, "pendingSnapshot"));
        assertTrue(booleanField(plugin, "snapshotPending"));
        assertTrue(booleanField(plugin, "snapshotDirty"));
        assertEquals(1, intField(pending, "attempts"));
    }

    @Test
    public void networkFailureRetainsTheSameDirtySnapshotIntent() throws Exception
    {
        OsrsFlipperSyncPlugin plugin = pluginWaitingForSnapshot("snapshot-retry-network");
        Object pending = field(plugin, "pendingSnapshot");
        set(plugin, "snapshotDirty", true);
        Method handle = OsrsFlipperSyncPlugin.class.getDeclaredMethod(
            "handleSnapshotFailure",
            String.class,
            IOException.class);
        handle.setAccessible(true);

        handle.invoke(plugin, "snapshot-retry-network", new IOException("fixture timeout"));

        assertSame(pending, field(plugin, "pendingSnapshot"));
        assertTrue(booleanField(plugin, "snapshotPending"));
        assertTrue(booleanField(plugin, "snapshotDirty"));
        assertEquals(1, intField(pending, "attempts"));
    }

    @Test
    public void slotChangeDuringSnapshotBackoffCannotAbandonTheDurableIntent() throws Exception
    {
        OsrsFlipperSyncPlugin plugin = pluginWaitingForSnapshot("snapshot-backoff");
        Object pending = field(plugin, "pendingSnapshot");
        set(pending, "attempts", 1);
        set(plugin, "snapshotInFlight", false);
        Object event = newNested("SyncEvent");
        set(event, "eventId", "newer-slot-event");

        Method enqueue = OsrsFlipperSyncPlugin.class.getDeclaredMethod(
            "enqueue",
            event.getClass());
        enqueue.setAccessible(true);
        enqueue.invoke(plugin, event);

        assertSame(pending, field(plugin, "pendingSnapshot"));
        assertTrue(booleanField(plugin, "snapshotPending"));
        assertTrue(booleanField(plugin, "snapshotDirty"));
        assertEquals(1, outbox(plugin).size());
    }

    @Test
    public void boundedWorkerSnapshotContinuationIsProgressNotAHealthFailure() throws Exception
    {
        for (int status : new int[]{202, 503})
        {
            String snapshotId = "snapshot-continuation-" + status;
            OsrsFlipperSyncPlugin plugin = pluginWaitingForSnapshot(snapshotId);
            Object pending = field(plugin, "pendingSnapshot");

            handleSnapshot(
                plugin,
                snapshotId,
                status,
                "{\"success\":false,\"retryable\":true,\"code\":\"snapshot_processing\"," +
                    "\"reconcile_required\":false}");

            assertSame(pending, field(plugin, "pendingSnapshot"));
            assertTrue(booleanField(plugin, "snapshotPending"));
            assertFalse(booleanField(plugin, "snapshotInFlight"));
            assertEquals(0, intField(pending, "attempts"));
            assertTrue(longField(pending, "nextAttemptAt") > 0L);
            assertEquals(0L, longField(plugin, "workerBackoffUntil"));
            assertEquals("", ((SyncHealthTracker) field(plugin, "syncHealth")).banner(0));
        }
    }

    @Test
    public void newSnapshotTriggerDuringBackoffQueuesAFollowUpWithoutReplacingTheIntent()
        throws Exception
    {
        OsrsFlipperSyncPlugin plugin = pluginWaitingForSnapshot("snapshot-trigger-backoff");
        Object pending = field(plugin, "pendingSnapshot");
        set(plugin, "snapshotInFlight", false);

        Method queue = OsrsFlipperSyncPlugin.class.getDeclaredMethod(
            "queueFullSnapshot",
            String.class);
        queue.setAccessible(true);
        queue.invoke(plugin, "manual_sync");

        assertSame(pending, field(plugin, "pendingSnapshot"));
        assertTrue(booleanField(plugin, "snapshotPending"));
        assertTrue(booleanField(plugin, "snapshotDirty"));
    }

    @Test
    public void authoritativeRuneLiteScanRequiresEightNonNullOffers() throws Exception
    {
        Method complete = OsrsFlipperSyncPlugin.class.getDeclaredMethod(
            "hasCompleteRuneLiteSlotArray",
            GrandExchangeOffer[].class);
        complete.setAccessible(true);

        GrandExchangeOffer[] valid = new GrandExchangeOffer[8];
        for (int slot = 0; slot < valid.length; slot++)
        {
            valid[slot] = emptyOffer();
        }
        assertTrue((Boolean) complete.invoke(null, (Object) valid));
        assertFalse((Boolean) complete.invoke(null, (Object) new GrandExchangeOffer[7]));
        assertFalse((Boolean) complete.invoke(null, (Object) new GrandExchangeOffer[9]));
        valid[4] = null;
        assertFalse((Boolean) complete.invoke(null, (Object) valid));
        assertFalse((Boolean) complete.invoke(null, new Object[]{null}));
    }

    @Test
    public void unsuccessfulStateResponseCannotBeAcceptedAsAuthoritative() throws Exception
    {
        OsrsFlipperSyncPlugin plugin = pluginWaitingForSnapshot("unused");
        set(plugin, "slotStateInFlight", true);
        set(plugin, "serverStateCheckPending", false);
        Method handle = OsrsFlipperSyncPlugin.class.getDeclaredMethod(
            "handleServerStateResponse",
            int.class,
            String.class);
        handle.setAccessible(true);

        handle.invoke(
            plugin,
            200,
            completeEmptyState(true).replace("\"success\":true", "\"success\":false"));

        assertTrue(booleanField(plugin, "serverStateCheckPending"));
        assertFalse(booleanField(plugin, "slotStateInFlight"));
        assertEquals(1, intField(plugin, "serverStateRetryAttempts"));
    }

    @Test
    public void pluginWiresEveryTriggerToTheIntendedSnapshotMode() throws Exception
    {
        String source = new String(Files.readAllBytes(Paths.get(
            "src/main/java/com/osrsflipper/sync/OsrsFlipperSyncPlugin.java")), StandardCharsets.UTF_8);
        String compact = source.replaceAll("\\s+", " ");

        assertTrue(compact.contains(
            "\"ge_open\", SnapshotSyncPolicy.ReconcileMode.WHEN_CHANGED"));
        assertTrue(compact.contains(
            "\"periodic_reconcile\", SnapshotSyncPolicy.ReconcileMode.NEVER"));
        assertTrue(compact.contains(
            "\"periodic_hourly\", SnapshotSyncPolicy.ReconcileMode.ALWAYS"));
        // Login ordering is exercised through real queued callbacks and live
        // offer fixtures in OverviewListContinuityTest, including durable recovery.
    }

    private static OsrsFlipperSyncPlugin pluginWaitingForSnapshot(String snapshotId) throws Exception
    {
        OsrsFlipperSyncPlugin plugin = new OsrsFlipperSyncPlugin();
        set(plugin, "gson", new Gson());
        set(plugin, "config", new OsrsFlipperSyncConfig()
        {
        });
        Object pending = newNested("PendingSnapshot");
        set(pending, "snapshotId", snapshotId);
        set(pending, "reason", "test");
        set(plugin, "pendingSnapshot", pending);
        set(plugin, "snapshotPending", true);
        set(plugin, "snapshotInFlight", true);
        set(plugin, "serverStateCheckPending", true);
        return plugin;
    }

    private static void handleSnapshot(
        OsrsFlipperSyncPlugin plugin,
        String snapshotId,
        String response) throws Exception
    {
        handleSnapshot(plugin, snapshotId, 200, response);
    }

    private static void handleSnapshot(
        OsrsFlipperSyncPlugin plugin,
        String snapshotId,
        int status,
        String response) throws Exception
    {
        Method handle = OsrsFlipperSyncPlugin.class.getDeclaredMethod(
            "handleSnapshotResponse",
            String.class,
            int.class,
            String.class);
        handle.setAccessible(true);
        handle.invoke(plugin, snapshotId, status, response);
    }

    private static String completeEmptyState(boolean includeReconcileFlag)
    {
        StringBuilder json = new StringBuilder("{\"success\":true");
        if (includeReconcileFlag)
        {
            json.append(",\"reconcile_required\":false");
        }
        json.append(",\"data\":[");
        for (int slot = 1; slot <= 8; slot++)
        {
            if (slot > 1)
            {
                json.append(',');
            }
            json.append("{\"slot_number\":")
                .append(slot)
                .append(",\"status\":\"empty\",\"version\":")
                .append(slot)
                .append('}');
        }
        return json.append("]}").toString();
    }

    private static String completeStateWithOccupiedFirstSlot()
    {
        StringBuilder json = new StringBuilder(
            "{\"success\":true,\"reconcile_required\":false,\"data\":[" +
                "{\"slot_number\":1,\"status\":\"active\",\"item_id\":4151," +
                "\"side\":\"buy\",\"price\":1000,\"total_quantity\":1," +
                "\"filled_quantity\":0,\"spent_amount\":0}");
        for (int slot = 2; slot <= 8; slot++)
        {
            json.append(",{\"slot_number\":")
                .append(slot)
                .append(",\"status\":\"empty\"}");
        }
        return json.append("]}").toString();
    }

    private static GrandExchangeOffer emptyOffer()
    {
        return new GrandExchangeOffer()
        {
            @Override
            public int getQuantitySold()
            {
                return 0;
            }

            @Override
            public int getItemId()
            {
                return 0;
            }

            @Override
            public int getTotalQuantity()
            {
                return 0;
            }

            @Override
            public int getPrice()
            {
                return 0;
            }

            @Override
            public int getSpent()
            {
                return 0;
            }

            @Override
            public GrandExchangeOfferState getState()
            {
                return GrandExchangeOfferState.EMPTY;
            }
        };
    }

    private static Object newNested(String simpleName) throws Exception
    {
        Class<?> type = Class.forName(
            "com.osrsflipper.sync.OsrsFlipperSyncPlugin$" + simpleName);
        Constructor<?> constructor = type.getDeclaredConstructor();
        constructor.setAccessible(true);
        return constructor.newInstance();
    }

    @SuppressWarnings("unchecked")
    private static Map<Integer, Object> slotSnapshots(OsrsFlipperSyncPlugin plugin) throws Exception
    {
        return (Map<Integer, Object>) field(plugin, "slotSnapshots");
    }

    @SuppressWarnings("unchecked")
    private static Deque<Object> outbox(OsrsFlipperSyncPlugin plugin) throws Exception
    {
        return (Deque<Object>) field(plugin, "outbox");
    }

    private static boolean booleanField(Object target, String name) throws Exception
    {
        return (Boolean) field(target, name);
    }

    private static int intField(Object target, String name) throws Exception
    {
        return (Integer) field(target, name);
    }

    private static long longField(Object target, String name) throws Exception
    {
        return (Long) field(target, name);
    }

    private static Object field(Object target, String name) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        return field.get(target);
    }

    private static void set(Object target, String name, Object value) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }
}

package com.osrsflipper.sync;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.EnumSet;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SnapshotSyncPolicyTest
{
    private static final Collection<Integer> COMPLETE_SLOTS =
        Arrays.asList(1, 2, 3, 4, 5, 6, 7, 8);

    @Test
    public void cadenceConstantsRepresentFiveMinutesAndOneHour()
    {
        assertEquals(500, SnapshotSyncPolicy.LOCAL_RECONCILE_GAME_TICKS);
        assertEquals(6000, SnapshotSyncPolicy.HOURLY_SNAPSHOT_GAME_TICKS);
    }

    @Test
    public void tickActionHonoursBothBoundariesAndLetsHourlyWin()
    {
        Object[][] cases = {
            {-1, -1, SnapshotSyncPolicy.TickAction.NONE},
            {0, 0, SnapshotSyncPolicy.TickAction.NONE},
            {499, 5999, SnapshotSyncPolicy.TickAction.NONE},
            {500, 0, SnapshotSyncPolicy.TickAction.LOCAL_RECONCILE},
            {501, 5999, SnapshotSyncPolicy.TickAction.LOCAL_RECONCILE},
            {0, 6000, SnapshotSyncPolicy.TickAction.HOURLY_SNAPSHOT},
            {499, 6001, SnapshotSyncPolicy.TickAction.HOURLY_SNAPSHOT},
            {500, 6000, SnapshotSyncPolicy.TickAction.HOURLY_SNAPSHOT},
            {Integer.MAX_VALUE, Integer.MAX_VALUE, SnapshotSyncPolicy.TickAction.HOURLY_SNAPSHOT}
        };

        for (Object[] testCase : cases)
        {
            int localTicks = (Integer) testCase[0];
            int hourlyTicks = (Integer) testCase[1];
            SnapshotSyncPolicy.TickAction expected =
                (SnapshotSyncPolicy.TickAction) testCase[2];
            assertEquals(
                "Onverwachte actie voor local=" + localTicks + ", hourly=" + hourlyTicks,
                expected,
                SnapshotSyncPolicy.tickAction(localTicks, hourlyTicks));
        }
    }

    @Test
    public void everyReconcileModeHasAnExplicitChangedAndUnchangedContract()
    {
        EnumSet<SnapshotSyncPolicy.ReconcileMode> covered =
            EnumSet.noneOf(SnapshotSyncPolicy.ReconcileMode.class);

        for (SnapshotSyncPolicy.ReconcileMode mode : SnapshotSyncPolicy.ReconcileMode.values())
        {
            covered.add(mode);
            switch (mode)
            {
                case ALWAYS:
                    assertTrue(SnapshotSyncPolicy.shouldQueueSnapshot(mode, false));
                    assertTrue(SnapshotSyncPolicy.shouldQueueSnapshot(mode, true));
                    break;
                case WHEN_CHANGED:
                    assertFalse(SnapshotSyncPolicy.shouldQueueSnapshot(mode, false));
                    assertTrue(SnapshotSyncPolicy.shouldQueueSnapshot(mode, true));
                    break;
                case NEVER:
                    assertFalse(SnapshotSyncPolicy.shouldQueueSnapshot(mode, false));
                    assertFalse(SnapshotSyncPolicy.shouldQueueSnapshot(mode, true));
                    break;
                default:
                    throw new AssertionError("Ongeteste reconciliatiemodus: " + mode);
            }
        }

        assertEquals(EnumSet.allOf(SnapshotSyncPolicy.ReconcileMode.class), covered);
        assertFalse(SnapshotSyncPolicy.shouldQueueSnapshot(null, false));
        assertFalse(SnapshotSyncPolicy.shouldQueueSnapshot(null, true));
    }

    @Test
    public void completeSlotSetRequiresEverySlotExactlyOnce()
    {
        assertTrue(SnapshotSyncPolicy.isCompleteSlotSet(COMPLETE_SLOTS));
        assertTrue(SnapshotSyncPolicy.isCompleteSlotSet(
            Arrays.asList(8, 3, 1, 7, 5, 2, 6, 4)));

        assertFalse(SnapshotSyncPolicy.isCompleteSlotSet(null));
        assertFalse(SnapshotSyncPolicy.isCompleteSlotSet(Collections.emptyList()));
        assertFalse(SnapshotSyncPolicy.isCompleteSlotSet(Arrays.asList(1, 2, 3, 4, 5, 6, 7)));
        assertFalse(SnapshotSyncPolicy.isCompleteSlotSet(
            Arrays.asList(1, 2, 3, 4, 5, 6, 7, 8, 8)));
        assertFalse(SnapshotSyncPolicy.isCompleteSlotSet(
            Arrays.asList(1, 2, 3, 4, 5, 6, 7, 7)));
        assertFalse(SnapshotSyncPolicy.isCompleteSlotSet(
            Arrays.asList(0, 1, 2, 3, 4, 5, 6, 7)));
        assertFalse(SnapshotSyncPolicy.isCompleteSlotSet(
            Arrays.asList(2, 3, 4, 5, 6, 7, 8, 9)));
        assertFalse(SnapshotSyncPolicy.isCompleteSlotSet(
            Arrays.asList(1, 2, 3, 4, null, 6, 7, 8)));
    }

    @Test
    public void successfulSnapshotStateRequiresEveryResponseInvariant()
    {
        for (int status = 0; status <= 599; status++)
        {
            boolean expected = status >= 200 && status < 300;
            assertEquals(
                "Onverwachte statusclassificatie voor HTTP " + status,
                expected,
                SnapshotSyncPolicy.canUseSuccessfulSnapshotState(
                    status,
                    true,
                    false,
                    COMPLETE_SLOTS));
        }

        assertFalse(SnapshotSyncPolicy.canUseSuccessfulSnapshotState(
            200, false, false, COMPLETE_SLOTS));
        assertFalse(SnapshotSyncPolicy.canUseSuccessfulSnapshotState(
            200, true, true, COMPLETE_SLOTS));
        assertFalse(SnapshotSyncPolicy.canUseSuccessfulSnapshotState(
            200, true, false, Arrays.asList(1, 2, 3, 4, 5, 6, 7)));
        assertFalse(SnapshotSyncPolicy.canUseSuccessfulSnapshotState(
            200, true, false, Arrays.asList(1, 2, 3, 4, 5, 6, 7, 7)));
        assertFalse(SnapshotSyncPolicy.canUseSuccessfulSnapshotState(
            200, true, false, null));
    }

    @Test
    public void manualSyncOnlyFinishesInTheSingleSafeBooleanState()
    {
        int accepted = 0;
        for (boolean mismatch : new boolean[]{false, true})
        {
            for (boolean snapshotPending : new boolean[]{false, true})
            {
                for (boolean snapshotInFlight : new boolean[]{false, true})
                {
                    for (boolean outboxEmpty : new boolean[]{false, true})
                    {
                        boolean expected = !mismatch && !snapshotPending &&
                            !snapshotInFlight && outboxEmpty;
                        boolean actual = SnapshotSyncPolicy.canFinishManualSync(
                            mismatch,
                            snapshotPending,
                            snapshotInFlight,
                            outboxEmpty);
                        assertEquals(
                            "Onverwachte manual-syncbeslissing voor mismatch=" + mismatch +
                                ", pending=" + snapshotPending +
                                ", inFlight=" + snapshotInFlight +
                                ", outboxEmpty=" + outboxEmpty,
                            expected,
                            actual);
                        if (actual)
                        {
                            accepted++;
                        }
                    }
                }
            }
        }

        assertEquals(1, accepted);
    }

    @Test
    public void mutableCollectionsAreEvaluatedFromTheirCurrentExactContents()
    {
        Collection<Integer> slots = new ArrayList<>(COMPLETE_SLOTS);
        assertTrue(SnapshotSyncPolicy.isCompleteSlotSet(slots));
        slots.remove(Integer.valueOf(8));
        slots.add(7);
        assertFalse(SnapshotSyncPolicy.isCompleteSlotSet(slots));
    }
}

package com.osrsflipper.sync;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class StatsItemFilterTest
{
    @Test
    public void separatesAndSortsProfitAndLoss()
    {
        List<RuneliteOverviewView.PeriodItem> items = Arrays.asList(
            new RuneliteOverviewView.PeriodItem(1, "Kleine winst", 100, 1),
            new RuneliteOverviewView.PeriodItem(2, "Groot verlies", -900, 1),
            new RuneliteOverviewView.PeriodItem(3, "Grote winst", 500, 1),
            new RuneliteOverviewView.PeriodItem(4, "Klein verlies", -50, 1));

        assertEquals(3, OsrsFlipperSyncPanel.visibleStatsItems(items, false).get(0).itemId);
        assertEquals(2, OsrsFlipperSyncPanel.visibleStatsItems(items, true).get(0).itemId);
    }

    @Test
    public void totalSortsEveryNonZeroItemFromHighestProfitToLargestLoss()
    {
        List<RuneliteOverviewView.PeriodItem> items = Arrays.asList(
            new RuneliteOverviewView.PeriodItem(1, "Kleine winst", 100, 1),
            new RuneliteOverviewView.PeriodItem(2, "Groot verlies", -900, 1),
            new RuneliteOverviewView.PeriodItem(3, "Grote winst", 500, 1),
            new RuneliteOverviewView.PeriodItem(4, "Klein verlies", -50, 1),
            new RuneliteOverviewView.PeriodItem(5, "Geen resultaat", 0, 1));

        List<RuneliteOverviewView.PeriodItem> total = OsrsFlipperSyncPanel.visibleStatsItems(
            items,
            OsrsFlipperSyncPanel.StatsSortChoice.TOTAL);

        assertEquals(4, total.size());
        assertEquals(3, total.get(0).itemId);
        assertEquals(1, total.get(1).itemId);
        assertEquals(4, total.get(2).itemId);
        assertEquals(2, total.get(3).itemId);
    }

    @Test
    public void labelsMatchTheThreeUserFacingChoices()
    {
        assertEquals("Winst", OsrsFlipperSyncPanel.StatsSortChoice.PROFIT.toString());
        assertEquals("Verlies", OsrsFlipperSyncPanel.StatsSortChoice.LOSS.toString());
        assertEquals("Totaal", OsrsFlipperSyncPanel.StatsSortChoice.TOTAL.toString());
    }
}

package com.osrsflipper.sync;

import org.junit.Test;
import static org.junit.Assert.*;

public class SyncHealthTrackerTest
{
    @Test
    public void unrelatedSuccessCannotHideFailedDeliveryOrOverview()
    {
        SyncHealthTracker health = new SyncHealthTracker();
        health.succeed(SyncHealthTracker.Channel.OVERVIEW, 100);
        health.fail(SyncHealthTracker.Channel.OVERVIEW, "HTTP 503", 200);
        health.fail(SyncHealthTracker.Channel.EVENTS, "netwerkfout/time-out", 201);
        long retryAt = health.retryAt(SyncHealthTracker.Channel.OVERVIEW);
        health.succeed(SyncHealthTracker.Channel.HEARTBEAT, 202);
        assertTrue(health.failed(SyncHealthTracker.Channel.OVERVIEW));
        assertTrue(health.failed(SyncHealthTracker.Channel.EVENTS));
        assertEquals(retryAt, health.retryAt(SyncHealthTracker.Channel.OVERVIEW));
        assertTrue(health.banner(7).contains("GE-wachtrij: 7"));
        assertTrue(health.banner(7).contains("Laatst OK:"));
        health.succeed(SyncHealthTracker.Channel.OVERVIEW, 203);
        assertFalse(health.failed(SyncHealthTracker.Channel.OVERVIEW));
        assertTrue(health.failed(SyncHealthTracker.Channel.EVENTS));
        health.succeed(SyncHealthTracker.Channel.EVENTS, 204);
        assertEquals("", health.banner(0));
    }

    @Test
    public void backoffIsBoundedAndOnlyOwnRecoveryResetsIt()
    {
        SyncHealthTracker health = new SyncHealthTracker();
        long[] delays = {15, 30, 60, 120, 240, 300, 300, 300};
        for (long delay : delays)
        {
            health.fail(SyncHealthTracker.Channel.OVERVIEW, "time-out", 1000);
            assertEquals(1000 + delay, health.retryAt(SyncHealthTracker.Channel.OVERVIEW));
        }
        health.succeed(SyncHealthTracker.Channel.OVERVIEW, 1400);
        assertEquals(0, health.retryAt(SyncHealthTracker.Channel.OVERVIEW));
        health.fail(SyncHealthTracker.Channel.OVERVIEW, "time-out", 1500);
        assertEquals(1515, health.retryAt(SyncHealthTracker.Channel.OVERVIEW));
    }

    @Test
    public void accountSwitchClearsOldHealthAndInvalidPairingRequestsUserAction()
    {
        SyncHealthTracker health = new SyncHealthTracker();
        health.fail(SyncHealthTracker.Channel.CONNECTION, "ongeldig", 100);
        assertTrue(health.banner(0).contains("Opnieuw koppelen via Sync"));
        assertFalse(health.banner(0).contains("Automatisch herstel actief"));
        health.clear();
        assertEquals("", health.banner(0));
        assertEquals(0, health.retryAt(SyncHealthTracker.Channel.CONNECTION));
    }
}

package com.osrsflipper.sync;

import java.util.Locale;
import org.junit.Test;
import static org.junit.Assert.*;

public class SyncStorageContextTest
{
    @Test
    public void equivalentOriginsOwnerCaseAndTokenRotationKeepTheSameContext()
    {
        SyncStorageContext original = context("https://EXAMPLE.test:443/path?query=1", " ALICE@EXAMPLE.TEST ", "device-a", "old", 42);
        SyncStorageContext rotated = context("https://example.test/other", "alice@example.test", "device-a", "new", 42);
        assertEquals(original.accountKey, rotated.accountKey);
        assertTrue(original.accountKey.matches("[0-9a-f]{64}"));
    }

    @Test
    public void everyAuthenticationAndAccountBoundaryHasItsOwnContext()
    {
        SyncStorageContext original = context("https://example.test", "alice@example.test", "device-a", "token", 42);
        assertNotEquals(original.accountKey, context("https://example.test:444", "alice@example.test", "device-a", "token", 42).accountKey);
        assertNotEquals(original.accountKey, context("https://example.test", "bob@example.test", "device-a", "token", 42).accountKey);
        assertNotEquals(original.accountKey, context("https://example.test", "alice@example.test", "device-b", "token", 42).accountKey);
        assertNotEquals(original.accountKey, context("https://example.test", "alice@example.test", "device-a", "token", 43).accountKey);
    }

    @Test
