    private static Object event(String id, int filled) throws Exception
    {
        Object event = nested("SyncEvent");
        set(event, "eventId", id);
        set(event, "eventSequence", (long) filled + 1);
        set(event, "slotNumber", 1);
        set(event, "offerId", "offer-" + id);
