import okio.Timeout;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.*;

public class WorkerAcknowledgementRecoveryTest
{
    private static final String ADDRESS = "https://acknowledgement.example.test";
    private static final String OWNER = "owner@example.test";
    private static final String DEVICE = "fixture-device";
    private static final String STATUS = "{\"success\":true,\"server_time\":123," +
        "\"device\":{\"active\":true,\"status\":\"active\",\"device_id\":\"fixture-device\"}," +
        "\"owner\":{\"email\":\"owner@example.test\"}}";
    private static final String HEARTBEAT = "{\"success\":true,\"heartbeat_at\":123," +
        "\"status\":\"active\",\"device_id\":\"fixture-device\",\"owner_email\":\"owner@example.test\"}";
    @Rule public TemporaryFolder temporary = new TemporaryFolder();

    @Test
    public void invalidSuccessfulStatusResponseKeepsPairingAndRetriesWithBackoff() throws Exception
    {
        for (String body : new String[]{"", "<html>upstream error</html>", "{\"success\":true}",
            STATUS.replace(OWNER, "different-owner@example.test")})
        {
            try (Harness harness = new Harness(temporary.newFolder().toPath()))
            {
                set(harness.plugin, "statusCheckPending", true);
                invoke(harness.plugin, "checkDeviceStatus");
                TestCall first = harness.calls.get(0);
                assertTrue(first.request.url().encodedPath().endsWith("/status"));
                first.respond(200, body);
                harness.drain();

                assertTrue(harness.health().failed(SyncHealthTracker.Channel.STATUS));
                assertTrue((boolean) get(harness.plugin, "statusCheckPending"));
                assertEquals(1, get(harness.plugin, "statusRetryAttempts"));
                assertTrue((long) get(harness.plugin, "statusNextAttemptAt") > System.currentTimeMillis() / 1000);
                assertTrue((boolean) invoke(harness.plugin, "hasDeviceToken"));
                assertEquals(OWNER, harness.manager.getConfiguration(OsrsFlipperSyncConfig.GROUP, "ownerEmail"));
                invoke(harness.plugin, "checkDeviceStatus");
                assertEquals("invalid 2xx must not trigger immediate requests", 1, harness.calls.size());

                set(harness.plugin, "workerBackoffUntil", 0L);
                set(harness.plugin, "statusNextAttemptAt", 0L);
                invoke(harness.plugin, "checkDeviceStatus");
                harness.calls.get(1).respond(200, STATUS);
                harness.drain();
                assertFalse(harness.health().failed(SyncHealthTracker.Channel.STATUS));
                assertFalse((boolean) get(harness.plugin, "statusCheckPending"));
                assertEquals(0, get(harness.plugin, "statusRetryAttempts"));
                assertEquals(0L, get(harness.plugin, "statusNextAttemptAt"));
            }
        }
    }

    @Test
    public void invalidSuccessfulHeartbeatCannotClearFailureAndNextValidReplyRecovers() throws Exception
    {
        for (String body : new String[]{"", "<html>upstream error</html>", "{\"success\":true}",
            HEARTBEAT.replace(DEVICE, "another-device")})
        {
            try (Harness harness = new Harness(temporary.newFolder().toPath()))
            {
                invoke(harness.plugin, "sendHeartbeat");
                TestCall first = harness.calls.get(0);
                assertTrue(first.request.url().encodedPath().endsWith("/heartbeat"));
                first.respond(200, body);
                harness.drain();

                assertTrue(harness.health().failed(SyncHealthTracker.Channel.HEARTBEAT));
                assertEquals(1, get(harness.plugin, "heartbeatRetryAttempts"));
                assertTrue((long) get(harness.plugin, "heartbeatNextAttemptAt") > System.currentTimeMillis() / 1000);
                assertTrue((boolean) invoke(harness.plugin, "hasDeviceToken"));
                invoke(harness.plugin, "sendHeartbeat");
                assertEquals("invalid 2xx must not trigger immediate requests", 1, harness.calls.size());

                set(harness.plugin, "workerBackoffUntil", 0L);
                set(harness.plugin, "heartbeatNextAttemptAt", 0L);
                invoke(harness.plugin, "sendHeartbeat");
                harness.calls.get(1).respond(200, HEARTBEAT);
                harness.drain();
                assertFalse(harness.health().failed(SyncHealthTracker.Channel.HEARTBEAT));
                assertEquals(0, get(harness.plugin, "heartbeatRetryAttempts"));
                assertEquals(0L, get(harness.plugin, "heartbeatNextAttemptAt"));
                assertEquals(2, harness.calls.size());
            }
        }
    }

    private static final class Harness implements AutoCloseable
    {
        final OsrsFlipperSyncPlugin plugin = new OsrsFlipperSyncPlugin();
        final ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
        final ConfigManager manager;
        final List<TestCall> calls = new ArrayList<>();
        final Deque<Runnable> callbacks = new ArrayDeque<>();
        Harness(Path root) throws Exception
        {
            Gson gson = new Gson();
            Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
                (proxy, method, args) ->
                {
                    if ("getGameState".equals(method.getName())) return GameState.LOGIN_SCREEN;
                    if (method.getReturnType() == boolean.class) return false;
                    if (method.getReturnType() == int.class) return 0;
                    if (method.getReturnType() == long.class) return -1L;
                    return null;
                });
            Constructor<?> constructor = ConfigManager.class.getDeclaredConstructors()[0];
            constructor.setAccessible(true);
            manager = (ConfigManager) constructor.newInstance(null, executor, new EventBus(), client, gson, null, null, null);
            Constructor<?> data = Class.forName("net.runelite.client.config.ConfigData").getDeclaredConstructor(File.class);
            data.setAccessible(true);
            set(manager, "configProfile", data.newInstance(root.resolve("fixture.properties").toFile()));
            manager.setConfiguration(OsrsFlipperSyncConfig.GROUP, "ownerEmail", OWNER);
            manager.setConfiguration(OsrsFlipperSyncConfig.GROUP, "deviceId", DEVICE);
            set(plugin, "configManager", manager);
            set(plugin, "gson", gson);
            set(plugin, "client", client);
            set(plugin, "eventJournalRoot", root);
            set(plugin, "config", new OsrsFlipperSyncConfig()
            {
                @Override public String webappAddress() { return ADDRESS; }
                @Override public String ownerEmail() { return manager.getConfiguration(OsrsFlipperSyncConfig.GROUP, "ownerEmail"); }
                @Override public String deviceId() { return manager.getConfiguration(OsrsFlipperSyncConfig.GROUP, "deviceId"); }
            });
            set(plugin, "pairingCredentials", PairingCredentials.create("default", HttpUrl.parse(ADDRESS), OWNER, DEVICE,
                "rlt_" + "acknowledgement-fixture".repeat(3)));
            set(plugin, "clientThread", new ClientThread()
            {
                @Override public void invokeLater(Runnable action) { callbacks.addLast(action); }
            });
            set(plugin, "httpClient", new OkHttpClient()
            {
                @Override public Call newCall(Request request)
                {
                    TestCall call = new TestCall(request);
                    calls.add(call);
                    return call;
                }
            });
            set(plugin, "started", true);
        }
        SyncHealthTracker health() throws Exception { return (SyncHealthTracker) get(plugin, "syncHealth"); }
        void drain() { while (!callbacks.isEmpty()) callbacks.removeFirst().run(); }
        @Override public void close() { executor.shutdownNow(); }
    }

    private static final class TestCall implements Call
    {
        final Request request;
        Callback callback;
        boolean cancelled;
        TestCall(Request request) { this.request = request; }
        void respond(int status, String body) throws IOException
        {
            callback.onResponse(this, new Response.Builder().request(request).protocol(Protocol.HTTP_1_1)
                .code(status).message("fixture").body(ResponseBody.create(MediaType.parse("application/json"), body)).build());
        }
        @Override public Request request() { return request; }
        @Override public Response execute() { throw new UnsupportedOperationException(); }
        @Override public void enqueue(Callback callback) { this.callback = callback; }
        @Override public void cancel() { cancelled = true; }
        @Override public boolean isExecuted() { return callback != null; }
        @Override public boolean isCanceled() { return cancelled; }
        @Override public Timeout timeout() { return Timeout.NONE; }
        @Override public Call clone() { return new TestCall(request); }
    }

    private static Object get(Object target, String name) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        return field.get(target);
    }
    private static void set(Object target, String name, Object value) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }
    private static Object invoke(Object target, String name) throws Exception
    {
        Method method = target.getClass().getDeclaredMethod(name);
        method.setAccessible(true);
        return method.invoke(target);
    }
}

package com.osrsflipper.sync;

import com.google.gson.Gson;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class WorkerRefreshCadenceTest
{
    @Test
    public void missingAdviceUsesOneMinuteAndPresentAdviceStaysBetweenFifteenAndSixtySeconds()
    {
        Gson gson = new Gson();
        assertEquals(60, gson.fromJson("{}", WorkerOverviewResponse.class).refreshAfterSeconds());
        assertEquals(60, gson.fromJson("{\"refresh_after_seconds\":null}", WorkerOverviewResponse.class).refreshAfterSeconds());
        int[][] cases = {{Integer.MIN_VALUE, 15}, {-1, 15}, {0, 15}, {14, 15},
            {15, 15}, {30, 30}, {60, 60}, {61, 60}, {Integer.MAX_VALUE, 60}};
        for (int[] entry : cases)
        {
            WorkerOverviewResponse response = gson.fromJson(
                "{\"refresh_after_seconds\":" + entry[0] + "}", WorkerOverviewResponse.class);
            assertEquals("Advice " + entry[0], entry[1], response.refreshAfterSeconds());
        }
    }
}

package com.osrsflipper.sync;

import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class WorkerRequestCoordinatorTest
{
    @Test
    public void onlyOneWorkerRequestCanBeActive()
    {
        WorkerRequestCoordinator coordinator = new WorkerRequestCoordinator();
        Object overview = new Object();
        Object event = new Object();

        assertTrue(coordinator.begin(
            WorkerRequestCoordinator.Kind.OVERVIEW, overview, () -> {}));
        assertFalse(coordinator.begin(
            WorkerRequestCoordinator.Kind.EVENT, event, () -> {}));
        assertEquals(WorkerRequestCoordinator.Kind.OVERVIEW, coordinator.activeKind());

        WorkerRequestCoordinator.Completion completion = coordinator.complete(
            WorkerRequestCoordinator.Kind.OVERVIEW, overview);
        assertTrue(completion.shouldHandleResponse());
        assertFalse(coordinator.isActive());
        assertTrue(coordinator.begin(
            WorkerRequestCoordinator.Kind.EVENT, event, () -> {}));
    }

    @Test
    public void overviewCanBePreemptedWithoutBecomingANetworkFailure()
    {
        WorkerRequestCoordinator coordinator = new WorkerRequestCoordinator();
        AtomicInteger cancellations = new AtomicInteger();
        Object overview = new Object();

        assertTrue(coordinator.begin(
            WorkerRequestCoordinator.Kind.OVERVIEW,
            overview,
            cancellations::incrementAndGet));
        assertTrue(coordinator.cancelOverview(
            WorkerRequestCoordinator.Cancellation.OVERVIEW_PREEMPTED));
        assertEquals(1, cancellations.get());
        assertTrue(coordinator.isActive());

        WorkerRequestCoordinator.Completion completion = coordinator.complete(
            WorkerRequestCoordinator.Kind.OVERVIEW, overview);
        assertEquals(
            WorkerRequestCoordinator.CompletionStatus.LOCALLY_CANCELLED,
            completion.status);
        assertEquals(
            WorkerRequestCoordinator.Cancellation.OVERVIEW_PREEMPTED,
            completion.cancellation);
        assertFalse(completion.shouldHandleResponse());
        assertFalse(coordinator.isActive());
    }

    @Test
    public void contextCancellationTargetsAnyWorkerCallAndStaleCallbacksCannotReleaseANewerCall()
    {
        WorkerRequestCoordinator coordinator = new WorkerRequestCoordinator();
        AtomicInteger cancellations = new AtomicInteger();
        Object oldCall = new Object();
        Object newCall = new Object();

        assertTrue(coordinator.begin(
            WorkerRequestCoordinator.Kind.EVENT,
            oldCall,
            cancellations::incrementAndGet));
        assertTrue(coordinator.cancelActive(
            WorkerRequestCoordinator.Cancellation.CONTEXT_CHANGED));
        assertEquals(1, cancellations.get());
        WorkerRequestCoordinator.Completion cancelled = coordinator.complete(
            WorkerRequestCoordinator.Kind.EVENT, oldCall);
        assertEquals(
            WorkerRequestCoordinator.CompletionStatus.LOCALLY_CANCELLED,
            cancelled.status);

        assertTrue(coordinator.begin(
            WorkerRequestCoordinator.Kind.STATUS, newCall, () -> {}));
        WorkerRequestCoordinator.Completion stale = coordinator.complete(
            WorkerRequestCoordinator.Kind.EVENT, oldCall);
        assertEquals(WorkerRequestCoordinator.CompletionStatus.STALE, stale.status);
        assertEquals(WorkerRequestCoordinator.Kind.STATUS, coordinator.activeKind());
    }

    @Test
    public void nonOverviewRequestsCannotBePreemptedAsOverview()
    {
        WorkerRequestCoordinator coordinator = new WorkerRequestCoordinator();
        Object event = new Object();
        assertTrue(coordinator.begin(
            WorkerRequestCoordinator.Kind.EVENT, event, () -> {}));
        assertFalse(coordinator.cancelOverview(
            WorkerRequestCoordinator.Cancellation.OVERVIEW_PREEMPTED));
        assertEquals(WorkerRequestCoordinator.Kind.EVENT, coordinator.activeKind());
    }
}

package com.osrsflipper.sync;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class WorkerRequestSchedulingTest
{
    @Test
    public void durableGeWorkAlwaysHasHighestPriority()
    {
        assertEquals(
            WorkerRequestCoordinator.Kind.SNAPSHOT,
            next(true, true, true, true, true, true, true, true));
        assertEquals(
            WorkerRequestCoordinator.Kind.EVENT,
            next(false, true, true, true, true, true, true, true));
        assertEquals(
            WorkerRequestCoordinator.Kind.SNAPSHOT,
            next(false, false, true, true, true, true, true, true));
        assertEquals(
            WorkerRequestCoordinator.Kind.STATE,
            next(false, false, false, true, true, true, true, true));
    }

    @Test
    public void lowerPriorityWorkHasADeterministicOrderAndCoalescesOutsideTheScheduler()
    {
        assertEquals(
            WorkerRequestCoordinator.Kind.CASH,
            next(false, false, false, false, true, true, true, true));
        assertEquals(
            WorkerRequestCoordinator.Kind.STATUS,
            next(false, false, false, false, false, true, true, true));
        assertEquals(
            WorkerRequestCoordinator.Kind.OVERVIEW,
            next(false, false, false, false, false, false, true, true));
        assertEquals(
            WorkerRequestCoordinator.Kind.HEARTBEAT,
            next(false, false, false, false, false, false, false, true));
        assertNull(next(false, false, false, false, false, false, false, false));
    }

    @Test
    public void unrelatedSuccessCannotEraseAnUnexpiredWorkerBackoff()
    {
        assertEquals(200, OsrsFlipperSyncPlugin.workerBackoffAfterSuccess(200, 150));
        assertEquals(0, OsrsFlipperSyncPlugin.workerBackoffAfterSuccess(200, 200));
        assertEquals(0, OsrsFlipperSyncPlugin.workerBackoffAfterSuccess(0, 150));
    }

    @Test
    public void temporaryCashFailuresRemainRetryableButPermanentClientErrorsDoNot()
    {
        assertTrue(OsrsFlipperSyncPlugin.retryableWorkerHttpStatus(408));
        assertTrue(OsrsFlipperSyncPlugin.retryableWorkerHttpStatus(425));
        assertTrue(OsrsFlipperSyncPlugin.retryableWorkerHttpStatus(429));
        assertTrue(OsrsFlipperSyncPlugin.retryableWorkerHttpStatus(500));
        assertTrue(OsrsFlipperSyncPlugin.retryableWorkerHttpStatus(503));
        assertFalse(OsrsFlipperSyncPlugin.retryableWorkerHttpStatus(400));
        assertFalse(OsrsFlipperSyncPlugin.retryableWorkerHttpStatus(404));
    }

    @Test
    public void geDeliveryPreemptsAndCoalescesAReadOnlyOverviewWithoutHealthFailure()
        throws Exception
    {
        OsrsFlipperSyncPlugin plugin = new OsrsFlipperSyncPlugin();
        WorkerRequestCoordinator coordinator = coordinator(plugin);
        AtomicInteger cancellations = new AtomicInteger();
        Object overviewCall = new Object();
        assertTrue(coordinator.begin(
            WorkerRequestCoordinator.Kind.OVERVIEW,
            overviewCall,
            cancellations::incrementAndGet));
        setBoolean(plugin, "overviewInFlight", true);
        setBoolean(plugin, "overviewInFlightFreshMarket", true);
        setBoolean(plugin, "overviewInFlightFreshBuyLimits", true);

        Method preempt = OsrsFlipperSyncPlugin.class.getDeclaredMethod(
            "preemptOverviewForGeDelivery");
        preempt.setAccessible(true);
        preempt.invoke(plugin);
        preempt.invoke(plugin);

        assertEquals(1, cancellations.get());
        assertTrue(booleanField(plugin, "overviewRefreshPending"));
        assertTrue(booleanField(plugin, "overviewFreshMarketPending"));
        assertTrue(booleanField(plugin, "overviewFreshBuyLimitsPending"));
        assertEquals("", health(plugin).banner(0));
        WorkerRequestCoordinator.Completion completion = coordinator.complete(
            WorkerRequestCoordinator.Kind.OVERVIEW, overviewCall);
        assertEquals(
            WorkerRequestCoordinator.CompletionStatus.LOCALLY_CANCELLED,
            completion.status);
        assertFalse(completion.shouldHandleResponse());
    }

    private static WorkerRequestCoordinator.Kind next(
        boolean snapshotContinuation,
        boolean event,
        boolean snapshot,
        boolean state,
        boolean cash,
        boolean status,
        boolean overview,
        boolean heartbeat)
    {
        return OsrsFlipperSyncPlugin.nextWorkerRequestKind(
            snapshotContinuation, event, snapshot, state, cash, status, overview, heartbeat);
    }

    private static WorkerRequestCoordinator coordinator(OsrsFlipperSyncPlugin plugin)
        throws Exception
    {
        Field field = OsrsFlipperSyncPlugin.class.getDeclaredField("workerRequests");
        field.setAccessible(true);
        return (WorkerRequestCoordinator) field.get(plugin);
    }

    private static SyncHealthTracker health(OsrsFlipperSyncPlugin plugin) throws Exception
    {
        Field field = OsrsFlipperSyncPlugin.class.getDeclaredField("syncHealth");
        field.setAccessible(true);
        return (SyncHealthTracker) field.get(plugin);
    }

    private static boolean booleanField(Object target, String name) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        return field.getBoolean(target);
    }

    private static void setBoolean(Object target, String name, boolean value) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.setBoolean(target, value);
    }
}

package com.osrsflipper.sync;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class WorkerResponseValidationTest
{
    private static final String READY = "{\"success\":false,\"retryable\":true," +
        "\"reconcile_required\":false,\"continuation_ready\":true,\"retry_after_ms\":1000," +
        "\"code\":\"event_processing\",\"event_id\":\"same-event\"}";

    @Test
    public void fastContinuationRequiresAnExactReadyAcknowledgementAndTheSameIdentity()
    {
        assertTrue(WorkerResponseValidation.eventContinuationReady(202, READY, "same-event"));
        assertFalse(WorkerResponseValidation.eventContinuationReady(202, READY, "other-event"));
        String snapshot = READY.replace("event_processing", "snapshot_processing")
            .replace("event_id", "snapshot_id");
        assertTrue(WorkerResponseValidation.snapshotContinuationReady(202, snapshot, "same-event"));
        assertFalse(WorkerResponseValidation.snapshotContinuationReady(202, snapshot, "other-event"));
        String nested = snapshot.replace("\"snapshot_id\":\"same-event\"", "\"snapshot\":{\"snapshot_id\":\"same-event\"}");
        assertTrue(WorkerResponseValidation.snapshotContinuationReady(202, nested, "same-event"));
        assertFalse(WorkerResponseValidation.snapshotContinuationReady(202,
            nested.replace("\"code\"", "\"snapshot_id\":\"other-event\",\"code\""), "same-event"));
        assertFalse(WorkerResponseValidation.snapshotContinuationReady(202,
            snapshot.replace(",\"snapshot_id\":\"same-event\"", ""), "same-event"));
        for (int status : new int[]{200, 400, 401, 403, 409, 413, 429, 500, 503})
        {
            assertFalse(WorkerResponseValidation.eventContinuationReady(status, READY, "same-event"));
            assertFalse(WorkerResponseValidation.snapshotContinuationReady(status, snapshot, "same-event"));
        }
    }

    @Test
    public void malformedOrLegacyProgressCannotEnterAnImmediateRetryLoop()
    {
        for (String body : new String[]{"{}", "[]", "invalid", READY.replace("true", "\"true\""),
            READY.replace(",\"continuation_ready\":true", ""),
            READY.replace("\"continuation_ready\":true", "\"continuation_ready\":false"),
            READY.replace("\"reconcile_required\":false", "\"reconcile_required\":true"),
            READY.replace("\"reconcile_required\":false,", ""),
            READY.replace("\"success\":false", "\"success\":true"),
            READY.replace("\"retry_after_ms\":1000", "\"retry_after_ms\":\"1000\""),
            READY.replace("1000", "0"), READY.replace("1000", "30001"),
            READY.replace("\"retry_after_ms\":1000,", "")})
        {
            assertFalse(body, WorkerResponseValidation.eventContinuationReady(202, body, "same-event"));
            assertFalse(body, WorkerResponseValidation.snapshotContinuationReady(202,
                body.replace("event_processing", "snapshot_processing").replace("event_id", "snapshot_id"), "same-event"));
        }
    }

    private static final String DEVICE = "fixture-device";
    private static final String OWNER = "owner@example.test";
    private static final String CASH = "{\"success\":true,\"cash\":{\"available\":1000," +
        "\"reserved\":20,\"available_plus_reserved\":1020,\"updated_at\":123}}";
    private static final String STATUS = "{\"success\":true,\"server_time\":123," +
        "\"device\":{\"active\":true,\"status\":\"active\",\"device_id\":\"fixture-device\"}," +
        "\"owner\":{\"email\":\"owner@example.test\"}}";
    private static final String HEARTBEAT = "{\"success\":true,\"heartbeat_at\":123," +
        "\"status\":\"active\",\"device_id\":\"fixture-device\",\"owner_email\":\"owner@example.test\"}";

    @Test
    public void acceptsCompleteExistingWorkerContractsAndCanonicalOwnerMatching()
    {
        assertTrue(WorkerResponseValidation.cash(CASH));
        assertTrue(WorkerResponseValidation.status(STATUS, DEVICE, OWNER));
        assertTrue(WorkerResponseValidation.heartbeat(HEARTBEAT, DEVICE, OWNER));
        assertTrue(WorkerResponseValidation.status(STATUS, DEVICE, " OWNER@EXAMPLE.TEST "));
        assertTrue(WorkerResponseValidation.heartbeat(HEARTBEAT, DEVICE, " OWNER@EXAMPLE.TEST "));
    }

    @Test
    public void emptyHtmlTruncatedAndMissingAcknowledgementsCannotCountAsSuccess()
    {
        for (String body : new String[] {null, "", "<html>Worker error</html>", "{\"success\":true",
            "[]", "null", "{}", "{\"success\":true}", "{\"success\":false}"})
        {
            assertFalse(String.valueOf(body), WorkerResponseValidation.cash(body));
            assertFalse(String.valueOf(body), WorkerResponseValidation.status(body, DEVICE, OWNER));
            assertFalse(String.valueOf(body), WorkerResponseValidation.heartbeat(body, DEVICE, OWNER));
        }
        for (String replacement : new String[] {"false", "\"true\"", "1", "null"})
        {
            assertFalse(WorkerResponseValidation.cash(CASH.replace("\"success\":true", "\"success\":" + replacement)));
            assertFalse(WorkerResponseValidation.status(STATUS.replace("\"success\":true", "\"success\":" + replacement), DEVICE, OWNER));
            assertFalse(WorkerResponseValidation.heartbeat(HEARTBEAT.replace("\"success\":true", "\"success\":" + replacement), DEVICE, OWNER));
        }
    }

    @Test
    public void cashRequiresWholeSafeNumbersAndAConsistentReservedTotal()
    {
        for (String replacement : new String[] {"null", "\"1000\"", "1000.5", "true", "{}", "9007199254740992"})
        {
            assertFalse(replacement, WorkerResponseValidation.cash(CASH.replace("\"available\":1000", "\"available\":" + replacement)));
        }
        assertFalse(WorkerResponseValidation.cash(CASH.replace("\"available_plus_reserved\":1020", "\"available_plus_reserved\":1000")));
        assertFalse(WorkerResponseValidation.cash(CASH.replace("\"reserved\":20", "\"reserved\":-20")));
        assertFalse(WorkerResponseValidation.cash(CASH.replace("\"updated_at\":123", "\"updated_at\":-1")));
        assertFalse(WorkerResponseValidation.cash(CASH.replace(",\"updated_at\":123", "")));
        assertTrue(WorkerResponseValidation.cash(CASH.replace("1000", "0").replace("1020", "20")));
    }

    @Test
    public void statusMustNameTheSameActiveDeviceAndOwnerWithAServerTimestamp()
    {
        assertFalse(WorkerResponseValidation.status(STATUS, "other-device", OWNER));
        assertFalse(WorkerResponseValidation.status(STATUS, DEVICE, "other@example.test"));
        assertFalse(WorkerResponseValidation.status(STATUS, DEVICE, null));
        assertFalse(WorkerResponseValidation.status(STATUS.replace("\"active\":true", "\"active\":false"), DEVICE, OWNER));
        assertFalse(WorkerResponseValidation.status(STATUS.replace("\"active\":true", "\"active\":\"true\""), DEVICE, OWNER));
        assertFalse(WorkerResponseValidation.status(STATUS.replace("\"status\":\"active\"", "\"status\":\"revoked\""), DEVICE, OWNER));
        for (String timestamp : new String[] {"0", "-1", "null", "\"123\"", "123.5"})
        {
            assertFalse(timestamp, WorkerResponseValidation.status(STATUS.replace("\"server_time\":123", "\"server_time\":" + timestamp), DEVICE, OWNER));
        }
        assertFalse(WorkerResponseValidation.status(STATUS.replace("\"device_id\":\"fixture-device\"", "\"device_id\":123"), DEVICE, OWNER));
        assertFalse(WorkerResponseValidation.status(STATUS.replace("\"email\":\"owner@example.test\"", "\"email\":false"), DEVICE, OWNER));
    }

    @Test
    public void heartbeatMustConfirmTheCurrentIdentityAndAnActualHeartbeatTime()
    {
        assertFalse(WorkerResponseValidation.heartbeat(HEARTBEAT, "other-device", OWNER));
        assertFalse(WorkerResponseValidation.heartbeat(HEARTBEAT, DEVICE, "other@example.test"));
        assertFalse(WorkerResponseValidation.heartbeat(HEARTBEAT, DEVICE, null));
        assertFalse(WorkerResponseValidation.heartbeat(HEARTBEAT.replace("\"status\":\"active\"", "\"status\":\"revoked\""), DEVICE, OWNER));
        for (String timestamp : new String[] {"0", "-1", "null", "\"123\"", "123.5"})
        {
            assertFalse(timestamp, WorkerResponseValidation.heartbeat(HEARTBEAT.replace("\"heartbeat_at\":123", "\"heartbeat_at\":" + timestamp), DEVICE, OWNER));
        }
        assertFalse(WorkerResponseValidation.heartbeat(HEARTBEAT.replace("\"device_id\":\"fixture-device\"", "\"device_id\":123"), DEVICE, OWNER));
        assertFalse(WorkerResponseValidation.heartbeat(HEARTBEAT.replace("\"owner_email\":\"owner@example.test\"", "\"owner_email\":false"), DEVICE, OWNER));
    }
}
